def _inputs_current_landing_context() -> str:
    """Scope local landing-card mode choices to the current client/project/beam."""
    try:
        cid = str(get_client_id() or "")
    except Exception:
        cid = ""
    return "|".join(
        [
            cid,
            str(st.session_state.get("active_project_id") or ""),
            str(st.session_state.get("active_beam_id") or ""),
        ]
    )


def _inputs_same_page_rerun_has_non_landing_state() -> bool:
    """True when a same-page rerun should not flash the empty landing card."""
    dispatch_state = st.session_state.get(_INPUTS_SAME_PAGE_ROOT_DISPATCH_ACTIVE_KEY)
    if not dispatch_state:
        return False
    cached_results = st.session_state.get(RESULT_CACHE_KEY)
    if isinstance(cached_results, dict) and bool(cached_results):
        return True
    bundle = st.session_state.get("_design_guide_debug_bundle")
    if isinstance(bundle, dict):
        verifier = dict(bundle.get("final_publication_verifier_payload") or {})
        render_trace = dict(bundle.get("design_guide_render_eligibility_trace") or {})
        overview = dict(bundle.get("current_overview") or bundle.get("overview") or {})
        if any(
            bool(value)
            for value in (
                verifier.get("publication_hash"),
                verifier.get("selected_family_id"),
                verifier.get("outcome_state"),
                render_trace.get("contract_required_design_brain_eligibility"),
                overview.get("all_key_pass"),
                overview.get("any_fail"),
                bundle.get("active_failures"),
                bundle.get("active_failure_keys"),
            )
        ):
            return True
    return False


def inputs_show_landing_dashboard() -> bool:
    """
    True when there are no ULS design actions and no line UDL loads (g+q).
    Design mode (Fast vs Detailed) does not hide the card.
    Uses existing session / shared state via get_param (no new state keys for detection).
    """
    if _inputs_same_page_rerun_has_non_landing_state():
        return False
    M_u = float(get_param("uls_Mstar", 0.0) or 0.0)
    V_u = float(get_param("uls_Vstar", 0.0) or 0.0)
    M_sls = float(get_param("sls_Mstar", 0.0) or 0.0)
    V_sls = float(get_param("sls_Vstar", 0.0) or 0.0)
    N_sls = float(get_param("sls_Nstar", 0.0) or 0.0)
    Tu = float(get_param("Tu_star", 0.0) or 0.0)
    Nu = float(get_param("uls_Nstar", 0.0) or get_param("N_star", 0.0) or 0.0)
    Pu = float(get_param("P_star", 0.0) or 0.0)
    g_udl = float(get_param("g_udl_kNm_per_m", 0.0) or 0.0)
    q_udl = float(get_param("q_udl_kNm_per_m", 0.0) or 0.0)

    no_design_actions = (
        abs(M_u) < 1e-15 and
        abs(V_u) < 1e-15 and
        abs(M_sls) < 1e-15 and
        abs(V_sls) < 1e-15 and
        abs(N_sls) < 1e-15 and
        abs(Tu) < 1e-15 and
        abs(Nu) < 1e-15 and
        abs(Pu) < 1e-15
    )
    no_loads = abs(g_udl) < 1e-15 and abs(q_udl) < 1e-15
    capacity_context_matches = (
        bool(st.session_state.get(_INPUTS_CAPACITY_ONLY_VIEW_KEY, False))
        and str(st.session_state.get(_INPUTS_CAPACITY_ONLY_CONTEXT_KEY) or "")
        == _inputs_current_landing_context()
    )
    if st.session_state.get(_INPUTS_CAPACITY_ONLY_VIEW_KEY, False) and not capacity_context_matches:
        st.session_state.pop(_INPUTS_CAPACITY_ONLY_VIEW_KEY, None)
        st.session_state.pop(_INPUTS_CAPACITY_ONLY_CONTEXT_KEY, None)
    if no_design_actions and no_loads:
        return not capacity_context_matches
    return False


def inputs_has_design_actions_or_loads() -> bool:
    """True once the Inputs page has real actions or generated/applied loads."""
    def _num(value) -> float:
        try:
            return float(value or 0.0)
        except Exception:
            return 0.0

    action_keys = (
        "uls_Mstar",
        "uls_Mstar_pos_manual",
        "uls_Mstar_neg_manual",
        "uls_Vstar",
        "uls_Nstar",
        "Tu_star",
        "N_star",
        "P_star",
        "sigma_sr",
        "sigma_s_sls",
        "sls_Mstar",
        "sls_Vstar",
        "g_udl_kNm_per_m",
        "q_udl_kNm_per_m",
        "load_Mstar_proxy",
        "load_Mstar_pos_proxy",
        "load_Mstar_neg_proxy",
        "load_Vstar_proxy",
        "load_Nstar_proxy",
        "inputs_load_Mstar_proxy",
        "inputs_load_Mstar_pos_proxy",
        "inputs_load_Mstar_neg_proxy",
        "inputs_load_Vstar_proxy",
        "inputs_load_Nstar_proxy",
        "inputs_Tu_star",
        "inputs_P_star",
    )
    return any(abs(_num(st.session_state.get(key, get_param(key, 0.0)))) >= 1e-15 for key in action_keys)


def should_render_design_guide_slot_from_publication_eligibility(
    *,
    inputs_has_design_actions_or_loads: bool,
    browser_test_mode: bool,
    debug_bundle: dict | None = None,
) -> dict:
    """Traceable render-slot eligibility for Design Guide publication states.

    The page gate can still render for normal action/load inputs, but it should
    not hide an already-materialized Design Brain family/blocker/publication
    state purely because action/load inputs are currently zero.
    """
    bundle = dict(debug_bundle or {})
    verifier = dict(bundle.get("final_publication_verifier_payload") or {})
    overview = dict(bundle.get("current_overview") or bundle.get("overview") or {})
    active_failures: set[str] = set()
    try:
        active_failures.update(_overview_active_failure_keys(overview) or set())
    except Exception:
        pass
    for source in (
        bundle.get("active_failures"),
        bundle.get("active_failure_keys"),
        verifier.get("active_failures"),
    ):
        if isinstance(source, (list, tuple, set)):
            active_failures.update(
                str(value).strip()
                for value in source
                if str(value or "").strip()
            )
        elif isinstance(source, dict):
            active_failures.update(
                str(key).strip()
                for key, value in source.items()
                if value and str(key or "").strip()
            )
    selected_family = str(
        verifier.get("selected_family_id")
        or verifier.get("selected_family")
        or bundle.get("selected_family_id")
        or bundle.get("selected_family")
        or bundle.get("published_family_id")
        or ""
    ).strip()
    outcome_state = str(
        verifier.get("outcome_state")
        or bundle.get("outcome_state")
        or bundle.get("final_publication_outcome_state")
        or ""
    ).strip()
    publication_hash = str(
        verifier.get("publication_hash")
        or bundle.get("publication_hash")
        or bundle.get("final_publication_publication_hash")
        or ""
    ).strip()
    exact_blockers = bundle.get("exact_blockers_by_family")
    blocker_state = bool(
        outcome_state == "BLOCKED"
        or selected_family in {"GEOMETRY_DETAILING_GOVERNS", "LOCKED_NO_REPAIR"}
        or bundle.get("blocked_reason")
        or bundle.get("blocker_reason")
        or (isinstance(exact_blockers, dict) and bool(exact_blockers))
    )
    invalid_input_state = bool(
        selected_family == "GEOMETRY_DETAILING_GOVERNS"
        or bundle.get("invalid_input_state")
        or bundle.get("invalid_geometry_state")
        or bundle.get("geometry_detailing_blocker")
    )
    current_page_gate_allows = bool(browser_test_mode or inputs_has_design_actions_or_loads)
    contract_required = bool(
        selected_family
        or active_failures
        or invalid_input_state
        or blocker_state
        or outcome_state
    )
    if current_page_gate_allows:
        classification = "A"
        reason = "page_gate_allows_render"
    elif contract_required:
        classification = "C"
        reason = "page_gate_blocks_contract_required_publication"
    else:
        classification = "B"
        reason = "page_gate_blocks_no_publication_reason"
    return {
        "schema": "design_guide_render_eligibility_decision.v1",
        "should_render_design_guide_slot": bool(current_page_gate_allows or contract_required),
        "current_page_gate_allows": current_page_gate_allows,
        "contract_required_design_brain_eligibility": contract_required,
        "inputs_has_design_actions_or_loads": bool(inputs_has_design_actions_or_loads),
        "browser_test_mode": bool(browser_test_mode),
        "selected_family_id": selected_family or None,
        "active_failures": sorted(active_failures),
        "invalid_input_state": bool(invalid_input_state),
        "blocker_state": bool(blocker_state),
        "final_publication_outcome_state": outcome_state or None,
        "final_publication_publication_hash": publication_hash or None,
        "render_eligibility_reason": reason,
        "render_eligibility_classification": classification,
    }


def _design_guide_pre_slot_publication_eligibility_probe(debug_bundle: dict | None = None) -> dict:
    """Cheap pre-slot signal for Design Guide render eligibility.

    This probe does not build recommendations or publication. It only gives the
    page-level slot gate enough already-available engineering state to avoid
    hiding an active failure/blocker behind the actions/load landing gate.
    """
    bundle = dict(debug_bundle or {})
    probe: dict = {
        "schema": "design_guide_pre_slot_publication_eligibility_probe.v1",
        "trace_only": True,
        "product_behaviour_changed": False,
        "source": "pre_slot_current_overview_and_existing_debug_bundle",
        "overview_source": None,
        "active_failures": [],
        "overview_available": False,
        "overview_probe_error": None,
    }
    overview = {}
    try:
        state = _shared_state_snapshot()
        overview = _collect_design_overview(
            state,
            context=_build_design_actions_context(state),
        )
        if isinstance(overview, dict) and overview:
            probe["overview_available"] = True
            probe["overview_source"] = "collect_design_overview_current_state"
    except Exception as exc:
        probe["overview_probe_error"] = f"{type(exc).__name__}: {exc}"
        overview = {}
    if isinstance(overview, dict) and overview:
        bundle["current_overview"] = dict(overview)
        bundle.setdefault("overview", dict(overview))
        try:
            probe["active_failures"] = sorted(_overview_active_failure_keys(overview) or set())
        except Exception as exc:
            probe["active_failure_probe_error"] = f"{type(exc).__name__}: {exc}"
    verifier = dict(bundle.get("final_publication_verifier_payload") or {})
    selected_family = str(
        verifier.get("selected_family_id")
        or verifier.get("selected_family")
        or bundle.get("selected_family_id")
        or bundle.get("selected_family")
        or bundle.get("published_family_id")
        or ""
    ).strip()
    outcome_state = str(
        verifier.get("outcome_state")
        or bundle.get("outcome_state")
        or bundle.get("final_publication_outcome_state")
        or ""
    ).strip()
    publication_hash = str(
        verifier.get("publication_hash")
        or bundle.get("publication_hash")
        or bundle.get("final_publication_publication_hash")
        or ""
    ).strip()
    probe.update(
        {
            "selected_family_id": selected_family or None,
            "final_publication_outcome_state": outcome_state or None,
            "final_publication_publication_hash": publication_hash or None,
            "contract_required_design_brain_eligibility": bool(
                selected_family
                or outcome_state
                or publication_hash
                or probe.get("active_failures")
                or bundle.get("blocked_reason")
                or bundle.get("blocker_reason")
            ),
        }
    )
    bundle["design_guide_pre_slot_publication_eligibility_probe"] = dict(probe)
    return {"debug_bundle": bundle, "probe": probe}


