def _bottom_reo_trace_float(value: object) -> float | None:
    try:
        if value is None:
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _bottom_reo_trace_int(value: object) -> int | None:
    try:
        if value is None:
            return None
        return int(float(value))
    except (TypeError, ValueError):
        return None


def _bottom_reo_candidate_identity(candidate: object, mode_config: dict | None = None) -> str | None:
    if not isinstance(candidate, dict):
        return None
    summary = _bottom_reo_recommendation_trace_candidate_summary(candidate, mode_config)
    candidate_id = summary.get("candidate_id")
    if candidate_id:
        return str(candidate_id)
    trace_hash = summary.get("hash")
    return f"trace:{trace_hash}" if trace_hash else None


def _bottom_reo_candidate_identities(candidates: object, mode_config: dict | None = None) -> tuple[str, ...]:
    values = list(candidates or []) if isinstance(candidates, (list, tuple)) else []
    return tuple(
        identity
        for identity in (
            _bottom_reo_candidate_identity(candidate, mode_config)
            for candidate in values
            if isinstance(candidate, dict)
        )
        if identity
    )


def _bottom_reo_selected_candidate_decision_record(
    *,
    filtered_candidates: object,
    ranked_candidates: object,
    filtered_candidate_identities: tuple[str, ...] | None = None,
    filtered_candidate_order_hash: str | None = None,
    selector_input_candidate: dict | None,
    selected_candidate: dict | None,
    selected_candidate_updates: dict | None = None,
    final_result_updates: dict | None = None,
    mode_config: dict | None,
    target_low: float | None,
    target_high: float | None,
    post_selector_guard_result: str,
    no_result_reason: str | None,
) -> BottomReoSelectedCandidateDecision:
    filtered_order = _bottom_reo_recommendation_trace_candidate_order(filtered_candidates, mode_config)
    ranked_order = _bottom_reo_recommendation_trace_candidate_order(ranked_candidates, mode_config)
    selected = dict(selected_candidate or {}) if isinstance(selected_candidate, dict) else {}
    selector_input = dict(selector_input_candidate or {}) if isinstance(selector_input_candidate, dict) else {}
    updates = dict(selected_candidate_updates if selected_candidate_updates is not None else selected.get("updates") or {})
    result_updates = dict(final_result_updates or {})
    overview = dict(selected.get("overview") or {})
    utils = dict(overview.get("utils") or {})
    selector_input_identity = _bottom_reo_candidate_identity(selector_input, mode_config) if selector_input else None
    selector_output_identity = _bottom_reo_candidate_identity(selected, mode_config) if selected else None
    return BottomReoSelectedCandidateDecision(
        filtered_candidate_identities=(
            tuple(filtered_candidate_identities)
            if filtered_candidate_identities is not None
            else _bottom_reo_candidate_identities(filtered_candidates, mode_config)
        ),
        filtered_candidate_order_hash=filtered_candidate_order_hash or filtered_order.get("order_hash"),
        ranked_candidate_identities=_bottom_reo_candidate_identities(ranked_candidates, mode_config),
        ranked_candidate_order_hash=ranked_order.get("order_hash"),
        selected_candidate_id=selected.get("candidate_id") or selected.get("source_candidate_id") or None,
        selected_candidate_identity=selector_output_identity,
        selected_candidate_trace_hash=(
            _bottom_reo_recommendation_trace_candidate_summary(selected, mode_config).get("hash")
            if selected
            else None
        ),
        selected_family_tag=selected.get("recommendation_family_tag") or None,
        selected_candidate_update_keys=tuple(sorted(str(key) for key in updates.keys())),
        selected_candidate_updates_hash=_dg_runtime_trace_hash(updates) if selected else None,
        final_result_update_keys=tuple(sorted(str(key) for key in result_updates.keys())),
        final_result_updates_hash=_dg_runtime_trace_hash(result_updates) if final_result_updates is not None else None,
        selector_input_candidate_id=selector_input.get("candidate_id") or selector_input.get("source_candidate_id") or None,
        selector_output_candidate_id=selected.get("candidate_id") or selected.get("source_candidate_id") or None,
        selector_input_candidate_identity=selector_input_identity,
        selector_output_candidate_identity=selector_output_identity,
        compound_preference_changed=bool(
            selector_input_identity
            and selector_output_identity
            and selector_input_identity != selector_output_identity
        ),
        compound_preference_selected=bool(selected.get("recommendation_compound")),
        post_selector_guard_result=str(post_selector_guard_result or ""),
        no_result_reason=str(no_result_reason) if no_result_reason else None,
        selected_score=_bottom_reo_trace_float(selected.get("score")),
        selected_bending_util=_bottom_reo_trace_float(utils.get("bending")),
        selected_candidate_post_util=(
            _bottom_reo_trace_float(selected.get("candidate_post_util"))
        ),
        target_low=_bottom_reo_trace_float(target_low),
        target_high=_bottom_reo_trace_float(target_high),
        selected_reaches_target_band=(
            bool(selected.get("candidate_reaches_target_band"))
            if selected.get("candidate_reaches_target_band") is not None
            else None
        ),
        selected_distance_to_target_band=(
            _bottom_reo_trace_float(selected.get("candidate_distance_to_target_band"))
        ),
        selected_because_reaches_band=(
            bool(selected.get("winning_candidate_selected_because_reaches_band"))
            if selected.get("winning_candidate_selected_because_reaches_band") is not None
            else None
        ),
    )


def _bottom_reo_selector_result_record(
    *,
    selected_candidate: dict | None,
    mode_config: dict | None,
    target_low: float | None,
    target_high: float | None,
    status: str,
    selected_reason: str | None,
    no_candidate_reason: str | None,
    strict_band_winner_seen: bool,
    strict_band_winner_accepted: bool,
    strict_band_rejected_reason: str | None,
    legacy_rejection_reason: str | None,
) -> BottomReoSelectorResult:
    return _build_bottom_reo_selector_result_record_from_candidate(
        selected_candidate=selected_candidate if isinstance(selected_candidate, dict) else None,
        status=status,
        selected_reason=selected_reason,
        no_candidate_reason=no_candidate_reason,
        strict_band_winner_seen=strict_band_winner_seen,
        strict_band_winner_accepted=strict_band_winner_accepted,
        strict_band_rejected_reason=strict_band_rejected_reason,
        legacy_rejection_reason=legacy_rejection_reason,
        target_low=target_low,
        target_high=target_high,
    )


def _bottom_reo_trace_ranking_result_boundary(decision: dict) -> dict:
    ranked = [str(value) for value in list(decision.get("ranked_candidate_identities") or [])]
    selected_identity = decision.get("selected_candidate_identity") or None
    ordered_hash = decision.get("ranked_candidate_order_hash") or _dg_runtime_trace_hash(ranked)
    policy_inputs = [
        {
            "policy_input_hash": _dg_runtime_trace_hash(
                {
                    "source": "selected_recommendation_handoff_ranked_identity",
                    "index": index,
                    "candidate_identity": identity,
                }
            ),
        }
        for index, identity in enumerate(ranked)
    ]
    ranking_decisions = []
    for identity in ranked:
        if selected_identity and str(identity) == str(selected_identity):
            ranking_decisions.append(
                {
                    "candidate_identity": identity,
                    "decision": "selected_by_page_local_selector",
                }
            )
        else:
            ranking_decisions.append(
                {
                    "candidate_identity": identity,
                    "decision": "ranked_available_before_selection",
                }
            )
    callback_handoff_hash = _dg_runtime_trace_hash(
        {
            "source": "selected_recommendation_handoff_trace",
            "ranked_candidate_order_hash": ordered_hash,
            "selector_input_candidate_identity": decision.get("selector_input_candidate_identity"),
            "selector_output_candidate_identity": decision.get("selector_output_candidate_identity"),
        }
    )
    return _build_bottom_reo_ranking_result_boundary(
        policy_inputs=policy_inputs,
        ordered_identities=ranked,
        kept_identities=ranked,
        pruned_identities=[],
        ranking_decisions=ranking_decisions,
        ordered_hash=ordered_hash,
        kept_hash=_dg_runtime_trace_hash(ranked),
        pruned_hash=_dg_runtime_trace_hash([]),
        callback_handoff_hash=callback_handoff_hash,
    ).to_dict()


def _bottom_reo_trace_guard_surface(decision: dict, selector: dict) -> dict:
    return {
        "strict_band": {
            "winner_seen": bool(selector.get("strict_band_winner_seen")),
            "winner_accepted": bool(selector.get("strict_band_winner_accepted")),
            "rejected_reason": selector.get("strict_band_rejected_reason"),
            "legacy_rejection_reason": selector.get("legacy_rejection_reason"),
            "selected_reason": selector.get("selected_reason"),
            "no_candidate_reason": selector.get("no_candidate_reason"),
        },
        "noop_or_improvement": {
            "selector_status": selector.get("status"),
            "selected_reason": selector.get("selected_reason"),
            "no_candidate_reason": selector.get("no_candidate_reason"),
            "legacy_rejection_reason": selector.get("legacy_rejection_reason"),
        },
        "compound_preference": {
            "changed": bool(decision.get("compound_preference_changed")),
            "selected": bool(decision.get("compound_preference_selected")),
            "selector_input_candidate_identity": decision.get("selector_input_candidate_identity"),
            "selector_output_candidate_identity": decision.get("selector_output_candidate_identity"),
        },
        "post_selector_guard": {
            "result": decision.get("post_selector_guard_result"),
            "no_result_reason": decision.get("no_result_reason"),
        },
    }


def _bottom_reo_trace_proof_payload(
    *,
    result: dict | None,
    decision: BottomReoSelectedCandidateDecision,
    selector_result: BottomReoSelectorResult | None,
    return_status: str,
    return_reason: str,
    include_selected_recommendation_proof: bool,
) -> dict:
    decision_d = decision.to_dict()
    selector_d = selector_result.to_dict() if selector_result else {}
    ranking_result_boundary = _bottom_reo_trace_ranking_result_boundary(decision_d)
    guard_surface = _bottom_reo_trace_guard_surface(decision_d, selector_d)
    trace_scenario = str(os.environ.get("DESIGN_GUIDE_RUNTIME_TRACE_SCENARIO") or "").strip()
    trace_scenario = (
        trace_scenario.removeprefix("BOTTOM_REO_SELECTED_RECOMMENDATION_")
        if trace_scenario.startswith("BOTTOM_REO_SELECTED_RECOMMENDATION_")
        else None
    )
    return _build_bottom_reo_trace_proof_payload_projection(
        result=result,
        decision=decision_d,
        selector_result=selector_d,
        ranking_result_boundary=ranking_result_boundary,
        guard_surface=guard_surface,
        return_status=return_status,
        return_reason=return_reason,
        include_selected_recommendation_proof=include_selected_recommendation_proof,
        trace_scenario=trace_scenario,
    )


def _emit_bottom_reo_selected_recommendation_return_trace(
    *,
    result: dict | None,
    state: dict,
    generated_candidates: object,
    filtered_candidates: object,
    ranked_candidates: object,
    selector_input_candidate: dict | None,
    selected_candidate: dict | None,
    selected_candidate_updates: dict | None = None,
    final_result_updates: dict | None = None,
    mode_config: dict | None,
    target_low: float | None,
    target_high: float | None,
    post_selector_guard_result: str,
    no_result_reason: str | None,
    selector_status: str,
    selected_reason: str | None,
    no_candidate_reason: str | None,
    strict_band_winner_seen: bool = False,
    strict_band_winner_accepted: bool = False,
    strict_band_rejected_reason: str | None = None,
    legacy_rejection_reason: str | None = None,
    reject_skip_reasons: dict | None = None,
    return_status: str = "none",
    return_reason: str = "",
) -> None:
    if not _dg_runtime_trace_enabled():
        return
    generated_order = _bottom_reo_recommendation_trace_candidate_order(generated_candidates, mode_config)
    filtered_order = _bottom_reo_recommendation_trace_candidate_order(filtered_candidates, mode_config)
    ranked_order = _bottom_reo_recommendation_trace_candidate_order(ranked_candidates, mode_config)
    _bottom_reo_recommendation_trace_event(
        "bottom_reo_selected_recommendation_candidates",
        candidate_order=generated_order,
        candidate_order_hash=generated_order.get("order_hash"),
        candidate_count=generated_order.get("count"),
        raw_candidate_count=generated_order.get("count"),
        raw_candidate_order_hash=generated_order.get("order_hash"),
        filtered_candidate_count=filtered_order.get("count"),
        filtered_candidate_order_hash=filtered_order.get("order_hash"),
    )
    decision = _bottom_reo_selected_candidate_decision_record(
        filtered_candidates=filtered_candidates,
        ranked_candidates=ranked_candidates,
        filtered_candidate_order_hash=filtered_order.get("order_hash"),
        selector_input_candidate=selector_input_candidate,
        selected_candidate=selected_candidate,
        selected_candidate_updates=selected_candidate_updates,
        final_result_updates=final_result_updates,
        mode_config=mode_config,
        target_low=target_low,
        target_high=target_high,
        post_selector_guard_result=post_selector_guard_result,
        no_result_reason=no_result_reason,
    )
    selector_result = _bottom_reo_selector_result_record(
        selected_candidate=selected_candidate,
        mode_config=mode_config,
        target_low=target_low,
        target_high=target_high,
        status=selector_status,
        selected_reason=selected_reason,
        no_candidate_reason=no_candidate_reason,
        strict_band_winner_seen=strict_band_winner_seen,
        strict_band_winner_accepted=strict_band_winner_accepted,
        strict_band_rejected_reason=strict_band_rejected_reason,
        legacy_rejection_reason=legacy_rejection_reason,
    )
    decision_payload = decision.to_dict()
    selector_payload = selector_result.to_dict()
    selected_candidate_summary = (
        _bottom_reo_recommendation_trace_candidate_summary(selected_candidate, mode_config)
        if isinstance(selected_candidate, dict)
        else {}
    )
    selected_update_keys = sorted(str(key) for key in dict(selected_candidate_updates or {}).keys())
    final_update_keys = sorted(str(key) for key in dict(final_result_updates or {}).keys())
    reject_reasons = dict(reject_skip_reasons or {})
    if no_result_reason and "no_result_reason" not in reject_reasons:
        reject_reasons["no_result_reason"] = no_result_reason
    pool_boundary = _bottom_reo_candidate_pool_boundary_record(
        state=state,
        generated_candidates=generated_candidates,
        filtered_candidates=filtered_candidates,
        ranked_candidates=ranked_candidates,
        selected_candidate=selected_candidate,
        mode_config=mode_config,
        target_low=target_low,
        target_high=target_high,
        reject_skip_reasons=reject_reasons,
        source_family_runtime_id="normal_bottom_reo_recommendation",
        generated_candidate_order_hash=generated_order.get("order_hash"),
        filtered_candidate_order_hash=filtered_order.get("order_hash"),
    ).to_dict()
    trace_payload = _bottom_reo_trace_proof_payload(
        result=result,
        decision=decision,
        selector_result=selector_result,
        return_status=return_status,
        return_reason=return_reason,
        include_selected_recommendation_proof=bool(result and selected_candidate),
    )
    _bottom_reo_recommendation_trace_event(
        "bottom_reo_selected_recommendation_return",
        status=return_status,
        return_reason=return_reason,
        result=_bottom_reo_recommendation_trace_result_summary(result),
        ranked_candidate_count=ranked_order.get("count"),
        ranked_candidate_order_hash=ranked_order.get("order_hash"),
        selected_candidate_hash=selected_candidate_summary.get("hash"),
        selected_candidate_id=selected_candidate_summary.get("candidate_id"),
        selected_candidate_update_keys=selected_update_keys,
        selected_candidate_update_keys_json=json.dumps(
            selected_update_keys,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        final_result_update_keys=final_update_keys,
        selected_candidate_decision=decision_payload,
        selected_candidate_decision_json=json.dumps(
            decision_payload,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        candidate_pool_boundary=pool_boundary,
        candidate_pool_boundary_json=json.dumps(
            pool_boundary,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        selector_result=selector_payload,
        selector_result_json=json.dumps(
            selector_payload,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        **trace_payload,
    )


def _bottom_reo_candidate_pool_boundary_record(
    *,
    state: dict,
    generated_candidates: object,
    filtered_candidates: object,
    ranked_candidates: object,
    selected_candidate: dict | None,
    mode_config: dict | None,
    target_low: float | None,
    target_high: float | None,
    reject_skip_reasons: dict | None,
    source_family_runtime_id: str,
    generated_candidate_order_hash: str | None = None,
    filtered_candidate_order_hash: str | None = None,
) -> BottomReoCandidatePoolBoundary:
    generated_order = _bottom_reo_recommendation_trace_candidate_order(generated_candidates, mode_config)
    filtered_order = _bottom_reo_recommendation_trace_candidate_order(filtered_candidates, mode_config)
    ranked_order = _bottom_reo_recommendation_trace_candidate_order(ranked_candidates, mode_config)
    selected = dict(selected_candidate or {}) if isinstance(selected_candidate, dict) else {}
    selected_summary = (
        _bottom_reo_recommendation_trace_candidate_summary(selected, mode_config)
        if selected
        else {}
    )
    selected_updates = dict(selected.get("updates") or {})
    selected_overview = dict(selected.get("overview") or {})
    selected_utils = dict(selected_overview.get("utils") or {})
    bottom_layout = {
        "label": _bottom_reo_state_label(state),
        "bot1_count": _int_from_state(state, "bot1_count", 0),
        "bot2_count": _int_from_state(state, "bot2_count", 0),
        "db_bot_1": _int_from_state(state, "db_bot_1", 0),
        "db_bot_2": _int_from_state(state, "db_bot_2", _int_from_state(state, "db_bot_1", 0)),
        "bot_row_count": _int_from_state(state, "bot_row_count", 1),
    }
    band_reachers = [
        item
        for item in list(filtered_candidates or [])
        if isinstance(item, dict) and bool(item.get("candidate_reaches_target_band"))
    ]
    return _build_bottom_reo_candidate_pool_boundary(
        input_state_hash=_dg_runtime_trace_hash(state),
        current_bottom_reo_layout=bottom_layout,
        generated_candidate_count=int(generated_order.get("count") or 0),
        generated_candidate_ids=_bottom_reo_candidate_identities(generated_candidates, mode_config),
        generated_candidate_order_hash=generated_candidate_order_hash or generated_order.get("order_hash"),
        filtered_candidate_count=int(filtered_order.get("count") or 0),
        filtered_candidate_ids=_bottom_reo_candidate_identities(filtered_candidates, mode_config),
        filtered_candidate_order_hash=filtered_candidate_order_hash or filtered_order.get("order_hash"),
        ranked_candidate_count=int(ranked_order.get("count") or 0),
        ranked_candidate_ids=_bottom_reo_candidate_identities(ranked_candidates, mode_config),
        ranked_candidate_order_hash=ranked_order.get("order_hash"),
        selected_candidate_id=(
            selected.get("candidate_id")
            or selected.get("source_candidate_id")
            or selected_summary.get("candidate_id")
            or None
        ),
        selected_update_payload=selected_updates,
        selected_util_surfaces={
            "score": selected_summary.get("score") if selected_summary else None,
            "bending_util": selected_utils.get("bending"),
            "worst_util": (
                selected.get("worst_util")
                or selected_overview.get("worst_util")
                or selected_overview.get("governing_util")
            ),
            "candidate_post_util": selected.get("candidate_post_util"),
            "actual_ast": selected.get("actual_ast") or selected.get("Ast_bot"),
        },
        reject_skip_reasons=dict(reject_skip_reasons or {}),
        target_band_status={
            "target_low": _bottom_reo_trace_float(target_low),
            "target_high": _bottom_reo_trace_float(target_high),
            "selected_reaches_target_band": (
                bool(selected.get("candidate_reaches_target_band"))
                if selected.get("candidate_reaches_target_band") is not None
                else None
            ),
            "selected_distance_to_target_band": _bottom_reo_trace_float(
                selected.get("candidate_distance_to_target_band"),
            ),
            "band_reacher_count": len(band_reachers),
        },
        source_family_runtime_id=str(source_family_runtime_id or "normal_bottom_reo_recommendation"),
    )


def _bottom_reo_evaluated_filter_arrangement_record(
    *,
    order_index: int,
    band: int,
    arrangement: dict,
    updates: dict,
) -> dict:
    arrangement_summary = {
        "bot1_count": _bottom_reo_trace_int(arrangement.get("bot1_count")),
        "bot2_count": _bottom_reo_trace_int(arrangement.get("bot2_count")),
        "db_bot_1": _bottom_reo_trace_int(arrangement.get("db_bot_1")),
        "db_bot_2": _bottom_reo_trace_int(arrangement.get("db_bot_2")),
        "bot_row_count": _bottom_reo_trace_int(arrangement.get("bot_row_count")),
        "spacing_bot_1": _bottom_reo_trace_float(arrangement.get("spacing_bot_1")),
        "spacing_bot_2": _bottom_reo_trace_float(arrangement.get("spacing_bot_2")),
        "spec": arrangement.get("spec"),
    }
    signature = (
        f"{arrangement_summary.get('bot1_count')}:"
        f"{arrangement_summary.get('bot2_count')}:"
        f"{arrangement_summary.get('db_bot_1')}:"
        f"{arrangement_summary.get('db_bot_2')}:"
        f"{arrangement_summary.get('bot_row_count')}"
    )
    return _build_bottom_reo_evaluated_candidate_filter_record(
        order_index=int(order_index),
        band=int(band),
        arrangement_identity=arrangement_summary,
        arrangement_signature=signature,
        arrangement_update_keys=tuple(sorted((updates or {}).keys())),
        arrangement_update_payload_hash=_dg_runtime_trace_hash(updates or {}),
        evaluator_returned=None,
        status="pending_evaluation",
        reject_reason=None,
        accepted_prerank_candidate_identity=None,
        candidate_update_keys=(),
        candidate_update_payload_hash=None,
        utilisation_summary={},
        target_band_status={},
    ).to_dict()


def _bottom_reo_evaluated_filter_candidate_surface(candidate: dict | None) -> dict:
    if not isinstance(candidate, dict):
        return {
            "candidate_identity": None,
            "candidate_update_keys": (),
            "candidate_update_payload_hash": None,
            "utilisation_summary": {},
        }
    updates = dict(candidate.get("updates") or {})
    overview = dict(candidate.get("overview") or {})
    utils = dict(overview.get("utils") or {})
    util_summary = {
        "bending_util": _bottom_reo_trace_float(utils.get("bending")),
        "worst_util": _bottom_reo_trace_float(
            candidate.get("worst_util")
            or overview.get("worst_util")
            or overview.get("governing_util")
        ),
        "candidate_post_util": _bottom_reo_trace_float(candidate.get("candidate_post_util")),
        "is_compliant": (
            bool(overview.get("is_compliant"))
            if overview.get("is_compliant") is not None
            else None
        ),
        "actual_ast": _bottom_reo_trace_float(candidate.get("actual_ast") or candidate.get("Ast_bot")),
    }
    identity_surface = {
        "candidate_id": candidate.get("candidate_id") or candidate.get("source_candidate_id"),
        "updates": updates,
        "utilisation": util_summary,
    }
    candidate_identity = (
        candidate.get("candidate_id")
        or candidate.get("source_candidate_id")
        or _dg_runtime_trace_hash(identity_surface)
    )
    return {
        "candidate_identity": str(candidate_identity) if candidate_identity is not None else None,
        "candidate_update_keys": tuple(sorted(updates.keys())),
        "candidate_update_payload_hash": _dg_runtime_trace_hash(updates),
        "utilisation_summary": util_summary,
    }


def _bottom_reo_update_evaluated_filter_record(
    records: list[dict] | None,
    record_index: int | None,
    *,
    candidate: dict | None = None,
    status: str,
    reject_reason: str | None = None,
    evaluator_returned: bool | None = None,
) -> None:
    if records is None or record_index is None:
        return
    if record_index < 0 or record_index >= len(records):
        return
    surface = _bottom_reo_evaluated_filter_candidate_surface(candidate)
    record = records[record_index]
    rebuilt: BottomReoEvaluatedCandidateFilterRecord = _build_bottom_reo_evaluated_candidate_filter_record(
        order_index=int(record.get("order_index", record_index) or record_index),
        band=int(record.get("band", 0) or 0),
        arrangement_identity=dict(record.get("arrangement") or {}),
        arrangement_signature=record.get("arrangement_signature"),
        arrangement_update_keys=tuple(record.get("arrangement_update_keys") or ()),
        arrangement_update_payload_hash=record.get("arrangement_update_payload_hash"),
        evaluator_returned=evaluator_returned,
        status=status,
        reject_reason=reject_reason,
        accepted_prerank_candidate_identity=(
            surface.get("candidate_identity") if status == "accepted_prerank" else None
        ),
        candidate_update_keys=tuple(surface.get("candidate_update_keys") or ()),
        candidate_update_payload_hash=surface.get("candidate_update_payload_hash"),
        utilisation_summary=dict(surface.get("utilisation_summary") or {}),
        target_band_status=dict(record.get("target_band_status") or {}),
    )
    record.clear()
    record.update(rebuilt.to_dict())


def _bottom_reo_evaluated_candidate_filter_boundary_record(
    *,
    records: list[dict],
    input_arrangement_pool_hash: str | None,
    source_family_runtime_id: str,
) -> BottomReoEvaluatedCandidateFilterBoundary:
    return _build_bottom_reo_evaluated_candidate_filter_boundary(
        records=records,
        input_arrangement_pool_hash=input_arrangement_pool_hash,
        source_family_runtime_id=source_family_runtime_id,
    )


def _compute_late_evidence_rehydration_rewrite_probe(label: str, items: object, debug_trace: dict) -> None:
    if not _dg_runtime_trace_enabled():
        return
    item_list = list(items or []) if isinstance(items, (list, tuple)) else []
    primary = item_list[0] if item_list and isinstance(item_list[0], dict) else {}
    contract = dict(primary.get("button_contract") or {})
    action_payload = dict(primary.get("action_payload") or {})
    resolved_candidate = dict(primary.get("resolved_candidate") or {})
    evidence = dict(
        primary.get("candidate_search_evidence")
        or action_payload.get("candidate_search_evidence")
        or resolved_candidate.get("candidate_search_evidence")
        or {}
    )
    title_text = " ".join(
        str(part or "")
        for part in (
            primary.get("title_main"),
            primary.get("title"),
            primary.get("secondary_action"),
            primary.get("reasoning"),
        )
    ).lower()
    updates = dict(
        evidence.get("best_safe_candidate_updates")
        or evidence.get("selected_candidate_updates")
        or evidence.get("closest_safe_candidate_updates")
        or contract.get("updates")
        or action_payload.get("updates")
        or resolved_candidate.get("updates")
        or {}
    )
    _compute_guidance_trace_event(
        "late_evidence_rehydration_rewrite_probe",
        label=str(label or ""),
        primary=_dg_runtime_trace_item_summary(primary),
        primary_title=primary.get("title_main") or primary.get("title"),
        primary_status=primary.get("status"),
        primary_intent=primary.get("guidance_intent"),
        primary_action_type=primary.get("action_type") or contract.get("action_type"),
        title_has_final_threshold=("shear cleanup blocked by final efficiency threshold" in title_text),
        evidence_hash=_dg_runtime_trace_hash(evidence),
        evidence_keys=sorted(str(k) for k in evidence.keys())[:80],
        evidence_selected_candidate_id=evidence.get("selected_candidate_id"),
        evidence_best_safe_candidate_id=evidence.get("best_safe_candidate_id"),
        evidence_one_click_target=bool(evidence.get("one_click_target_reaching_candidate_exists")),
        evidence_accepted_band_count=int(evidence.get("accepted_band_candidate_count") or 0),
        action_payload_hash=_dg_runtime_trace_hash(action_payload),
        resolved_candidate_hash=_dg_runtime_trace_hash(resolved_candidate),
        button_contract_hash=_dg_runtime_trace_hash(contract),
        button_contract_actionable=contract.get("actionable"),
        button_contract_enabled=contract.get("enabled"),
        button_contract_preview_pass=contract.get("preview_pass"),
        button_contract_blocking_reason=contract.get("blocking_reason"),
        updates_hash=_dg_runtime_trace_hash(updates),
        updates_keys=sorted(str(k) for k in updates.keys())[:40],
        has_shear_update_keys=bool(set(updates) & _COMPOUND_SHEAR_UPDATE_KEYS),
        has_bottom_update_keys=bool(set(updates) & _COMPOUND_BOTTOM_UPDATE_KEYS),
        debug_branch=debug_trace.get("guidance_branch") if isinstance(debug_trace, dict) else None,
        debug_evidence_hash=_dg_runtime_trace_hash((debug_trace or {}).get("candidate_search_evidence") or {}),
        debug_exact_blockers_hash=_dg_runtime_trace_hash((debug_trace or {}).get("exact_blockers_by_family") or {}),
    )


def _compute_late_evidence_sync_result_record(result: DesignGuideComputeLateEvidenceSyncResult) -> None:
    if not _dg_runtime_trace_enabled():
        return
    configured = str(os.environ.get("DESIGN_GUIDE_COMPUTE_LATE_EVIDENCE_SYNC_RESULT_PATH") or "").strip()
    if not configured:
        return
    path = configured
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    row = {
        "event": "compute_late_evidence_sync_typed_result",
        "function": "_compute_design_guidance_items",
        "pid": os.getpid(),
        "scenario": os.environ.get("DESIGN_GUIDE_RUNTIME_TRACE_SCENARIO"),
        "timestamp": datetime.utcnow().isoformat(timespec="milliseconds") + "Z",
        "typed_result": result.to_dict(),
    }
    with open(path, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(row, default=str, sort_keys=True) + "\n")


def _apply_button_binding_tail_trace_enabled() -> bool:
    return str(os.environ.get("DESIGN_GUIDE_APPLY_BUTTON_BINDING_TAIL_TRACE") or "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _apply_button_binding_tail_trace_path() -> str:
    configured = str(os.environ.get("DESIGN_GUIDE_APPLY_BUTTON_BINDING_TAIL_TRACE_PATH") or "").strip()
    if configured:
        return configured
    stamp = str(os.environ.get("DESIGN_GUIDE_APPLY_BUTTON_BINDING_TAIL_TRACE_STAMP") or "").strip()
    if not stamp:
        stamp = datetime.now().strftime("%Y-%m-%dT%H-%M-%S")
    return os.path.join(
        "artifacts",
        "traces",
        f"apply_button_binding_tail_trace_7CD_{stamp}_{os.getpid()}.jsonl",
    )


