def _design_guide_publication_fp_value(value):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return tuple(
            (str(k), _design_guide_publication_fp_value(v))
            for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))
        )
    if isinstance(value, (list, tuple, set)):
        return tuple(_design_guide_publication_fp_value(v) for v in value)
    return str(value)


def _design_guide_canonical_effective_depth_for_publication(source: dict | None) -> float | None:
    """Return the stable derived d used only for Design Guide payload freshness."""
    s = dict(source or {})
    try:
        D = float(s.get("D", 0.0) or 0.0)
        cover_bot = float(s.get("cover_bot", 0.0) or 0.0)
        lig_d = float(s.get("lig_d", 0.0) or 0.0)
    except (TypeError, ValueError):
        return None
    if D <= 0.0:
        return None
    primary_bar_dia = 0.0
    for row in (1, 2, 3, 4):
        count_raw = s.get(f"bot_row_{row}_bars", s.get(f"bot{row}_count", 0))
        try:
            row_active = int(float(count_raw or 0)) > 0
        except (TypeError, ValueError):
            row_active = bool(count_raw)
        if not row_active:
            continue
        dia_raw = s.get(f"bot_row_{row}_dia", s.get(f"db_bot_{row}", 0.0))
        try:
            dia = float(dia_raw or 0.0)
        except (TypeError, ValueError):
            dia = 0.0
        if dia > 0.0:
            primary_bar_dia = dia
            break
    if primary_bar_dia <= 0.0:
        for key in ("bot_row_1_dia", "db_bot_1", "db_bot"):
            try:
                primary_bar_dia = float(s.get(key, 0.0) or 0.0)
            except (TypeError, ValueError):
                primary_bar_dia = 0.0
            if primary_bar_dia > 0.0:
                break
    return float(
        effective_depth_with_links_mm(
            D_mm=D,
            cover_to_ligs_mm=cover_bot,
            lig_diameter_mm=lig_d,
            bar_diameter_mm=primary_bar_dia,
        )
    )


def _design_guide_publication_state_payload(state: dict | None) -> dict:
    source = dict(state or {})
    for row in (2, 3, 4):
        bot_count = source.get(f"bot{row}_count", source.get(f"bot_row_{row}_bars", 0))
        try:
            bot_active = int(bot_count or 0) > 0
        except Exception:
            bot_active = bool(bot_count)
        if not bot_active:
            source[f"db_bot_{row}"] = 0
            source[f"bot_row_{row}_dia"] = 0
        top_count = source.get(f"top{row}_count", source.get(f"top_row_{row}_bars", 0))
        try:
            top_active = int(top_count or 0) > 0
        except Exception:
            top_active = bool(top_count)
        if not top_active:
            source[f"db_top_{row}"] = 0
            source[f"top_row_{row}_dia"] = 0
    canonical_d = _design_guide_canonical_effective_depth_for_publication(source)
    if canonical_d is not None:
        source["d"] = canonical_d
    payload: dict = {}
    for key in _DESIGN_GUIDE_PUBLICATION_FP_EXPLICIT_KEYS:
        if key in source:
            payload[key] = _design_guide_publication_fp_value(source.get(key))
    for key in sorted(source.keys(), key=str):
        key_text = str(key)
        key_norm = key_text.lower()
        if key_norm.startswith("design_guide_") or key_norm.startswith("_design_guide"):
            continue
        if key_norm in _DESIGN_GUIDE_PUBLICATION_FP_SKIP_KEYS:
            continue
        if key_norm.startswith(_DESIGN_GUIDE_PUBLICATION_FP_SKIP_PREFIXES):
            continue
        if any(token in key_norm for token in _DESIGN_GUIDE_PUBLICATION_FP_SKIP_TOKENS):
            continue
        if key_text in payload:
            continue
        if key_norm.startswith(_DESIGN_GUIDE_PUBLICATION_FP_PREFIXES) or any(
            token in key_norm for token in _DESIGN_GUIDE_PUBLICATION_FP_KEY_TOKENS
        ):
            payload[key_text] = _design_guide_publication_fp_value(source.get(key))
    try:
        session_payload = {
            key: st.session_state.get(key)
            for key in (
                "actions_mode",
                "actions_source",
                "inputs_use_calculated_actions",
                "loads_edit_mode",
                "results_version",
            )
            if key in st.session_state
        }
    except Exception:
        session_payload = {}
    if session_payload:
        payload["session_controls"] = _design_guide_publication_fp_value(session_payload)
    try:
        payload["design_actions_signature"] = tuple(
            _resolve_design_actions_from_state(source).get("signature", ())
        )
    except Exception:
        payload["design_actions_signature"] = ()
    payload["optimisation_goal"] = str(_design_optimisation_goal(source))
    return payload


