def _canonical_overdesign_family_from_updates(
    family_id: object,
    updates: dict | None,
) -> str | None:
    family_text = str(family_id or "").strip()
    if family_text.upper() not in _OVERDESIGN_PUBLICATION_FAMILY_IDS:
        return family_text or None
    update_keys = set(dict(updates or {}))
    has_shear = bool(update_keys & _COMPOUND_SHEAR_UPDATE_KEYS)
    has_bottom = bool(update_keys & _COMPOUND_BOTTOM_UPDATE_KEYS)
    has_geometry = bool(update_keys & {"b", "D"})
    if has_shear and (has_bottom or has_geometry):
        return "COMBINED_OVERDESIGN"
    if has_shear:
        return "SHEAR_OVERDESIGN_GOVERNS"
    if has_bottom or has_geometry:
        return "BENDING_OVERDESIGN_GOVERNS"
    return family_text or None


def _overdesign_terminal_folded_cleanup_from_proof_sources(
    *proof_sources: dict | None,
) -> dict:
    """Return the terminal folded cleanup payload already proven by family evidence."""

    for proof in _iter_overdesign_proof_dicts(*proof_sources):
        try:
            target_count = max(
                int(proof.get("target_band_candidate_count") or 0),
                int(proof.get("executable_target_band_candidate_count") or 0),
            )
        except Exception:
            target_count = 0
        if target_count <= 0:
            continue
        updates = dict(
            proof.get("attempted_updates")
            or proof.get("best_safe_candidate_updates")
            or proof.get("updates")
            or {}
        )
        if not updates:
            continue
        candidate_id = str(
            proof.get("selected_candidate_id")
            or proof.get("best_safe_candidate_id")
            or proof.get("best_rejected_candidate_id")
            or proof.get("failed_candidate_id")
            or proof.get("candidate_id")
            or ""
        ).strip()
        return {
            "updates": updates,
            "candidate_id": candidate_id or _guidance_cleanup_candidate_id(
                "overdesign_terminal_folded", updates
            ),
            "target_band_candidate_count": target_count,
            "terminal_candidate_status": "TERMINAL_TARGET_BAND",
            "further_cleanup_available": False,
            "proof_hash": _dg_runtime_trace_hash(proof),
        }
    return {}


def _iter_overdesign_proof_dicts(*proof_sources: dict | None):
    """Yield nested family proof dictionaries from publication/debug evidence maps."""

    visited: set[int] = set()

    def _walk(value: object):
        if isinstance(value, dict):
            ident = id(value)
            if ident in visited:
                return
            visited.add(ident)
            yield value
            for child in value.values():
                yield from _walk(child)
        elif isinstance(value, (list, tuple)):
            for child in value:
                yield from _walk(child)

    for source in proof_sources:
        yield from _walk(dict(source or {}))


def _overdesign_no_second_cta_proof_from_sources(
    *proof_sources: dict | None,
) -> dict:
    """Return exact-stop cleanup proof that forbids another overdesign CTA."""

    for proof in _iter_overdesign_proof_dicts(*proof_sources):
        if not isinstance(proof, dict) or not proof:
            continue
        no_second = bool(
            proof.get("no_second_cta_required")
            or proof.get("best_safe_candidate_applied")
        )
        if not no_second:
            continue
        try:
            executable_target_count = int(
                proof.get("executable_target_band_candidate_count") or 0
            )
        except Exception:
            executable_target_count = 0
        if executable_target_count <= 0:
            return dict(proof)
    return {}


def _canonical_family_owned_shear_overdesign_apply_family(
    family_id: object,
    updates: dict | None,
    *,
    context: dict | None = None,
) -> str | None:
    family_text = str(family_id or "").strip()
    update_keys = set(dict(updates or {}))
    context_d = dict(context or {})
    context_values = {
        str(value or "").strip()
        for value in (
            context_d.get("selected_family_id"),
            context_d.get("published_family_id"),
            context_d.get("cta_family_id"),
            context_d.get("apply_payload_family_id"),
            context_d.get("candidate_family_id"),
            context_d.get("card_family_id"),
            *(context_d.get("matched_family_ids") or [] if isinstance(context_d.get("matched_family_ids"), (list, tuple, set)) else []),
            context_d.get("contract_runtime_authority"),
            context_d.get("source"),
            context_d.get("guidance_branch"),
            context_d.get("bucket"),
            context_d.get("status"),
            context_d.get("critical_status"),
            context_d.get("title"),
            context_d.get("title_main"),
            context_d.get("primary_action"),
            context_d.get("summary"),
            context_d.get("reasoning"),
        )
        if str(value or "").strip()
    }
    context_text = " ".join(sorted(context_values)).lower()
    if (
        update_keys
        and update_keys.issubset(_COMPOUND_SHEAR_UPDATE_KEYS | {"b", "bw"})
        and (
            "SHEAR_OVERDESIGN_GOVERNS" in context_values
            or "shear_overdesign" in context_text
            or "run_shear_overdesign_governs_runtime" in context_text
        )
    ):
        return "SHEAR_OVERDESIGN_GOVERNS"
    if (
        family_text.lower() == "shear"
        and update_keys
        and update_keys.issubset(_COMPOUND_SHEAR_UPDATE_KEYS)
        and (
            "SHEAR_OVERDESIGN_GOVERNS" in context_values
            or "shear_overdesign" in context_text
            or "run_shear_overdesign_governs_runtime" in context_text
            or (
                "cleanup" in context_text
                and (
                    "efficiency" in context_text
                    or "optional" in context_text
                    or "design is safe" in context_text
                    or "all checks pass" in context_text
                )
            )
        )
    ):
        return "SHEAR_OVERDESIGN_GOVERNS"
    return _canonical_overdesign_family_from_updates(family_text, updates)


