@speed_profiled("ui_render.make_summary_cross_section_figure", category="render")
def make_summary_cross_section_figure():
    layout = compute_section_layout()
    tension_face = st.session_state.get("active_tension_face")

    def _cached_section_builder(
        *,
        shape_name: str,
        dims: dict,
        reo: dict,
        show_shear: bool,
        show_dn: bool = False,
        dn: float = 0.0,
        tension_face: str | None = None,
    ):
        return cached_make_section_figure(
            shape_name=shape_name,
            dims_json=_cache_json(dims),
            reo_json=_cache_json(reo),
            show_shear=show_shear,
            show_dn=show_dn,
            dn=dn,
            tension_face=tension_face,
        )

    result = build_summary_cross_section_result(
        layout=layout,
        tension_face=tension_face,
        fallback_cover_side=float(st.session_state.get("cover_side", 40.0) or 40.0),
        fallback_cover_top=float(st.session_state.get("cover_top", 40.0) or 40.0),
        fallback_cover_bot=float(st.session_state.get("cover_bot", 40.0) or 40.0),
        section_figure_builder=_cached_section_builder,
    )
    if result.error_message:
        st.error(result.error_message)
    return result.figure

# -------------------------------------------------------------------
# Backwards-compatible entrypoint expected by app.py
# Do not remove: app.py routes to inputs_page.render_inputs
# -------------------------------------------------------------------
@speed_profiled("ui_render.inputs_page.render_inputs_alias", category="render")
def render_inputs():
    """
    Stable alias for the Inputs page renderer.

    Some versions of app.py call inputs_page.render_inputs.
    If the internal renderer is renamed, keep this alias so routing never breaks.
    """
    # Try common renderer names in order of preference
    if "render_inputs_page" in globals():
        return globals()["render_inputs_page"]()
    if "render_page" in globals():
        return globals()["render_page"]()
    if "render" in globals():
        return globals()["render"]()
    if "page" in globals():
        return globals()["page"]()

    raise AttributeError(
        "inputs_page.py: No Inputs renderer found. Expected one of: "
        "render_inputs_page(), render_page(), render(), page()."
    )


