@speed_profiled("ui_render.inputs_page.section_2d_diagram_block", category="render")
def _render_section_2d_diagram_block(*, compact: bool = False, model_state: dict | None = None):
    """Render the 2D section diagram only (UI order/presentation helper)."""
    diagram_started_at = time.perf_counter()
    sec_shape = st.session_state.get("sec_shape", "RECT")

    if sec_shape == "RECT":
        _required = ["b", "D"]
    elif sec_shape == "T":
        _required = ["bf", "tf", "bw", "D"]
    else:  # "I"
        _required = ["bf", "tf", "tw", "D"]

    _missing = [k for k in _required if st.session_state.get(k) in (None, "", 0)]
    if _missing:
        st.info("2D section diagram not available right now (inputs are still saved).")
        return

    fig_sec = None
    figure_cache_hit = False
    try:
        geo_fp = _inputs_geometry_fingerprint(model_state)
        cached_fp = st.session_state.get("_inputs_model_2d_geo_fp")
        cached_fig = st.session_state.get("_inputs_model_2d_fig")
        if cached_fp == geo_fp and cached_fig is not None:
            fig_sec = cached_fig
            figure_cache_hit = True
        else:
            fig_sec = make_summary_cross_section_figure()
            if fig_sec is None:
                raise ValueError("2D section diagram function returned None (fig is None)")
            st.session_state["_inputs_model_2d_fig"] = fig_sec
            st.session_state["_inputs_model_2d_geo_fp"] = geo_fp
    except Exception as e:
        st.warning(f"2D section diagram failed: {e}")
        with st.expander("Diagram debug details"):
            st.exception(e)
        return

    if fig_sec is not None:
        try:
            # ~12% shorter than legacy 540/620 to limit vertical overflow
            fig_sec.update_layout(
                autosize=True,
                height=(475 if compact else 545),
                margin=dict(l=4, r=4, t=4, b=4),
            )
        except Exception:
            pass
        _record_inputs_model_diagram_render_reuse_trace(
            diagram_key="inputs_section_2d_diagram",
            geometry_fingerprint=_inputs_geometry_fingerprint(model_state),
            compact=compact,
            renderer="section_2d",
            figure_cache_hit=figure_cache_hit,
            figure_copy_skipped=figure_cache_hit,
        )
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        render_plotly_diagram(
            fig_sec,
            key="inputs_section_2d_diagram",
            title="2D section diagram",
            config={"displayModeBar": False},
        )
        st.markdown("</div>", unsafe_allow_html=True)


def _render_3d_diagram_block(*, compact: bool = False, model_state: dict | None = None):
    """Render the 3D diagram only (UI order/presentation helper)."""
    diagram_started_at = time.perf_counter()
    geo_fp = _inputs_geometry_fingerprint(model_state)
    cache_payload = st.session_state.get("_inputs_model_3d_cache", {})
    cached_fp = cache_payload.get("geo_fp")
    cached_shape = cache_payload.get("shape_name")
    cached_fig = cache_payload.get("fig")
    figure_cache_hit = False
    if cached_fp == geo_fp and cached_fig is not None and isinstance(cached_shape, str):
        shape_name = cached_shape
        fig3d = cached_fig
        figure_cache_hit = True
    else:
        layout = compute_section_layout()
        shape_name = layout.get("shape_name", "Rectangle (b ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â D)")
        dims = layout.get("dims", {})
        reo = dict(layout.get("reo", {}))
        shared_state = dict(model_state) if isinstance(model_state, dict) else _shared_state_snapshot()
        reo["lig_d"] = float(shared_state.get("lig_d", reo.get("lig_d", 0.0)) or 0.0)
        reo["lig_legs"] = int(shared_state.get("lig_legs", reo.get("lig_legs", 0)) or 0)
        reo["s_lig"] = float(shared_state.get("s_lig", reo.get("s_lig", 200.0)) or 200.0)
        reo_layout = layout.get("reo_layout", {})
        if shape_name.startswith(("T-Section", "I-Section")):
            if not isinstance(reo_layout, dict):
                reo_layout = {"top": [], "bottom": []}
            fig3d = cached_make_section_3d_figure(
                shape_name=shape_name,
                dims_json=_cache_json(dims),
                reo_layout_json=_cache_json(reo_layout),
                reo_inputs_json=_cache_json(reo),
                show_shear=True,
                L_vis=900.0,
            )
        else:
            fig3d = make_beam_3d_figure()
        st.session_state["_inputs_model_3d_cache"] = {
            "geo_fp": geo_fp,
            "shape_name": shape_name,
            "fig": fig3d,
        }

    st.markdown(
        """
        <style>
        div[data-testid="stPlotlyChart"] {
          border: 1px solid rgba(0,0,0,0.12);
          border-radius: 8px;
          background: #fff;
          overflow: hidden;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    if shape_name.startswith(("T-Section", "I-Section")):
        BASE_H = 500 if compact else 580
        _h3d = int(int(BASE_H * 7 / 5) * 0.88)
        fig3d.update_layout(
            height=_h3d,
            margin=dict(l=4, r=4, t=4, b=4),
        )
        _record_inputs_model_diagram_render_reuse_trace(
            diagram_key="inputs_section_3d_diagram_t_or_i",
            geometry_fingerprint=_inputs_geometry_fingerprint(model_state),
            compact=compact,
            renderer="section_3d",
            figure_cache_hit=figure_cache_hit,
            figure_copy_skipped=figure_cache_hit,
        )
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        render_plotly_diagram(
            fig3d,
            key="inputs_section_3d_diagram_t_or_i",
            title="3D section diagram",
            width="stretch",
            fullscreen_height=1120,
            config={"displayModeBar": False}
        )
        st.markdown("</div>", unsafe_allow_html=True)
    else:
        BASE_H = 560 if compact else 640
        _h3d = int(int(BASE_H * 7 / 5) * 0.88)
        fig3d.update_layout(
            height=_h3d,
            margin=dict(l=4, r=4, t=4, b=4),
        )
        _record_inputs_model_diagram_render_reuse_trace(
            diagram_key="inputs_section_3d_diagram",
            geometry_fingerprint=_inputs_geometry_fingerprint(model_state),
            compact=compact,
            renderer="section_3d",
            figure_cache_hit=figure_cache_hit,
            figure_copy_skipped=figure_cache_hit,
        )
        st.markdown('<div class="inputs-page-main-diagram-wrap">', unsafe_allow_html=True)
        render_plotly_diagram(
            fig3d,
            key="inputs_section_3d_diagram",
            title="3D section diagram",
            width="stretch",
            fullscreen_height=1120,
            config={"displayModeBar": True}
        )
        st.markdown("</div>", unsafe_allow_html=True)


def _shared_toggle(
    label: str,
    widget_key: str,
    shared_key: str,
    default: bool,
    sync_callbacks: dict,
    *,
    help_text: str | None = None,
) -> bool:
    _register_rendered_key(widget_key)
    seed_widget_from_shared(widget_key, shared_key, bool(default))
    return st.toggle(
        label,
        key=widget_key,
        help=help_text,
        on_change=sync_callbacks.get(widget_key),
    )


PRIMARY_GEOMETRY_KEYS = {
    "sec_shape",
    "b",
    "D",
    "bf",
    "tf",
    "bw",
    "tw",
    "bf_bot",
    "tf_bot",
}

MODEL_RENDER_FINGERPRINT_KEYS = PRIMARY_GEOMETRY_KEYS | {
    "cover_top",
    "cover_bot",
    "cover_side",
    "rowgap_top",
    "rowgap_bot",
    "bot_row_count",
    "bot1_count",
    "db_bot_1",
    "bot2_count",
    "db_bot_2",
    "top_row_count",
    "top1_count",
    "db_top_1",
    "top2_count",
    "db_top_2",
    "lig_d",
    "lig_legs",
    "s_lig",
}

_INPUTS_MODEL_DIAGRAM_RENDER_REUSE_TRACE_KEY = "_inputs_model_diagram_render_reuse_trace"
_INPUTS_STABLE_RENDER_REUSE_TRACE_KEY = "_inputs_stable_render_reuse_trace"


def _inputs_geometry_fingerprint(state: dict | None = None) -> tuple:
    source = state if isinstance(state, dict) else st.session_state
    return tuple((k, source.get(k)) for k in sorted(MODEL_RENDER_FINGERPRINT_KEYS))


def _record_inputs_model_diagram_render_reuse_trace(
    *,
    diagram_key: str,
    geometry_fingerprint: object,
    compact: bool,
    renderer: str,
    figure_cache_hit: bool = False,
    figure_copy_skipped: bool = False,
) -> dict:
    current_hash = str(
        stable_fingerprint_for_payload(
            {
                "diagram_key": str(diagram_key or ""),
                "geometry_fingerprint": geometry_fingerprint,
                "compact": bool(compact),
                "renderer": str(renderer or ""),
            }
        )
    )
    try:
        trace = dict(st.session_state.get(_INPUTS_MODEL_DIAGRAM_RENDER_REUSE_TRACE_KEY) or {})
        previous = dict(trace.get(str(diagram_key or "")) or {})
        previous_hash = str(previous.get("render_fingerprint_hash") or "")
        reuse_eligible = bool(previous_hash and previous_hash == current_hash)
        row = {
            "diagram_key": str(diagram_key or ""),
            "renderer": str(renderer or ""),
            "compact": bool(compact),
            "render_fingerprint_hash": current_hash,
            "previous_render_fingerprint_hash": previous_hash or None,
            "reuse_eligible": reuse_eligible,
            "decision": "TRACE_REUSE_ELIGIBLE" if reuse_eligible else "TRACE_RENDER_REQUIRED",
            "reason": "stable_model_diagram_fingerprint" if reuse_eligible else "missing_or_changed_model_diagram_fingerprint",
            "trace_only": True,
            "product_behavior_changed": False,
            "render_skipped": False,
            "figure_cache_hit": bool(figure_cache_hit),
            "figure_copy_skipped": bool(figure_copy_skipped),
            "implementation_guard_active": True,
            "implementation_scope": "diagram_figure_reuse_without_render_skip",
        }
        trace[str(diagram_key or "")] = dict(row)
        st.session_state[_INPUTS_MODEL_DIAGRAM_RENDER_REUSE_TRACE_KEY] = trace
        return row
    except Exception:
        return {
            "diagram_key": str(diagram_key or ""),
            "renderer": str(renderer or ""),
            "compact": bool(compact),
            "render_fingerprint_hash": current_hash,
            "reuse_eligible": False,
            "decision": "TRACE_RENDER_REQUIRED",
            "reason": "trace_record_failed",
            "trace_only": True,
            "product_behavior_changed": False,
            "render_skipped": False,
            "figure_cache_hit": bool(figure_cache_hit),
            "figure_copy_skipped": bool(figure_copy_skipped),
            "implementation_guard_active": True,
            "implementation_scope": "diagram_figure_reuse_without_render_skip",
        }


def _record_inputs_stable_render_reuse_trace(
    *,
    surface: str,
    fingerprint_payload: dict,
    debug_mode: bool = False,
    apply_in_flight: bool = False,
    pending_apply_refresh: bool = False,
    required_fingerprint_keys: tuple[str, ...] = (),
    store_trace: bool = True,
) -> dict:
    fingerprint_payload_d = fingerprint_payload if isinstance(fingerprint_payload, dict) else {}
    current_hash = str(
        stable_fingerprint_for_payload(
            {
                "surface": str(surface or ""),
                "fingerprint_payload": fingerprint_payload_d,
            }
        )
    )
    try:
        trace = dict(st.session_state.get(_INPUTS_STABLE_RENDER_REUSE_TRACE_KEY) or {})
        previous = dict(trace.get(str(surface or "")) or {})
        previous_hash = str(previous.get("render_fingerprint_hash") or "")
        reasons: list[str] = []
        if bool(debug_mode):
            reasons.append("debug_mode_enabled")
        if bool(apply_in_flight):
            reasons.append("post_click_apply_in_flight")
        if bool(pending_apply_refresh):
            reasons.append("pending_apply_refresh")
        if not current_hash:
            reasons.append("missing_render_fingerprint_hash")
        missing_required_keys = sorted(
            str(key)
            for key in tuple(required_fingerprint_keys or ())
            if fingerprint_payload_d.get(str(key)) in (None, "", [], {})
        )
        if missing_required_keys:
            reasons.append(
                "missing_required_render_fingerprint_fields:"
                + ",".join(missing_required_keys)
            )
        if not previous_hash:
            reasons.append("missing_previous_render_fingerprint_hash")
        if previous_hash and previous_hash != current_hash:
            reasons.append("stale_or_changed_render_fingerprint_hash")
        reuse_eligible = not reasons
        row = {
            "surface": str(surface or ""),
            "render_fingerprint_hash": current_hash,
            "previous_render_fingerprint_hash": previous_hash or None,
            "fingerprint_payload_hash": str(
                stable_fingerprint_for_payload(fingerprint_payload_d)
            ),
            "fingerprint_payload_keys": sorted(str(key) for key in dict(fingerprint_payload_d or {}).keys()),
            "required_fingerprint_keys": sorted(str(key) for key in tuple(required_fingerprint_keys or ())),
            "missing_required_fingerprint_keys": missing_required_keys,
            "reuse_eligible": bool(reuse_eligible),
            "decision": "TRACE_REUSE_ELIGIBLE" if reuse_eligible else "TRACE_RENDER_REQUIRED",
            "reason": "stable_render_fingerprint" if reuse_eligible else ",".join(sorted(set(reasons))),
            "trace_only": True,
            "product_behavior_changed": False,
            "render_skipped": False,
            "store_trace": bool(store_trace),
        }
        if bool(store_trace):
            trace[str(surface or "")] = dict(row)
            st.session_state[_INPUTS_STABLE_RENDER_REUSE_TRACE_KEY] = trace
        else:
            probe_trace = dict(trace.get("_diagnostic_probes") or {})
            probe_trace[str(surface or "")] = dict(row)
            trace["_diagnostic_probes"] = probe_trace
            st.session_state[_INPUTS_STABLE_RENDER_REUSE_TRACE_KEY] = trace
        return row
    except Exception:
        return {
            "surface": str(surface or ""),
            "render_fingerprint_hash": current_hash,
            "reuse_eligible": False,
            "decision": "TRACE_RENDER_REQUIRED",
            "reason": "trace_record_failed",
            "trace_only": True,
            "product_behavior_changed": False,
            "render_skipped": False,
            "store_trace": bool(store_trace),
        }


def _geometry_lock_enabled(source: dict | None = None) -> bool:
    resolved = source if isinstance(source, dict) else st.session_state
    if bool((resolved or {}).get("optimisation_lock_geometry", False)):
        return True
    return bool(
        (resolved or {}).get("optimisation_lock_width", False)
        and (resolved or {}).get("optimisation_lock_depth", False)
    )


def _geometry_width_lock_enabled(source: dict | None = None) -> bool:
    resolved = source if isinstance(source, dict) else st.session_state
    return bool(
        (resolved or {}).get("optimisation_lock_geometry", False)
        or (resolved or {}).get("optimisation_lock_width", False)
    )


def _geometry_depth_lock_enabled(source: dict | None = None) -> bool:
    resolved = source if isinstance(source, dict) else st.session_state
    return bool(
        (resolved or {}).get("optimisation_lock_geometry", False)
        or (resolved or {}).get("optimisation_lock_depth", False)
    )


def _migrate_geometry_master_lock_to_axis_locks_once() -> None:
    version_key = "_inputs_geometry_axis_lock_migration_version"
    if st.session_state.get(version_key) == "axis-locks-v1":
        return
    if bool(st.session_state.get("optimisation_lock_geometry", False)):
        for shared_key, widget_key in (
            ("optimisation_lock_width", "inputs_optimisation_lock_width"),
            ("optimisation_lock_depth", "inputs_optimisation_lock_depth"),
        ):
            st.session_state[shared_key] = True
            st.session_state[widget_key] = True
    st.session_state[version_key] = "axis-locks-v1"


def _sync_geometry_master_lock_from_axis_locks() -> None:
    width_locked = bool(st.session_state.get("optimisation_lock_width", False))
    depth_locked = bool(st.session_state.get("optimisation_lock_depth", False))
    master_locked = bool(width_locked and depth_locked)
    st.session_state["optimisation_lock_geometry"] = master_locked
    st.session_state["inputs_optimisation_lock_geometry"] = master_locked


def _design_optimisation_goal(state: dict | None = None) -> str:
    source = state if isinstance(state, dict) else st.session_state
    return _resolve_design_optimisation_goal_core(
        source,
        goal_labels=DESIGN_OPTIMISATION_GOAL_LABELS,
        default_goal="balanced",
    )


def _design_optimisation_goal_label(state: dict | None = None) -> str:
    goal = _design_optimisation_goal(state)
    return DESIGN_OPTIMISATION_GOAL_LABELS[goal]


def _design_mode_config(goal: str | None = None) -> dict:
    resolved_goal = goal or _design_optimisation_goal()
    return _resolve_design_mode_config_core(
        resolved_goal,
        mode_config_by_goal=AUTO_DESIGN_MODE_CONFIG,
        default_goal="balanced",
    )


def _resolved_efficiency_target_band(
    mode_config: dict | None = None,
    *,
    goal: str | None = None,
) -> tuple[float, float, bool]:
    resolved_goal = goal or _design_optimisation_goal()
    return _resolve_efficiency_target_band_core(
        mode_config,
        goal=resolved_goal,
        mode_config_by_goal=AUTO_DESIGN_MODE_CONFIG,
        default_low=EFFICIENCY_TARGET_UTIL_MIN,
        default_high=EFFICIENCY_TARGET_UTIL_MAX,
        default_goal="balanced",
    )


def _mode_target_midpoint(mode_config: dict) -> float:
    target_lo, target_hi, _ = _resolved_efficiency_target_band(mode_config, goal=_design_optimisation_goal())
    return (float(target_lo) + float(target_hi)) / 2.0


def _sync_auto_design_mode_tracking(state: dict | None = None) -> None:
    current_mode = _design_optimisation_goal(state)
    previous_mode = st.session_state.get("_prev_auto_design_mode")
    if previous_mode is None:
        st.session_state["_prev_auto_design_mode"] = current_mode
        return
    if current_mode != previous_mode:
        st.session_state["_force_auto_redesign"] = True
        st.session_state["_prev_auto_design_mode"] = current_mode
        st.session_state["_auto_design_reason"] = "mode_changed"


