def _design_guide_blocker_attempts_table(item: dict | None) -> dict:
    source_merge = _build_design_guide_controller_blocker_attempt_source_merge(item)
    src = dict(source_merge.get("item") or {})
    evidence = dict(source_merge.get("candidate_search_evidence") or {})
    current_rows = dict(src.get("family_status_current") or {})
    state_for_labels = dict(
        src.get("_current_state_for_display")
        or src.get("current_state_for_display")
        or src.get("state")
        or src.get("current_state")
        or {}
    )
    blockers = dict(source_merge.get("blockers") or {})
    active_candidate_rows = [
        dict(row)
        for row in list(
            evidence.get("active_fail_repair_candidate_rows")
            or evidence.get("candidate_rows")
            or []
        )
        if isinstance(row, dict)
    ]
    active_failures = _resolve_design_guide_controller_blocker_attempt_active_failures(
        candidate_search_evidence=evidence,
        item=src,
        family_status_current=current_rows,
    )

    def _strength_attempt_value_limit(
        family: str,
        value: object,
        limit: object,
    ) -> tuple[object, object]:
        parsed_value = _parse_util_value(value)
        if parsed_value is None and family in {"bending", "shear"}:
            parsed_value = _parse_util_value(dict(current_rows.get(family) or {}).get("util"))
        parsed_limit = _parse_util_value(limit)
        limit_text = str(limit or "").strip().lower()
        if parsed_limit is None or not limit_text or "capacity or serviceability" in limit_text:
            parsed_limit = 1.0
        return (parsed_value if parsed_value is not None else value), parsed_limit

    out: dict = {}
    for family in ("bending", "shear", "combined"):
        blocker = dict(blockers.get(family) or {})
        if family == "combined" and not blocker:
            combined_attempted_updates = (
                _active_failure_route_attempt_updates("combined")
                if ({"bending", "shear"}.issubset(active_failures) or {"bending", "shear"}.issubset(set(blockers)))
                else {}
            )
            combined_attempt = _build_design_guide_controller_combined_active_strength_attempt_row(
                active_failures=active_failures,
                blockers=blockers,
                active_candidate_rows=active_candidate_rows,
                candidate_search_evidence=evidence,
                family_status_current=current_rows,
                combined_attempted_updates=combined_attempted_updates,
            )
            if combined_attempt:
                out[family] = combined_attempt
                continue
        if not blocker and family != "combined":
            continue
        attempted_count = (
            blocker.get("attempted_candidate_count")
            or blocker.get("candidate_count")
            or blocker.get("repair_candidate_count")
            or blocker.get("cleanup_candidate_count")
            or evidence.get(f"{family}_attempted_candidate_count")
            or evidence.get("attempted_candidate_count")
        )
        reason = str(
            blocker.get("reason")
            or blocker.get("why_reduction_would_hurt_other_design_elements")
            or blocker.get("failed_candidate_reason")
            or blocker.get("failed_check_name")
            or evidence.get("reason")
            or ""
        ).strip()
        failed_check_name = (
            blocker.get("failed_check_name")
            or blocker.get("failed_check")
            or blocker.get("blocking_check")
            or evidence.get("failed_check_name")
        )
        failed_check_value = (
            blocker.get("failed_check_value")
            or blocker.get("failed_value")
            or blocker.get("failed_check_util")
            or blocker.get("current_util")
        )
        failed_check_limit = (
            blocker.get("failed_check_limit")
            or blocker.get("failed_limit")
            or blocker.get("failed_check_capacity_or_limit")
            or blocker.get("limit")
            or blocker.get("capacity")
        )
        if family in {"bending", "shear"} and family in active_failures:
            failed_check_name = _resolve_design_guide_controller_blocker_attempt_strength_capacity_rule(family)
            failed_check_value, failed_check_limit = _strength_attempt_value_limit(
                family,
                failed_check_value,
                failed_check_limit,
            )
            reason = _build_design_guide_controller_blocker_attempt_strength_reason(
                family,
                failed_check_value,
                failed_check_limit,
            )
        attempted_updates = (
            _active_failure_route_attempt_updates(
                family,
                dict(blocker.get("attempted_updates") or evidence.get("attempted_updates") or {}),
            )
            if family in {"bending", "shear", "combined"} and (
                family == "combined" or family in active_failures
            )
            else dict(blocker.get("attempted_updates") or evidence.get("attempted_updates") or {})
        )
        current_util = (
            blocker.get("current_util")
            or blocker.get("failed_check_current_util")
            or dict(current_rows.get(family) or {}).get("util")
        )
        attempted_util = (
            blocker.get("attempted_util")
            or blocker.get("rejected_candidate_util")
            or blocker.get("preview_util")
            or blocker.get("failed_check_util")
            or failed_check_value
        )
        row_seed = {
            **dict(blocker),
            "attempted_updates": dict(attempted_updates),
            "current_util": current_util,
            "attempted_util": attempted_util,
            "failed_check_name": failed_check_name,
            "failed_check_status": blocker.get("failed_check_status") or evidence.get("failed_check_status"),
            "failed_check_demand": blocker.get("failed_check_demand") or blocker.get("failed_check_value"),
            "failed_check_capacity_or_limit": (
                blocker.get("failed_check_capacity_or_limit")
                or blocker.get("failed_check_limit")
                or blocker.get("limit_value")
                or failed_check_limit
            ),
            "reason": reason,
        }
        attempted_passed = _resolve_design_guide_controller_cleanup_attempted_passed(
            row_seed,
            _parse_util_value(attempted_util),
        )
        rejection_category = _resolve_design_guide_controller_cleanup_rejection_category(
            row_seed,
            _parse_util_value(attempted_util),
            final_accepted_min_family_util=FINAL_ACCEPTED_MIN_FAMILY_UTIL,
            guidance_target_util_max=GUIDANCE_TARGET_UTIL_MAX,
        )
        current_arrangement = _design_guide_cleanup_arrangement_label(family, state_for_labels)
        retained_arrangement = current_arrangement
        out[family] = {
            "attempted": bool(blocker or attempted_count or reason),
            "attempted_candidate_count": attempted_count,
            "attempted_updates": dict(attempted_updates),
            "attempted_change_label": _design_guide_cleanup_attempt_label(family, row_seed, state_for_labels),
            "current_arrangement_label": current_arrangement,
            "retained_arrangement_label": retained_arrangement,
            "current_util": current_util,
            "attempted_util": attempted_util,
            "attempted_passed": attempted_passed,
            "rejection_category": rejection_category,
            "failed_check_demand": blocker.get("failed_check_demand") or blocker.get("failed_check_value"),
            "failed_check_capacity_or_limit": (
                blocker.get("failed_check_capacity_or_limit")
                or blocker.get("failed_check_limit")
                or blocker.get("limit_value")
                or failed_check_limit
            ),
            "failed_check_util": blocker.get("failed_check_util") or attempted_util,
            "accepted_floor": float(FINAL_ACCEPTED_MIN_FAMILY_UTIL),
            "max_allowed_util": 1.0,
            "searched_candidate_count": (
                blocker.get("searched_candidate_count")
                or blocker.get("candidate_count")
                or evidence.get("total_candidates_considered")
                or evidence.get("candidate_count")
            ),
            "safe_candidate_count": blocker.get("safe_candidate_count") or evidence.get("safe_candidate_count"),
            "executable_candidate_count": (
                blocker.get("executable_candidate_count")
                or evidence.get("executable_candidate_count")
                or evidence.get("safe_executor_backed_count")
            ),
            "accepted_band_candidate_count": (
                blocker.get("accepted_band_candidate_count")
                or evidence.get("accepted_band_candidate_count")
            ),
            "preferred_band_candidate_count": (
                blocker.get("preferred_band_candidate_count")
                or evidence.get("preferred_band_candidate_count")
                or evidence.get("target_band_candidate_count")
            ),
            "active_repair_route_inventory": dict(
                blocker.get("active_repair_route_inventory")
                or evidence.get("active_repair_route_inventory")
                or _active_failure_route_inventory(active_failures)
            ),
            "best_rejected_candidate_id": (
                blocker.get("best_rejected_candidate_id")
                or blocker.get("failed_candidate_id")
                or blocker.get("rejected_candidate_id")
                or evidence.get("failed_candidate_id")
                or evidence.get("best_rejected_candidate_id")
            ),
            "failed_check_name": failed_check_name,
            "failed_check_status": blocker.get("failed_check_status") or evidence.get("failed_check_status"),
            "failed_check_value": failed_check_value,
            "failed_check_limit": failed_check_limit,
            "reason": reason,
        }
    return out


def _attach_family_status_display_payload(item: dict | None, *, state: dict | None) -> dict:
    if not isinstance(item, dict):
        return {}
    snapshot_item = _bending_fail_publication_snapshot_for_state(
        state,
        purpose="family_status_display",
        source_item=item,
        restore_binding=False,
    )
    if isinstance(snapshot_item, dict):
        return snapshot_item
    out = dict(item)
    current_state_for_display = dict(state or {})
    try:
        current_overview = _collect_design_overview(dict(state or {}))
    except Exception:
        current_overview = {}
    current_table = _design_guide_family_status_table(current_overview)
    contract = dict(out.get("button_contract") or {})
    action_updates = dict(
        contract.get("updates")
        or out.get("selected_action_updates")
        or out.get("updates")
        or _resolve_recommendation_updates(out, state=state or {})
        or {}
    )
    preview_table: dict | None = None
    preview_table_present = False
    if (
        str(contract.get("action_type") or out.get("action_type") or "").strip()
        and (_design_guide_button_contract_enabled(contract) or action_updates)
    ):
        preview_overview = _design_guide_candidate_preview_overview(out, state)
        if preview_overview:
            preview_table = _design_guide_preview_family_delta_table(
                current_overview,
                preview_overview,
            )
            preview_table_present = True
    blocker_attempts: dict | None = None
    blocker_attempts_present = False
    if _design_guide_item_is_visible_blocker(out) or dict(out.get("exact_blockers_by_family") or {}):
        blocker_attempts = _design_guide_blocker_attempts_table(out)
        blocker_attempts_present = True
    return _build_design_guide_controller_family_status_display_payload(
        item=out,
        current_state_for_display=current_state_for_display,
        family_status_current=dict(current_table),
        family_status_preview=preview_table,
        family_status_preview_present=preview_table_present,
        blocker_attempts_by_family=blocker_attempts,
        blocker_attempts_present=blocker_attempts_present,
    )


def _project_final_visible_family_status_display_payload(
    item: dict | None,
    *,
    state: dict | None,
) -> dict:
    if not isinstance(item, dict):
        return {}
    snapshot_item = _bending_fail_publication_snapshot_for_state(
        state,
        purpose="family_status_display",
        source_item=item,
        restore_binding=False,
    )
    if isinstance(snapshot_item, dict):
        return snapshot_item
    out = dict(item)
    current_state = dict(state or {})
    try:
        current_overview = _collect_design_overview(dict(current_state))
    except Exception:
        current_overview = {}
    current_table = _design_guide_family_status_table(current_overview)
    contract = dict(out.get("button_contract") or {})
    action_updates = dict(
        contract.get("updates")
        or out.get("selected_action_updates")
        or out.get("updates")
        or _resolve_recommendation_updates(out, state=current_state)
        or {}
    )
    preview_table: dict = {}
    if (
        str(contract.get("action_type") or out.get("action_type") or "").strip()
        and (_design_guide_button_contract_enabled(contract) or action_updates)
    ):
        preview_overview = _design_guide_candidate_preview_overview(out, current_state)
        if preview_overview:
            preview_table = _design_guide_preview_family_delta_table(
                current_overview,
                preview_overview,
            )
    blocker_attempts: dict = {}
    if _design_guide_item_is_visible_blocker(out) or dict(out.get("exact_blockers_by_family") or {}):
        blocker_attempts = _design_guide_blocker_attempts_table(out)
    projection = _build_final_visible_family_status_display_projection(
        input_item=dict(out),
        current_state_for_display=current_state,
        family_status_current=dict(current_table),
        family_status_preview=dict(preview_table),
        blocker_attempts_by_family=dict(blocker_attempts),
    )
    out.update(dict(projection or {}))
    return out


def _apply_final_visible_combined_outside_target_blocker_projection(
    *,
    out: dict,
    state: dict | None,
    family: str,
    expected_util: float | None,
    existing_evidence: dict,
    contract: dict,
    updates: dict,
    action_payload: dict,
    resolved_candidate: dict,
) -> dict:
    if str(family or "").strip().lower() != "combined" or expected_util is None:
        return {
            "out": dict(out),
            "existing_evidence": dict(existing_evidence),
            "action_payload": dict(action_payload),
            "resolved_candidate": dict(resolved_candidate),
            "projection_applied": False,
        }
    try:
        target_low, target_high, _ = _resolved_efficiency_target_band(
            _design_mode_config(_design_optimisation_goal(state or {})),
            goal=_design_optimisation_goal(state or {}),
        )
    except Exception:
        target_low = float(EFFICIENCY_TARGET_UTIL_MIN)
        target_high = float(GUIDANCE_TARGET_UTIL_MAX)
    if float(target_low) <= float(expected_util) <= float(target_high):
        return {
            "out": dict(out),
            "existing_evidence": dict(existing_evidence),
            "action_payload": dict(action_payload),
            "resolved_candidate": dict(resolved_candidate),
            "projection_applied": False,
        }
    try:
        overview_for_blocker = _collect_design_overview(
            _guidance_state_snapshot(state or {}),
            context=_build_design_actions_context(_guidance_state_snapshot(state or {})),
        )
    except Exception:
        overview_for_blocker = {}
    current_utils = dict((overview_for_blocker or {}).get("utils") or {})
    combined_current_values = [
        float(value)
        for value in (
            _parse_util_value(current_utils.get("bending")),
            _parse_util_value(current_utils.get("shear")),
        )
        if value is not None
    ]
    combined_current_util = max(combined_current_values) if combined_current_values else None
    exact = dict(
        existing_evidence.get("post_click_exact_blockers_by_family")
        or existing_evidence.get("exact_blockers_by_family")
        or out.get("post_click_exact_blockers_by_family")
        or out.get("exact_blockers_by_family")
        or {}
    )
    exact["combined"] = _visible_cleanup_blocker_from_action(
        family="combined",
        state=state,
        overview=overview_for_blocker,
        evidence=existing_evidence,
        contract=contract,
        current_util=combined_current_util,
        expected_util=expected_util,
        terminal_mode=False,
    )
    exact["bending"] = _visible_cleanup_blocker_from_action(
        family="bending",
        state=state,
        overview=overview_for_blocker,
        evidence=existing_evidence,
        contract=contract,
        current_util=_parse_util_value(current_utils.get("bending")),
        expected_util=expected_util,
        terminal_mode=False,
    )
    projection = _build_final_visible_combined_outside_target_blocker_evidence_projection(
        existing_evidence=dict(existing_evidence),
        exact_blockers_by_family=dict(exact),
        updates=dict(updates),
        expected_util=expected_util,
        action_payload=dict(action_payload),
        resolved_candidate=dict(resolved_candidate),
    )
    projected_out = dict(out)
    projected_out.update(dict(projection.get("item_projection") or {}))
    return {
        "out": projected_out,
        "existing_evidence": dict(projection.get("candidate_search_evidence") or existing_evidence),
        "action_payload": dict(projection.get("action_payload_projection") or action_payload),
        "resolved_candidate": dict(projection.get("resolved_candidate_projection") or resolved_candidate),
        "projection": dict(projection),
        "projection_applied": True,
    }


def _attach_safe_combined_cleanup_preview_payload(
    item: dict | None,
    *,
    state: dict | None,
    debug_sink: dict | None = None,
) -> dict:
    if not isinstance(item, dict):
        return {}
    out = dict(item)
    contract = dict(out.get("button_contract") or {})
    candidate_id = str(
        contract.get("candidate_id")
        or contract.get("source_candidate_id")
        or out.get("candidate_id")
        or out.get("source_candidate_id")
        or ""
    ).strip()
    updates = dict(
        contract.get("updates")
        or out.get("selected_action_updates")
        or out.get("updates")
        or {}
    )
    if not (
        candidate_id == "combined_best_safe_shear_plus_bending_cleanup"
        and _design_guide_button_contract_enabled(contract)
        and bool(updates)
        and bool(set(updates) & _COMPOUND_SHEAR_UPDATE_KEYS)
        and bool(set(updates) & _COMPOUND_BOTTOM_UPDATE_KEYS)
    ):
        return out
    out = _attach_family_status_display_payload(out, state=state)
    if dict(out.get("family_status_preview") or {}):
        if isinstance(debug_sink, dict):
            debug_sink["family_status_current"] = dict(out.get("family_status_current") or {})
            debug_sink["family_status_preview"] = dict(out.get("family_status_preview") or {})
            debug_sink["safe_combined_cleanup_preview_rows_attached"] = True
        return out
    try:
        current_overview = _collect_design_overview(dict(state or {}))
        candidate = _evaluate_auto_design_candidate(
            dict(state or {}),
            updates=dict(updates),
            source="design_guide_safe_combined_cleanup_final_preview",
            label=str(out.get("title_main") or out.get("title") or "Shear and bending cleanup - one-click optimisation"),
            action_type=str(contract.get("action_type") or out.get("action_type") or "apply_resolved_candidate"),
        )
    except Exception:
        candidate = None
        current_overview = {}
    if isinstance(candidate, dict):
        preview_overview = dict(candidate.get("overview") or {})
        if preview_overview:
            out["family_status_current"] = _design_guide_family_status_table(current_overview)
            out["family_status_preview"] = _design_guide_preview_family_delta_table(
                current_overview,
                preview_overview,
            )
            if isinstance(debug_sink, dict):
                debug_sink["family_status_current"] = dict(out.get("family_status_current") or {})
                debug_sink["family_status_preview"] = dict(out.get("family_status_preview") or {})
                debug_sink["safe_combined_cleanup_preview_rows_attached"] = True
                debug_sink["safe_combined_cleanup_preview_candidate_source"] = (
                    "design_guide_safe_combined_cleanup_final_preview"
                )
    return out


def _design_guide_family_status_sections_html(item: dict, state: dict | None = None) -> str:
    current = dict((item or {}).get("family_status_current") or {})
    if not current:
        return ""

    def _status_text(row: dict) -> str:
        util = _design_guide_format_display_util(row.get("util"))
        status = str(row.get("status") or "-").strip().upper() or "-"
        return f"{util} {status}".strip()

    labels = {
        "bending": "Bending",
        "shear": "Shear",
        "crack": "Crack",
        "deflection": "Deflection",
    }
    sections: list[str] = []
    preview = dict((item or {}).get("family_status_preview") or {})
    if preview:
        preview_lines = []
        for family in ("bending", "shear", "crack", "deflection"):
            row = dict(preview.get(family) or {})
            before = f"{_design_guide_format_display_util(row.get('before_util'))} {str(row.get('before_status') or '-').upper()}"
            after = f"{_design_guide_format_display_util(row.get('after_util'))} {str(row.get('after_status') or '-').upper()}"
            preview_lines.append(f"{labels[family]}: {before.strip()} -> {after.strip()}")
        sections.append(
            "<div class='fast-guidance-secondary fast-guidance-family-preview'>"
            "<strong>Current -&gt; Preview</strong><br>"
            + "<br>".join(html.escape(line) for line in preview_lines)
            + "</div>"
        )
        change_lines = _proposed_change_lines_for_guidance_item(item or {}, dict(state or {}))
        change_text = _guidance_compact_change_text(change_lines)
        if change_text:
            sections.append(
                "<div class='fast-guidance-secondary fast-guidance-change-summary'>"
                f"<strong>Change:</strong> {html.escape(change_text)}"
                "</div>"
            )
        family = str((item or {}).get("family") or (item or {}).get("selected_action_family") or "").strip().lower()
        if family not in {"bending", "shear", "combined"}:
            family = str((item or {}).get("check_key") or "design").strip().lower()
        source = str((item or {}).get("source") or "").strip().lower()
        if "repair" in str((item or {}).get("guidance_intent") or "").strip().lower() or str((item or {}).get("bucket") or "") == "fail":
            why_text = f"Smallest one-click {family} repair that restores required checks."
        elif "cleanup" in source or str((item or {}).get("guidance_intent") or "") == "efficiency_tightening":
            why_text = f"Best safe one-click {family} reduction. All checks remain PASS."
        else:
            why_text = "Selected one-click update. All required checks remain PASS."
        sections.append(
            "<div class='fast-guidance-secondary fast-guidance-action-reason'>"
            f"<strong>Why:</strong> {html.escape(why_text)}"
            + "</div>"
        )
    else:
        current_lines = [
            f"{labels[family]}: {_status_text(dict(current.get(family) or {}))}"
            for family in ("bending", "shear", "crack", "deflection")
        ]
        sections.append(
            "<div class='fast-guidance-secondary fast-guidance-family-status'>"
            "<strong>Current</strong><br>"
            + "<br>".join(html.escape(line) for line in current_lines)
            + "</div>"
        )
    attempts = dict((item or {}).get("blocker_attempts_by_family") or {})
    if attempts:
        reason_lines = []
        detail_lines = []
        active_strength_fail = any(
            str(dict(current.get(family) or {}).get("status") or "").strip().upper() == "FAIL"
            for family in ("bending", "shear")
        )

        def _route_text(family: str, updates: dict) -> str:
            keys = {str(key).strip().lower() for key in (updates or {}).keys()}
            if family == "bending":
                found = []
                if any("count" in key or "bars" in key for key in keys):
                    found.append("bar count")
                if any("dia" in key or "db_bot" in key for key in keys):
                    found.append("bar diameter")
                if any("bot2" in key or "row_2" in key or "second" in key for key in keys):
                    found.append("second row")
                if "d" in keys or "depth" in keys:
                    found.append("depth")
                if "b" in keys or "bw" in keys or "width" in keys:
                    found.append("width")
                return ", ".join(dict.fromkeys(found)) or "bar count, bar diameter, depth and width routes"
            if family == "shear":
                found = []
                if "s_lig" in keys or any("spacing" in key for key in keys):
                    found.append("link spacing")
                if "lig_d" in keys or any("diameter" in key for key in keys):
                    found.append("link diameter")
                if "lig_legs" in keys or any("legs" in key for key in keys):
                    found.append("link legs")
                if "d" in keys or "depth" in keys:
                    found.append("depth")
                if "b" in keys or "bw" in keys or "width" in keys:
                    found.append("width")
                return ", ".join(dict.fromkeys(found)) or "link spacing, link diameter, leg count, depth and width routes"
            return "combined geometry, reinforcement and link routes"

        def _display_value_text(value: object) -> str:
            parsed = _parse_util_value(value)
            if parsed is not None:
                return f"utilisation {_design_guide_format_display_util(parsed)}"
            text = str(value or "").strip()
            return text if text else "not published"

        def _display_limit_text(limit: object) -> str:
            parsed = _parse_util_value(limit)
            if parsed is not None:
                return f"<= {_design_guide_format_display_util(parsed)}"
            text = str(limit or "").strip()
            return text if text else "not published"

        for family in ("bending", "shear", "combined"):
            row = dict(attempts.get(family) or {})
            if not row:
                continue
            failed = str(row.get("failed_check_name") or "not published").strip()
            failed_status = str(row.get("failed_check_status") or "").strip()
            value = row.get("failed_check_value")
            limit = row.get("failed_check_limit")
            value_text = _display_value_text(value)
            limit_text = _display_limit_text(limit)
            candidate = str(row.get("best_rejected_candidate_id") or "-").strip()
            count = row.get("attempted_candidate_count")
            reason = str(row.get("reason") or "").strip()
            short_reason = reason.split(".")[0].strip() if reason else failed
            if active_strength_fail:
                route_text = _route_text(family, dict(row.get("attempted_updates") or {}))
                if family == "combined":
                    route_text = "combined geometry, bottom reo, second-row and links routes"
                failed_status_text = f" ({failed_status})" if failed_status else ""
                reason_lines.append(
                    f"- {family.title()} blocker: candidate {candidate}; tried {route_text}; "
                    f"failed rule {failed}{failed_status_text}; actual value {value_text}; "
                    f"required limit {limit_text}"
                )
            else:
                candidate_text = "" if candidate == "-" else f" candidate {candidate};"
                reason_lines.append(
                    f"- {family.title()}:{candidate_text} {short_reason}; "
                    f"actual value {value_text}; required limit {limit_text}"
                )
            detail_lines.append(
                f"{family.title()} attempts: tried {count if count is not None else '-'}; "
                f"best rejected {candidate}; failed rule {failed}; actual value {value_text}; required limit {limit_text}."
            )
            if reason:
                detail_lines.append(f"{family.title()} reason: {reason}")
        if reason_lines:
            sections.append(
                "<div class='fast-guidance-secondary fast-guidance-blocker-attempts'>"
                "<strong>Blocked because:</strong><br>"
                + "<br>".join(_render_final_design_guide_text_html(line) for line in reason_lines[:3])
                + "</div>"
            )
            if detail_lines:
                sections.append(
                    "<details class='fast-guidance-secondary fast-guidance-details'>"
                    "<summary>Details</summary>"
                    + "<br>".join(_render_final_design_guide_text_html(line) for line in detail_lines)
                    + "</details>"
                )
    return "".join(sections)


def _design_guide_dashboard_status(
    item: dict,
    *,
    item_bucket: str,
    use_success_style: bool,
    actionable: bool,
) -> tuple[str, str, str]:
    publication_policy = str(item.get("design_guide_publication_policy") or "").strip()
    if publication_policy == "locked_active_failure_missing_exact_proof":
        return "error", "ERROR", "error"
    if str(item.get("guidance_intent") or "").strip() == "diagnostic_incomplete_proof":
        return "error", "ERROR", "error"
    title_hint = str(item.get("title_main") or item.get("title") or "").strip().lower()
    if _is_final_design_guide_family_contract_violation_item(item):
        return "error", "ERROR", "error"
    is_blocker = _design_guide_item_is_visible_blocker(item) or "blocked" in title_hint
    if actionable:
        current = dict(item.get("family_status_current") or {})
        active_strength_fail = any(
            str(dict(current.get(family) or {}).get("status") or "").strip().upper() == "FAIL"
            for family in ("bending", "shear")
        ) or "capacity is low" in title_hint or "repair required" in title_hint
        if active_strength_fail:
            return "action", "ACTION", "error"
        return "action", "ACTION", "action"
    if item_bucket in {"fail", "error"}:
        return "error", ("BLOCKED" if is_blocker else "ERROR"), "error"
    if use_success_style or item_bucket == "pass":
        return "pass", "PASS", "pass"
    if item_bucket == "warn":
        return "warning", "WARNING", "warning"
    if item_bucket == "efficiency":
        return (
            "blocked" if is_blocker else "pass",
            "BLOCKED" if is_blocker else "PASS",
            "blocked" if is_blocker else "pass",
        )
    return "info", "INFO", "blocked" if is_blocker else "pass"


def _design_guide_dashboard_title(item: dict, display_title: str, *, actionable: bool, status: str) -> str:
    publication_policy = str(item.get("design_guide_publication_policy") or "").strip()
    if publication_policy in {
        "locked_active_failure_missing_exact_proof",
        "unlocked_active_failure_missing_runtime_proof",
    }:
        return "Design Guide blocker proof incomplete"
    if str(item.get("guidance_intent") or "").strip() == "diagnostic_incomplete_proof":
        return str(
            item.get("title_main")
            or item.get("title")
            or display_title
            or "Design Guide proof incomplete"
        ).strip()
    title_l = str(display_title or item.get("title_main") or item.get("title") or "").strip().lower()
    family = str(item.get("selected_action_family") or item.get("family") or item.get("check_key") or "").strip().lower()
    current = dict(item.get("family_status_current") or {})
    blocker_families = {
        str(blocker_family or "").strip().lower()
        for blocker_family in dict(
            item.get("exact_blockers_by_family")
            or item.get("post_click_exact_blockers_by_family")
            or item.get("blocker_attempts_by_family")
            or {}
        ).keys()
        if str(blocker_family or "").strip().lower() in {"bending", "shear"}
    }
    bending_current_util = _parse_util_value(
        dict(current.get("bending") or {}).get("util")
        or dict(current.get("bending") or {}).get("current_util")
    )
    if (
        not actionable
        and "shear cleanup blocked" in title_l
        and "bending" in blocker_families
        and bending_current_util is not None
        and float(bending_current_util) < float(FINAL_ACCEPTED_MIN_FAMILY_UTIL) - float(TARGET_BAND_EPS)
    ):
        return "Bending and shear cleanup blocked"
    active_fail = any(
        str(dict(current.get(f) or {}).get("status") or "").strip().upper() == "FAIL"
        for f in ("bending", "shear")
    )
    if actionable and active_fail:
        return "Strengthening required"
    if actionable:
        if family == "shear" or "shear cleanup" in title_l:
            return "Improve shear efficiency"
        if family == "bending" or "bending cleanup" in title_l:
            return "Improve bending efficiency"
        return "One-click design available"
    if status == "pass":
        return "Design is efficient"
    if status == "error":
        if "bending and shear" in title_l or family == "combined":
            return "Bending and shear repair blocked"
        if family == "shear":
            return "Shear repair blocked"
        if family == "bending":
            return "Bending repair blocked"
        return "Strengthening blocked"
    if "cleanup" in title_l or status == "blocked":
        if blocker_families >= {"bending", "shear"}:
            return "Bending and shear cleanup blocked"
        if "shear" in blocker_families or family == "shear":
            return "Shear cleanup blocked"
        if "bending" in blocker_families or family == "bending":
            return "Bending cleanup blocked"
        return "Further cleanup blocked"
    return str(display_title or item.get("title_main") or "Design guidance").strip() or "Design guidance"


def _design_guide_dashboard_governing_label(item: dict, display_util: object, display_title: str) -> str:
    contract_evidence = dict((item or {}).get("candidate_search_evidence") or {})
    explicit_contract_label = str((item or {}).get("governing_label") or "").strip()
    if explicit_contract_label and bool(contract_evidence.get("contract_boundary_checked")):
        return explicit_contract_label
    util = _parse_util_value(display_util)
    family = str(item.get("selected_action_family") or item.get("family") or item.get("check_key") or "").strip().lower()
    current = dict(item.get("family_status_current") or {})
    if family == "combined":
        title_l = str(display_title or item.get("title_main") or item.get("title") or "").strip().lower()
        status_l = str(item.get("status") or item.get("bucket") or "").strip().lower()
        contract_enabled = _design_guide_button_contract_enabled(dict(item.get("button_contract") or {}))
        actionable = bool(item.get("primary_card_actionable")) or contract_enabled
        if (
            not actionable
            and ("blocked" in title_l or "repair" in title_l or status_l in {"fail", "error", "blocked"})
        ):
            ranked = []
            for fam in ("bending", "shear"):
                row = dict(current.get(fam) or {})
                fam_util = _parse_util_value(row.get("util"))
                fam_status = str(row.get("status") or "").strip().upper()
                if fam_util is not None and (fam_status == "FAIL" or float(fam_util) > 1.0):
                    ranked.append((float(fam_util), fam))
            if ranked:
                governing_util, governing_family = max(ranked, key=lambda pair: pair[0])
                return f"{governing_family.title()} {governing_util:.2f}"
            blocker_ranked = []
            blocker_source = dict(
                item.get("blocker_attempts_by_family")
                or item.get("exact_blockers_by_family")
                or item.get("post_click_exact_blockers_by_family")
                or {}
            )
            for fam in ("bending", "shear"):
                row = dict(blocker_source.get(fam) or {})
                fam_util = _parse_util_value(
                    row.get("current_util")
                    or row.get("failed_check_util")
                    or row.get("attempted_util")
                    or row.get("util")
                )
                fam_status = str(
                    row.get("failed_check_status")
                    or row.get("status")
                    or row.get("displayed_status")
                    or ""
                ).strip().upper()
                if fam_util is not None and (fam_status == "FAIL" or float(fam_util) > 1.0):
                    blocker_ranked.append((float(fam_util), fam))
            if blocker_ranked:
                governing_util, governing_family = max(blocker_ranked, key=lambda pair: pair[0])
                return f"{governing_family.title()} {governing_util:.2f}"
    if util is not None:
        if family in {"bending", "shear"}:
            current_util = _parse_util_value(dict(current.get(family) or {}).get("util"))
            if current_util is not None and abs(float(current_util) - float(util)) > 0.005:
                return f"{family.title()} {float(util):.2f} from {float(current_util):.2f}"
            return f"{family.title()} {util:.2f}"
        return f"Governing utilisation {util:.2f}"
    vals = [
        _parse_util_value(dict(current.get(f) or {}).get("util"))
        for f in ("bending", "shear", "crack", "deflection")
    ]
    vals = [v for v in vals if v is not None]
    if vals:
        return f"Governing utilisation {max(vals):.2f}"
    return "Target 0.88-0.95"


def _design_guide_dashboard_current_rows(item: dict) -> list[dict]:
    labels = {
        "bending": "Bending",
        "shear": "Shear",
        "crack": "Crack",
        "deflection": "Deflection",
    }
    current = dict(item.get("family_status_current") or {})
    rows = []
    for family in ("bending", "shear", "crack", "deflection"):
        row = dict(current.get(family) or {})
        status = str(row.get("status") or "-").strip().upper() or "-"
        util = _design_guide_format_display_util(row.get("util"))
        rows.append(
            {
                "family": family,
                "label": labels[family],
                "value": util,
                "status": status,
                "tone": _resolve_final_design_guide_status_tone(status),
            }
        )
    return rows


def _design_guide_dashboard_preview_summary(item: dict) -> str:
    preview = dict(item.get("family_status_preview") or {})
    failure_text = _design_guide_action_failure_detail_text(item)
    if not preview:
        return failure_text
    pieces = []
    for family in ("bending", "shear"):
        row = dict(preview.get(family) or {})
        before = _parse_util_value(row.get("before_util"))
        after = _parse_util_value(row.get("after_util"))
        if before is None or after is None:
            continue
        if abs(after - before) > 0.005:
            pieces.append(f"{family} utilisation moves from {before:.2f} to {after:.2f}")
    preview_text = "; ".join(pieces) if pieces else "All required checks remain acceptable after the update."
    if failure_text:
        return f"{failure_text}. {preview_text}"
    return preview_text


def _design_guide_action_failure_detail_text(item: dict | None) -> str:
    details = dict((item or {}).get("failure_details_by_family") or {})
    family = str(
        dict((item or {}).get("button_contract") or {}).get("family")
        or (item or {}).get("selected_action_family")
        or (item or {}).get("family")
        or (item or {}).get("check_key")
        or ""
    ).strip().lower()
    families = [family] if family in details else []
    families.extend([name for name in ("bending", "shear", "crack", "deflection") if name not in families])
    for fam in families:
        for detail in list(details.get(fam) or []):
            if not isinstance(detail, dict):
                continue
            status = str(detail.get("status") or "").strip().upper()
            util = _parse_util_value(detail.get("util"))
            if status not in {"FAIL", "NG"} and not (util is not None and util > 1.0 + 1e-9):
                continue
            title = str(detail.get("title") or "Detailed check").strip() or "Detailed check"
            text = str(detail.get("text") or "").strip()
            if "ductility" in title.lower() or "k_u" in text.lower() or "ku" in text.lower():
                ku_match = re.search(r"k[_\s]?u\s*=\s*([0-9]+(?:\.[0-9]+)?)", text, flags=re.IGNORECASE)
                lim_match = re.search(r"k[_\s]?u\s*,?\s*lim\s*=\s*([0-9]+(?:\.[0-9]+)?)", text, flags=re.IGNORECASE)
                if ku_match and lim_match:
                    return (
                        f"{title} fails: k_u = {ku_match.group(1)} "
                        f"exceeds k_u,lim = {lim_match.group(1)}"
                    )
            if text:
                return f"{title} fails: {text}"
            return f"{title} fails"
    return ""


def _design_guide_attempt_route_summary(family: str, attempted_updates: dict | None) -> str:
    return _repair_attempt_route_summary(family, attempted_updates)


def _design_guide_cleanup_arrangement_label(family: str, state: dict | None) -> str:
    state_dict = dict(state or {})
    family_l = str(family or "").strip().lower()
    if family_l == "bending":
        return _bottom_reo_state_label(state_dict) or "current bending reinforcement"
    if family_l == "shear":
        shear_label = _guidance_shear_links_banner_fragment(state_dict)
        return shear_label or "no links"
    if family_l == "combined":
        bending_label = _bottom_reo_state_label(state_dict) or "current bending reinforcement"
        shear_label = _guidance_shear_links_banner_fragment(state_dict) or "no links"
        return f"bending {bending_label} and shear {shear_label}"
    return "current arrangement"


def _design_guide_sanitised_model_updates_for_label(updates: dict | None) -> dict:
    numeric_keys = {
        "bot1_count",
        "bot2_count",
        "bot_row_count",
        "bot_row_1_bars",
        "bot_row_1_dia",
        "bot_row_2_bars",
        "bot_row_2_dia",
        "db_bot_1",
        "db_bot_2",
        "nb_bot",
        "bot_entry",
        "lig_d",
        "db_lig",
        "lig_legs",
        "s_lig",
        "D",
        "b",
        "beam_width",
        "beam_b",
        "width",
    }
    text_keys = {
        "bot1_layout_mode",
        "bot2_layout_mode",
        "bot_row_1_mode",
        "bot_row_2_mode",
    }
    ignored_keys = {
        "search_scope",
        "generated_count",
        "deduped_count",
        "preview_count",
    }
    out: dict = {}
    for raw_key, value in dict(updates or {}).items():
        key = str(raw_key or "").strip()
        key_l = key.lower()
        if not key or key_l in ignored_keys or key_l.endswith("_route") or key_l in {"links", "bottom_reo"}:
            continue
        if key in numeric_keys:
            numeric = _parse_util_value(value)
            if numeric is None:
                continue
            out[key] = numeric
            continue
        if key in text_keys:
            text = str(value or "").strip()
            if text:
                out[key] = text
    return out


def _design_guide_state_after_updates(state: dict | None, updates: dict | None) -> dict:
    out = dict(state or {})
    for key, value in _design_guide_sanitised_model_updates_for_label(updates).items():
        out[key] = value
    try:
        out = _normalise_bottom_layer_order(out)
    except Exception:
        pass
    return out


def _design_guide_exact_attempt_change_label(family: str, updates: dict | None, state: dict | None) -> str:
    updates_d = dict(updates or {})
    if not updates_d:
        return ""
    before = dict(state or {})
    after = _design_guide_state_after_updates(before, updates_d)
    family_l = str(family or "").strip().lower()
    parts: list[str] = []

    bottom_keys = set(updates_d) & {
        "bot1_count",
        "db_bot_1",
        "bot1_layout_mode",
        "bot2_count",
        "db_bot_2",
        "bot2_layout_mode",
        "bot2_row_enabled",
    }
    if family_l in {"bending", "combined"} and bottom_keys:
        before_label = _bottom_reo_state_label(before) or "current bottom reinforcement"
        after_label = _bottom_reo_state_label(after) or "the proposed bottom reinforcement"
        before_ast = _parse_util_value((_effective_bottom_design_state(before) or {}).get("Ast_bot"))
        after_ast = _parse_util_value((_effective_bottom_design_state(after) or {}).get("Ast_bot"))
        bottom_label = _build_design_guide_controller_cleanup_bottom_reinforcement_change_label(
            before_label=before_label,
            after_label=after_label,
            before_ast=before_ast,
            after_ast=after_ast,
        )
        if bottom_label:
            parts.append(bottom_label)

    shear_keys = set(updates_d) & _COMPOUND_SHEAR_UPDATE_KEYS
    if family_l in {"shear", "combined"} and shear_keys:
        before_label = _guidance_shear_links_banner_fragment(before) or "no links"
        after_label = _guidance_shear_links_banner_fragment(after) or "no links"
        before_spacing = _parse_util_value(before.get("s_lig"))
        after_spacing = _parse_util_value(after.get("s_lig"))
        before_dia = _int_from_state(before, "lig_d", 0)
        after_dia = _int_from_state(after, "lig_d", 0)
        before_legs = _int_from_state(before, "lig_legs", 0)
        after_legs = _int_from_state(after, "lig_legs", 0)
        shear_label = _build_design_guide_controller_cleanup_shear_link_change_label(
            before_label=before_label,
            after_label=after_label,
            before_spacing=before_spacing,
            after_spacing=after_spacing,
            before_dia=before_dia,
            after_dia=after_dia,
            before_legs=before_legs,
            after_legs=after_legs,
        )
        if shear_label:
            parts.append(shear_label)

    geom_keys = set(updates_d) & {"D", "b", "beam_width", "beam_b", "width"}
    if family_l in {"geometry", "combined"} and geom_keys:
        before_w = _parse_util_value(_design_width_value(before))
        after_w = _parse_util_value(_design_width_value(after))
        before_d = _parse_util_value(before.get("D"))
        after_d = _parse_util_value(after.get("D"))
        geom_label = _build_design_guide_controller_cleanup_geometry_change_label(
            before_depth=before_d,
            after_depth=after_d,
            before_width=before_w,
            after_width=after_w,
        )
        if geom_label:
            parts.append(geom_label)

    if parts:
        if len(parts) == 1:
            return parts[0]
        return ", ".join(parts[:-1]) + " and " + parts[-1]
    return ""


def _design_guide_cleanup_attempted_updates(row: dict | None) -> dict:
    return _resolve_design_guide_controller_cleanup_attempted_updates(row)


def _design_guide_cleanup_attempt_label(family: str, row: dict | None, state: dict | None) -> str:
    row_d = dict(row or {})
    explicit = str(
        row_d.get("attempted_change_label")
        or row_d.get("attempted_next_reduction")
        or row_d.get("attempted_reduction_label")
        or ""
    ).strip()
    current_arrangement = _design_guide_cleanup_arrangement_label(family, state)
    explicit_l = explicit.lower()
    if (
        str(family or "").strip().lower() == "shear"
        and (
            bool(row_d.get("no_link_candidate_already_active"))
            or current_arrangement.lower() == "no links"
            or "no links" in current_arrangement.lower()
        )
        and ("removing shear links" in explicit_l or "remove shear" in explicit_l)
    ):
        return _build_design_guide_controller_cleanup_no_link_no_change_label(current_arrangement)
    explicit_label = _resolve_design_guide_controller_cleanup_explicit_attempt_label(row_d)
    if explicit_label:
        return explicit_label
    updates = _design_guide_cleanup_attempted_updates(row_d)
    exact_label = _design_guide_exact_attempt_change_label(family, updates, state)
    if exact_label:
        return exact_label
    change_lines = []
    if updates and not any(
        str(key).strip().lower() in {"search_scope", "generated_count", "deduped_count", "preview_count"}
        for key in updates
    ):
        try:
            change_lines = _guidance_change_lines_for_updates(dict(state or {}), updates)
        except Exception:
            change_lines = []
    if change_lines:
        line = str(change_lines[0] or "").strip()
        arrow = "ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢" if "ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢" in line else ("->" if "->" in line else "")
        if ":" in line and arrow:
            label, values = line.split(":", 1)
            before, after = values.split(arrow, 1)
            label_l = label.strip().lower()
            before_s = before.strip()
            after_s = after.strip()
            if "remove" in after_s.lower():
                return f"removing {label_l} from {before_s}"
            return f"changing {label_l} from {before_s} to {after_s}"
        return line
    if bool(row_d.get("no_link_candidate_already_active")) or "no_links" in str(row_d.get("best_rejected_candidate_id") or "").lower():
        current_arrangement = current_arrangement or "no links"
        return _build_design_guide_controller_cleanup_no_link_no_change_label(current_arrangement)
    route = _design_guide_attempt_route_summary(family, updates)
    return _build_design_guide_controller_cleanup_route_fallback_label(
        route=route,
        current_arrangement=current_arrangement,
        has_sanitised_model_updates=bool(_design_guide_sanitised_model_updates_for_label(updates)),
    )


def _design_guide_cleanup_limit_phrase(row: dict | None, attempted_util: float | None) -> tuple[str, str, str]:
    row_d = dict(row or {})
    raw_limit = (
        row_d.get("limit_value")
        or row_d.get("failed_check_capacity_or_limit")
        or row_d.get("failed_check_limit")
        or row_d.get("capacity_or_limit")
        or row_d.get("threshold")
        or row_d.get("limit")
    )
    limit_value = _parse_util_value(raw_limit)
    raw_limit_text_l = str(raw_limit or "").strip().lower()
    raw_limit_name_l = str(row_d.get("limit_name") or row_d.get("failed_check_name") or "").strip().lower()
    if (
        attempted_util is not None
        and ("accepted" in raw_limit_name_l or "threshold" in raw_limit_name_l)
        and float(attempted_util) < 1.0
    ):
        limit_value = float(FINAL_ACCEPTED_MIN_FAMILY_UTIL)
    if attempted_util is not None and raw_limit_text_l and any(
        token in raw_limit_text_l
        for token in ("knm", "kn", "mpa", "mm", "capacity", "demand", "ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ", "phi")
    ):
        limit_value = 1.0 if float(attempted_util) > 1.0 else float(FINAL_ACCEPTED_MIN_FAMILY_UTIL)
    if limit_value is None and attempted_util is not None:
        if not raw_limit_text_l or "target" in raw_limit_text_l or "accepted" in raw_limit_text_l:
            limit_value = float(FINAL_ACCEPTED_MIN_FAMILY_UTIL)
        else:
            limit_value = 1.0
    limit_name = str(row_d.get("limit_name") or row_d.get("failed_check_name") or "").strip()
    direction = str(row_d.get("failed_direction") or "").strip().lower()
    if attempted_util is not None and limit_value is not None:
        if not direction:
            direction = "below" if float(attempted_util) < float(limit_value) else "above"
        if not limit_name:
            if direction == "below":
                limit_name = "accepted cleanup floor"
            elif abs(float(limit_value) - 1.0) <= 1e-9:
                limit_name = "maximum allowed"
            else:
                limit_name = "required limit"
        return direction, limit_name, _design_guide_format_display_util(limit_value)
    if not direction:
        direction = "not permitted"
    return direction, limit_name or "required check", str(raw_limit or "the recorded limit").strip()


def _design_guide_cleanup_attempted_util(row: dict | None) -> float | None:
    row_d = dict(row or {})
    for key in (
        "attempted_util",
        "failed_check_util",
        "failed_check_value",
        "best_safe_final_util",
        "preview_util",
        "current_util",
    ):
        parsed = _parse_util_value(row_d.get(key))
        if parsed is not None:
            return float(parsed)
    return None


def _design_guide_cleanup_attempted_passed(row: dict | None, attempted_util: float | None = None) -> bool | None:
    row_d = dict(row or {})
    explicit = row_d.get("attempted_passed")
    if isinstance(explicit, bool):
        return explicit
    status_text = " ".join(
        str(row_d.get(key) or "")
        for key in ("failed_check_status", "attempted_status", "preview_status", "status", "rejection_category")
    ).strip().lower()
    if any(token in status_text for token in ("spacing", "detailing", "ductility", "serviceability", "unsafe")):
        return False
    if "fail" in status_text and "final accepted" not in status_text and "efficiency" not in status_text:
        return False
    if any(token in status_text for token in ("pass", "safe", "accepted floor", "below accepted", "preferred band")):
        return True
    if attempted_util is not None:
        return float(attempted_util) <= 1.0
    return None


def _design_guide_cleanup_rejection_category(row: dict | None, attempted_util: float | None = None) -> str:
    row_d = dict(row or {})
    explicit = str(row_d.get("rejection_category") or "").strip()
    if explicit:
        return explicit
    text = " ".join(
        str(row_d.get(key) or "")
        for key in (
            "failed_check_name",
            "failed_check_status",
            "failed_check_reason",
            "reason",
            "rejection_reason",
            "failed_candidate_reason",
            "limit_name",
        )
    ).lower()
    attempted_passed = _design_guide_cleanup_attempted_passed(row_d, attempted_util)
    if attempted_passed is True and attempted_util is not None:
        if float(attempted_util) < float(FINAL_ACCEPTED_MIN_FAMILY_UTIL):
            return "Safe but still below accepted efficiency floor"
        if float(attempted_util) > float(GUIDANCE_TARGET_UTIL_MAX):
            return "Safe but above preferred band, with no better preferred-band candidate"
    if "not executor" in text or "not executable" in text or "advisory" in text:
        return "Not executor-backed"
    if "superseded" in text or "combined same-click" in text or "combined cleanup" in text:
        return "Superseded by better combined same-click option"
    if "geometry locked" in text or "not permitted" in text or "locked" in text:
        return "Geometry locked / not permitted"
    if any(token in text for token in ("spacing", "detailing", "ductility", "fit", "minimum clear")):
        return "Unsafe - failed spacing/detailing/ductility"
    if any(token in text for token in ("serviceability", "deflection", "crack", "sls")):
        return "Unsafe - failed serviceability"
    if attempted_passed is False:
        return "Unsafe - failed capacity"
    if attempted_passed is True:
        return "Safe but still below accepted efficiency floor"
    return "Not executor-backed"


def _design_guide_cleanup_rejection_phrase(row: dict | None, category: str, attempted_util: float | None) -> str:
    row_d = dict(row or {})
