_FINAL_PUBLICATION_CTA_AUTHORITY = "FinalDesignGuidePublication.cta"
_FINAL_PUBLICATION_DISPLAY_AUTHORITY = "FinalDesignGuidePublication.display"
_FINAL_PUBLICATION_LEGACY_SESSION_METADATA_KEY = "_design_guide_legacy_publication_session_key_metadata"
_FINAL_PUBLICATION_LEGACY_SESSION_KEYS = (
    DESIGN_GUIDE_SIMPLE_CACHE_ITEMS_KEY,
    DESIGN_GUIDE_GUIDANCE_CACHE_DEBUG_KEY,
    DESIGN_GUIDE_GUIDANCE_CACHE_FP_KEY,
    DESIGN_GUIDE_GUIDANCE_CACHE_ITEMS_KEY,
    DESIGN_GUIDE_SIMPLE_CACHE_FP_KEY,
    DESIGN_GUIDE_PUBLICATION_FP_KEY,
    "design_guide_post_apply_display_truth",
    DESIGN_GUIDE_PRIMARY_APPLY_PAYLOAD_KEY,
    "design_guide_primary_button_contract",
    "design_guide_primary_button_contract_enabled",
    "design_guide_primary_display_truth",
)


def _final_publication_authority_hash_from_parts(
    *,
    cta_hash: object = None,
    display_hash: object = None,
) -> str:
    return _stable_final_publication_hash(
        {
            "cta_hash": str(cta_hash or ""),
            "display_hash": str(display_hash or ""),
            "authority": "FinalDesignGuidePublication",
        }
    )


def _final_publication_outcome_state_for_debug(
    *,
    item: dict | None = None,
    cta: dict | None = None,
    blocker_reason: object = None,
) -> str:
    item_d = dict(item or {})
    cta_d = dict(cta or {})
    status = str(item_d.get("status") or item_d.get("critical_status") or "").strip().upper()
    bucket = str(item_d.get("bucket") or "").strip().lower()
    display_state = str(item_d.get("display_state") or "").strip().upper()
    final_state = str(item_d.get("final_state_class") or item_d.get("final_state_type") or "").strip().lower()
    intent = str(item_d.get("guidance_intent") or "").strip().lower()
    title_text = str(item_d.get("title_main") or item_d.get("title") or "").strip().lower()
    if bool(cta_d.get("enabled") or cta_d.get("actionable")):
        return "ACTION"
    blocker_reason_text = str(blocker_reason or "").strip()
    blocker_reason_lower = blocker_reason_text.lower()
    terminal_no_action_reason = blocker_reason_text in {
        "terminal_accepted_state_has_no_same_flow_action",
        "terminal_or_non_action_card_has_no_same_flow_action",
        "terminal_pass_no_action",
        "terminal_overdesign_cleanup_no_second_cta",
    } or (
        "all required checks remain acceptable" in blocker_reason_lower
        and "inside the target band" in blocker_reason_lower
    )
    if (
        status in {"PASS", "GOOD", "OK"}
        or bucket == "pass"
        or item_d.get("design_guide_terminal_state")
    ) and (not blocker_reason_text or terminal_no_action_reason):
        return "PASS"
    if blocker_reason_text:
        return "BLOCKED"
    if status == "BLOCKED" or display_state == "BLOCKED" or bucket in {"blocked", "blocker"} or final_state == "blocker":
        return "BLOCKED"
    if "block" in intent:
        return "BLOCKED"
    if "blocked" in title_text and not bool(cta_d.get("enabled") or cta_d.get("actionable")):
        return "BLOCKED"
    if status in {"ERROR", "CRITICAL"} or bucket == "error":
        return "ERROR"
    return "PROOF_PENDING"


def _final_publication_same_object_verifier_payload(
    *,
    item: dict | None = None,
    debug_sink: dict | None = None,
    cta_authority: dict | None = None,
    display_authority: dict | None = None,
) -> dict:
    item_d = dict(item or {})
    debug_d = debug_sink if isinstance(debug_sink, dict) else {}
    existing_payload = dict(debug_d.get("final_publication_verifier_payload") or {})
    cta_payload = dict(
        (cta_authority or {}).get("cta")
        or existing_payload.get("cta")
        or {}
    )
    display_payload = dict(
        (display_authority or {}).get("display")
        or existing_payload.get("display")
        or {}
    )
    cta_hash = (
        (cta_authority or {}).get("cta_hash")
        or debug_d.get("final_publication_cta_hash")
        or existing_payload.get("final_publication_cta_hash")
    )
    display_hash = (
        (display_authority or {}).get("display_hash")
        or debug_d.get("final_publication_display_hash")
        or existing_payload.get("final_publication_display_hash")
    )
    selected_family = str(
        item_d.get("selected_family_id")
        or item_d.get("published_family_id")
        or item_d.get("cta_family_id")
        or debug_d.get("selected_family_id")
        or existing_payload.get("selected_family")
        or ""
    ).strip() or None
    selected_family = _canonical_overdesign_family_from_updates(
        selected_family,
        dict(
            dict(item_d.get("button_contract") or {}).get("updates")
            or dict(item_d.get("action_payload") or {}).get("updates")
            or dict(item_d.get("action_payload") or {}).get("resolved_candidate_updates")
            or item_d.get("updates")
            or cta_payload.get("updates")
            or {}
        ),
    )
    blocker_reason = (
        item_d.get("blocking_reason")
        or dict(item_d.get("button_contract") or {}).get("blocking_reason")
        or dict(item_d.get("button_contract") or {}).get("disabled_reason")
        or existing_payload.get("blocker_reason")
    )
    display_status = str(
        display_payload.get("status")
        or display_payload.get("display_state")
        or display_payload.get("colour_state")
        or ""
    ).strip().lower()
    display_badge = str(display_payload.get("badge") or "").strip().upper()
    display_blocker_explanation = str(
        display_payload.get("blocker_explanation") or ""
    ).strip()
    blocker_reason_text = str(blocker_reason or "").strip()
    blocker_reason_lower = blocker_reason_text.lower()
    display_terminal_no_action = display_blocker_explanation in {
        "terminal_accepted_state_has_no_same_flow_action",
        "terminal_or_non_action_card_has_no_same_flow_action",
    } or (
        "all required checks remain acceptable" in blocker_reason_lower
        and "inside the target band" in blocker_reason_lower
    )
    if (
        display_terminal_no_action
        and (display_status == "pass" or display_badge == "PASS")
        and not bool(cta_payload.get("enabled") or cta_payload.get("actionable"))
    ):
        blocker_reason = None
    outcome_state = _final_publication_outcome_state_for_debug(
        item=item_d,
        cta=cta_payload,
        blocker_reason=blocker_reason,
    )
    if (
        outcome_state == "PROOF_PENDING"
        and not blocker_reason
        and (display_status == "pass" or display_badge == "PASS")
        and not bool(cta_payload.get("enabled") or cta_payload.get("actionable"))
    ):
        outcome_state = "PASS"
    publication_hash = _stable_final_publication_hash(
        {
            "selected_family": selected_family,
            "outcome_state": outcome_state,
            "blocker_reason": blocker_reason,
            "cta": cta_payload,
            "display": display_payload,
            "cta_hash": str(cta_hash or ""),
            "display_hash": str(display_hash or ""),
        }
    )
    authority_hash = _final_publication_authority_hash_from_parts(
        cta_hash=cta_hash,
        display_hash=display_hash,
    )
    return {
        "authority": "FinalDesignGuidePublication",
        "final_publication_authority_hash": authority_hash,
        "publication_hash": publication_hash,
        "final_publication_cta_hash": cta_hash,
        "final_publication_display_hash": display_hash,
        "selected_family": selected_family,
        "outcome_state": outcome_state,
        "blocker_reason": blocker_reason,
        "cta": cta_payload,
        "display": display_payload,
        "debug_payload_mutation_allowed": False,
        "browser_expectation_source": "FinalDesignGuidePublication",
        "dom_expectation_source": "FinalDesignGuidePublication",
        "render_driving": False,
        "browser_driving": False,
    }


_FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_CANDIDATES = frozenset(
    {
        "duplicate_compute_proof_debug_payload_stamping",
        "duplicate_debug_session_publication_stamps",
        "repeated_verifier_debug_payload_stamping",
    }
)
_FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_SESSION_STATE_KEY = (
    "_design_guide_final_publication_duplicate_stamp_bypass_state"
)


def _final_publication_current_hash_from_debug(debug_sink: dict | None) -> str | None:
    if not isinstance(debug_sink, dict):
        return None
    controller_trace = dict(debug_sink.get("design_guide_controller_trace_only_parity") or {})
    controller_hash = (
        controller_trace.get("controller_publication_hash")
        or controller_trace.get("live_publication_hash")
        or debug_sink.get("design_guide_controller_publication_authority_hash")
        or debug_sink.get("final_visible_resolution_authority_hash")
        or debug_sink.get("final_visible_resolution_publication_hash")
    )
    controller_hash_text = str(controller_hash or "").strip()
    if controller_hash_text:
        return controller_hash_text
    payload = dict(debug_sink.get("final_publication_verifier_payload") or {})
    return (
        payload.get("publication_hash")
        or debug_sink.get("publication_hash")
        or debug_sink.get("final_publication_publication_hash")
        or debug_sink.get("final_publication_authority_hash")
    )


def _final_publication_duplicate_stamp_debug_force_rebuild(debug_sink: dict | None) -> bool:
    explicit_force = False
    if isinstance(debug_sink, dict):
        explicit_force = bool(
            debug_sink.get("final_publication_duplicate_stamp_bypass_debug_force_rebuild")
            or debug_sink.get("final_publication_debug_force_rebuild")
        )
    return bool(explicit_force or _design_guide_sidebar_debug_enabled())


def _final_publication_duplicate_stamp_bypass_key(candidate_id: str, stamp_key: str | None = None) -> str:
    suffix = str(stamp_key or "").strip()
    return f"{candidate_id}:{suffix}" if suffix else str(candidate_id)


def _final_publication_duplicate_stamp_session_state() -> dict:
    try:
        state = st.session_state.get(_FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_SESSION_STATE_KEY)
    except Exception:
        state = None
    return dict(state or {}) if isinstance(state, dict) else {}


def _final_publication_duplicate_stamp_bypass_decision(
    *,
    debug_sink: dict | None,
    candidate_id: str,
    current_publication_hash: object,
    stamp_key: str | None = None,
    existing_stamp_present: bool = True,
) -> dict:
    """Decide whether a duplicate debug/compat stamp rebuild can be skipped."""

    candidate = str(candidate_id or "")
    instance_key = _final_publication_duplicate_stamp_bypass_key(candidate, stamp_key)
    current_hash = str(current_publication_hash or "").strip()
    guard_hash = _final_publication_current_hash_from_debug(debug_sink)
    guard_hash_text = str(guard_hash or "").strip()
    if guard_hash_text:
        current_hash = guard_hash_text
    debug_force = _final_publication_duplicate_stamp_debug_force_rebuild(debug_sink)
    states = {}
    if isinstance(debug_sink, dict):
        states.update(dict(debug_sink.get("final_publication_duplicate_stamp_bypass_state") or {}))
    states.update(_final_publication_duplicate_stamp_session_state())
    previous_state = dict(states.get(instance_key) or {})
    previous_hash = str(previous_state.get("publication_hash") or "").strip()
    if candidate not in _FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_CANDIDATES:
        decision = "REBUILD"
        reason = "candidate_not_approved_for_bypass"
    elif debug_force:
        decision = "REBUILD"
        reason = "debug_force_rebuild"
    elif not current_hash:
        decision = "REBUILD"
        reason = "missing_current_publication_hash"
    elif not previous_hash:
        decision = "REBUILD"
        reason = "missing_previous_publication_hash"
    elif current_hash != previous_hash:
        decision = "REBUILD"
        reason = "stale_or_changed_publication_hash"
    elif not existing_stamp_present:
        decision = "SKIP_REBUILD"
        reason = "publication_hash_unchanged_session_state"
    else:
        decision = "SKIP_REBUILD"
        reason = "publication_hash_unchanged"
    row = {
        "candidate_id": candidate,
        "stamp_key": str(stamp_key or ""),
        "instance_key": instance_key,
        "publication_hash": current_hash or None,
        "publication_hash_source": (
            "DesignGuideController.publication_hash"
            if guard_hash_text
            else "legacy_final_publication_verifier_payload"
        ),
        "previous_publication_hash": previous_hash or None,
        "bypassed": decision == "SKIP_REBUILD",
        "decision": decision,
        "reason": reason,
        "debug_force_rebuild": debug_force,
        "product_behavior_changed": False,
        "affects_final_publication": False,
        "affects_cta": False,
        "affects_display": False,
        "affects_apply_payload": False,
        "affects_visible_wording": False,
    }
    if isinstance(debug_sink, dict):
        decisions = dict(debug_sink.get("final_publication_duplicate_stamp_bypass_decisions") or {})
        decisions[instance_key] = dict(row)
        debug_sink["final_publication_duplicate_stamp_bypass_decisions"] = decisions
        by_candidate = dict(
            debug_sink.get("final_publication_duplicate_stamp_bypass_decisions_by_candidate")
            or {}
        )
        entries = dict(by_candidate.get(candidate) or {})
        entries[instance_key] = dict(row)
        by_candidate[candidate] = entries
        debug_sink["final_publication_duplicate_stamp_bypass_decisions_by_candidate"] = by_candidate
        debug_sink["final_publication_duplicate_stamp_bypass_key"] = (
            "FinalDesignGuidePublication.publication_hash"
        )
        debug_sink["final_publication_duplicate_stamp_bypass_session_state_key"] = (
            _FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_SESSION_STATE_KEY
        )
    return row


def _record_final_publication_duplicate_stamp_rebuild(
    *,
    debug_sink: dict | None,
    candidate_id: str,
    current_publication_hash: object,
    stamp_key: str | None = None,
) -> None:
    if not isinstance(debug_sink, dict):
        return
    candidate = str(candidate_id or "")
    if candidate not in _FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_CANDIDATES:
        return
    current_hash = str(current_publication_hash or "").strip()
    canonical_hash = None
    if isinstance(debug_sink, dict):
        canonical_hash = _final_publication_current_hash_from_debug(debug_sink)
    canonical_hash_text = str(canonical_hash or "").strip()
    if canonical_hash_text:
        current_hash = canonical_hash_text
    if not current_hash:
        return
    instance_key = _final_publication_duplicate_stamp_bypass_key(candidate, stamp_key)
    states = dict(debug_sink.get("final_publication_duplicate_stamp_bypass_state") or {})
    states[instance_key] = {
        "candidate_id": candidate,
        "stamp_key": str(stamp_key or ""),
        "publication_hash": current_hash,
        "last_result": "rebuilt",
        "bypassed": False,
    }
    debug_sink["final_publication_duplicate_stamp_bypass_state"] = states
    session_states = _final_publication_duplicate_stamp_session_state()
    session_states[instance_key] = dict(states[instance_key])
    st.session_state[_FINAL_PUBLICATION_DUPLICATE_STAMP_BYPASS_SESSION_STATE_KEY] = session_states


def _stamp_final_publication_same_object_verifier_payload(
    *,
    item: dict | None = None,
    debug_sink: dict | None = None,
    cta_authority: dict | None = None,
    display_authority: dict | None = None,
) -> dict:
    payload = _final_publication_same_object_verifier_payload(
        item=item,
        debug_sink=debug_sink,
        cta_authority=cta_authority,
        display_authority=display_authority,
    )
    if isinstance(debug_sink, dict):
        decision = _final_publication_duplicate_stamp_bypass_decision(
            debug_sink=debug_sink,
            candidate_id="repeated_verifier_debug_payload_stamping",
            current_publication_hash=payload.get("publication_hash"),
            existing_stamp_present=bool(debug_sink.get("final_publication_verifier_payload")),
        )
        if decision.get("bypassed"):
            existing_verifier_payload = dict(
                debug_sink.get("final_publication_verifier_payload") or {}
            )
            payload_changed_under_same_hash = bool(
                existing_verifier_payload
                and any(
                    existing_verifier_payload.get(key) != payload.get(key)
                    for key in (
                        "selected_family",
                        "outcome_state",
                        "blocker_reason",
                        "cta",
                        "display",
                    )
                )
            )
            if payload_changed_under_same_hash:
                decision = dict(decision)
                decision["bypassed"] = False
                decision["decision"] = "REBUILD"
                decision["reason"] = "payload_changed_under_same_publication_hash"
                decisions = dict(
                    debug_sink.get("final_publication_duplicate_stamp_bypass_decisions")
                    or {}
                )
                instance_key = str(decision.get("instance_key") or "")
                if instance_key:
                    decisions[instance_key] = dict(decision)
                    debug_sink["final_publication_duplicate_stamp_bypass_decisions"] = decisions
            elif not isinstance(debug_sink.get("final_publication_verifier_payload"), dict):
                debug_sink["final_publication_verifier_payload"] = dict(payload)
                debug_sink["final_publication_publication_hash"] = payload["publication_hash"]
                debug_sink["publication_hash"] = payload["publication_hash"]
                debug_sink["final_publication_verifier_payload_bypassed_rebuild"] = True
            else:
                _canonicalize_legacy_design_guide_publication_session_storage(
                    debug_sink=debug_sink,
                    publication_payload=payload,
                )
                return dict(debug_sink.get("final_publication_verifier_payload") or payload)
        debug_sink["final_publication_verifier_payload"] = dict(payload)
        debug_sink["final_publication_publication_hash"] = payload["publication_hash"]
        debug_sink["publication_hash"] = payload["publication_hash"]
        _record_final_publication_duplicate_stamp_rebuild(
            debug_sink=debug_sink,
            candidate_id="repeated_verifier_debug_payload_stamping",
            current_publication_hash=payload.get("publication_hash"),
        )
        _canonicalize_legacy_design_guide_publication_session_storage(
            debug_sink=debug_sink,
            publication_payload=payload,
        )
    return payload


def _canonicalize_legacy_design_guide_publication_session_storage(
    *,
    debug_sink: dict | None = None,
    publication_payload: dict | None = None,
) -> dict:
    """Stamp legacy publication-shaped session keys as non-authoritative.

    Compatibility keys keep their existing value shape. The sidecar metadata is
    the canonical proof that they derive from FinalDesignGuidePublication and
    cannot act as a second publication authority.
    """

    payload = dict(publication_payload or {})
    if not payload and isinstance(debug_sink, dict):
        payload = dict(debug_sink.get("final_publication_verifier_payload") or {})
    authority_hash = (
        payload.get("final_publication_authority_hash")
        or (debug_sink or {}).get("final_publication_authority_hash")
    )
    publication_hash = (
        payload.get("publication_hash")
        or (debug_sink or {}).get("publication_hash")
        or (debug_sink or {}).get("final_publication_publication_hash")
    )
    if isinstance(debug_sink, dict):
        decision = _final_publication_duplicate_stamp_bypass_decision(
            debug_sink=debug_sink,
            candidate_id="duplicate_debug_session_publication_stamps",
            current_publication_hash=publication_hash,
            existing_stamp_present=bool(debug_sink.get("final_publication_legacy_session_key_metadata")),
        )
        if decision.get("bypassed"):
            session_metadata = st.session_state.get(_FINAL_PUBLICATION_LEGACY_SESSION_METADATA_KEY)
            if isinstance(session_metadata, dict) and not isinstance(
                debug_sink.get("final_publication_legacy_session_key_metadata"),
                dict,
            ):
                debug_sink["final_publication_legacy_session_key_metadata"] = dict(session_metadata)
                debug_sink["legacy_publication_session_keys_non_authoritative"] = True
                debug_sink["legacy_publication_session_keys_derived_from"] = "FinalDesignGuidePublication"
                debug_sink["final_publication_legacy_session_key_metadata_bypassed_rebuild"] = True
            return dict(debug_sink.get("final_publication_legacy_session_key_metadata") or session_metadata or {})
    metadata: dict[str, dict] = {}
    for key in _FINAL_PUBLICATION_LEGACY_SESSION_KEYS:
        present = key in st.session_state
        value = st.session_state.get(key) if present else None
        metadata[key] = {
            "present": bool(present),
            "legacy_non_authoritative": True,
            "compatibility_only": True,
            "derived_from": "FinalDesignGuidePublication",
            "final_publication_authority_hash": authority_hash,
            "publication_hash": publication_hash,
            "value_hash": _stable_final_publication_hash(value) if present else None,
            "may_override_publication": False,
        }
    st.session_state[_FINAL_PUBLICATION_LEGACY_SESSION_METADATA_KEY] = dict(metadata)
    if isinstance(debug_sink, dict):
        debug_sink["final_publication_legacy_session_key_metadata"] = dict(metadata)
        debug_sink["legacy_publication_session_keys_non_authoritative"] = True
        debug_sink["legacy_publication_session_keys_derived_from"] = "FinalDesignGuidePublication"
        _record_final_publication_duplicate_stamp_rebuild(
            debug_sink=debug_sink,
            candidate_id="duplicate_debug_session_publication_stamps",
            current_publication_hash=publication_hash,
        )
    return metadata


def _final_publication_cta_authority_payload(
    *,
    item: dict | None,
    debug: dict | None = None,
    button_contract: dict | None = None,
    action_payload: dict | None = None,
    source_precedence: dict | None = None,
    fallback_only: bool = False,
) -> dict:
    """Build the live CTA authority proof without rendering or routing actions."""

    item_d = dict(item or {})
    contract = dict(button_contract or item_d.get("button_contract") or {})
    payload = dict(action_payload or item_d.get("action_payload") or {})
    evidence = dict(item_d.get("candidate_search_evidence") or {})
    publication_selected_family = ""
    try:
        publication = _build_final_design_guide_publication(
            item=item_d,
            debug=dict(debug or {}),
            design_brain_result={},
            verifier_payload={
                "source": "inputs_page.final_publication_cta_authority_payload",
                "source_precedence": dict(source_precedence or {}),
            },
            publication_reason=str(
                item_d.get("publication_reason")
                or item_d.get("final_publication_reason")
                or ""
            ).strip()
            or None,
        )
        cta_d = publication.cta.to_dict()
        publication_selected_family = str(
            getattr(publication, "selected_family", "") or ""
        ).strip()
    except Exception:
        cta = _build_final_publication_cta_from_current_state(
            item=item_d,
            debug=dict(debug or {}),
            button_contract=contract,
            action_payload=payload,
            candidate_search_evidence=evidence,
            source_precedence=dict(source_precedence or {}),
        )
        cta_d = cta.to_dict()
    updates = dict(
        contract.get("updates")
        or payload.get("updates")
        or payload.get("resolved_candidate_updates")
        or item_d.get("updates")
        or {}
    )
    _publication_family_hint = str(
        publication_selected_family
        or item_d.get("selected_family_id")
        or item_d.get("published_family_id")
        or item_d.get("candidate_family_id")
        or (debug or {}).get("selected_family_id")
        or (debug or {}).get("published_family_id")
        or (debug or {}).get("candidate_family_id")
        or ""
    ).strip().upper()
    canonical_cta_family = _canonical_overdesign_family_from_updates(
        _publication_family_hint
        or item_d.get("selected_family_id")
        or item_d.get("published_family_id")
        or item_d.get("cta_family_id")
        or cta_d.get("family")
        or contract.get("family")
        or item_d.get("family"),
        updates,
    )
    if (
        str(canonical_cta_family or "").strip().lower() == "bending"
        and _publication_family_hint == "BENDING_OVERDESIGN_GOVERNS"
    ):
        canonical_cta_family = "BENDING_OVERDESIGN_GOVERNS"
    if canonical_cta_family:
        cta_d["family"] = canonical_cta_family
        cta_d["family_id"] = canonical_cta_family
        cta_d["cta_family_id"] = canonical_cta_family
        apply_payload_summary = dict(cta_d.get("apply_payload_summary") or {})
        if apply_payload_summary:
            apply_payload_summary["family"] = canonical_cta_family
            apply_payload_summary["family_id"] = canonical_cta_family
            apply_payload_summary["cta_family_id"] = canonical_cta_family
            cta_d["apply_payload_summary"] = apply_payload_summary
        one_click_action_handoff = dict(cta_d.get("one_click_action_handoff") or {})
        if one_click_action_handoff:
            one_click_action_handoff["family"] = canonical_cta_family
            one_click_action_handoff["family_id"] = canonical_cta_family
            one_click_action_handoff["cta_family_id"] = canonical_cta_family
            cta_d["one_click_action_handoff"] = one_click_action_handoff
    if str(canonical_cta_family or "").strip().upper() in {
        "BENDING_OVERDESIGN_GOVERNS",
        "COMBINED_OVERDESIGN_GOVERNS",
        "COMBINED_OVERDESIGN",
    }:
        if (
            str(canonical_cta_family or "").strip().upper() == "BENDING_OVERDESIGN_GOVERNS"
            and updates
        ):
            try:
                terminal_state_for_cta = dict(
                    (debug or {}).get("guidance_state_snapshot")
                    or (debug or {}).get("final_seed_state")
                    or _guidance_state_snapshot(_shared_state_snapshot())
                    or {}
                )
            except Exception:
                terminal_state_for_cta = {}
            if terminal_state_for_cta:
                trial_base_state = dict(terminal_state_for_cta)
                trial_base_state.update(dict(updates))
                try:
                    trial_base_overview = _collect_design_overview(
                        _guidance_state_snapshot(trial_base_state),
                        context=_build_design_actions_context(
                            _guidance_state_snapshot(trial_base_state)
                        ),
                    )
                except Exception:
                    trial_base_overview = {}
                trial_base_bending_util = _parse_util_value(
                    dict(trial_base_overview.get("utils") or {}).get("bending")
                )
                if (
                    trial_base_bending_util is not None
                    and float(trial_base_bending_util)
                    < float(FINAL_ACCEPTED_MIN_FAMILY_UTIL) - float(TARGET_BAND_EPS)
                ):
                    try:
                        terminal_bending_followup = _bending_only_target_band_cleanup_item(
                            trial_base_state,
                            trial_base_overview,
                            _design_mode_config(_design_optimisation_goal(trial_base_state)),
                            debug_sink={},
                            allow_terminalisation_fold=False,
                        )
                    except Exception:
                        terminal_bending_followup = None
                    followup_contract = dict(
                        (terminal_bending_followup or {}).get("button_contract") or {}
                    )
                    if (
                        not _design_guide_button_contract_enabled(followup_contract)
                        and isinstance(terminal_bending_followup, dict)
                    ):
                        try:
                            followup_contract = _design_guide_button_contract(
                                terminal_bending_followup,
                                state=trial_base_state,
                            )
                        except Exception:
                            followup_contract = dict(
                                (terminal_bending_followup or {}).get("button_contract") or {}
                            )
                    followup_resolution = _resolve_design_guide_controller_terminalisation_followup_updates(
                        item=terminal_bending_followup,
                        button_contract=followup_contract,
                    )
                    followup_updates = dict((followup_resolution or {}).get("updates") or {})
                    if (
                        str((followup_resolution or {}).get("action_type") or "").strip()
                        == "apply_resolved_candidate"
                        and followup_updates
                        and not _updates_match_state(trial_base_state, followup_updates)
                    ):
                        terminal_bending_updates = dict(updates)
                        terminal_bending_updates.update(followup_updates)
                        terminal_bending_state = dict(terminal_state_for_cta)
                        terminal_bending_state.update(terminal_bending_updates)
                        try:
                            terminal_bending_candidate = _evaluate_bending_only_target_band_prebuilt_candidate_with_service(
                                _guidance_state_snapshot(terminal_bending_state),
                                source="guidance:final_publication_cta_bending_overdesign_terminal_fold",
                                updates=terminal_bending_updates,
                            )
                        except Exception:
                            terminal_bending_candidate = None
                        terminal_bending_overview = dict(
                            (terminal_bending_candidate or {}).get("overview") or {}
                        )
                        terminal_bending_statuses = dict(
                            terminal_bending_overview.get("statuses") or {}
                        )
                        terminal_bending_util = _parse_util_value(
                            dict(terminal_bending_overview.get("utils") or {}).get("bending")
                        )
                        if (
                            isinstance(terminal_bending_candidate, dict)
                            and terminal_bending_util is not None
                            and float(FINAL_ACCEPTED_MIN_FAMILY_UTIL) - float(TARGET_BAND_EPS)
                            <= float(terminal_bending_util)
                            <= 1.0 + float(TARGET_BAND_EPS)
                            and not bool(terminal_bending_overview.get("any_fail"))
                            and _overview_required_checks_acceptable(terminal_bending_overview)
                            and not _candidate_preview_statuses_have_explicit_fail(
                                terminal_bending_statuses
                            )
                        ):
                            updates = dict(terminal_bending_updates)
                            terminal_bending_candidate_id = _guidance_cleanup_candidate_id(
                                "bending",
                                updates,
                            )
                            contract.update(
                                {
                                    "updates": dict(updates),
                                    "expected_util": float(terminal_bending_util),
                                    "candidate_id": terminal_bending_candidate_id,
                                    "source_candidate_id": terminal_bending_candidate_id,
                                    "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                                    "further_cleanup_available": False,
                                    "no_second_cta_required": True,
                                }
                            )
                            contract.pop("target_band_contract_blocked", None)
                            payload.update(
                                {
                                    "updates": dict(updates),
                                    "resolved_candidate_updates": dict(updates),
                                    "candidate_id": terminal_bending_candidate_id,
                                    "source_candidate_id": terminal_bending_candidate_id,
                                    "expected_util": float(terminal_bending_util),
                                    "candidate_post_util": float(terminal_bending_util),
                                    "resolved_candidate_post_util": float(terminal_bending_util),
                                    "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                                    "further_cleanup_available": False,
                                    "no_second_cta_required": True,
                                }
                            )
                            cta_d.update(
                                {
                                    "updates": dict(updates),
                                    "expected_util": float(terminal_bending_util),
                                    "candidate_id": terminal_bending_candidate_id,
                                    "source_candidate_id": terminal_bending_candidate_id,
                                    "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                                    "further_cleanup_available": False,
                                    "no_second_cta_required": True,
                                }
                            )
                            cta_d.pop("target_band_contract_blocked", None)
                            if isinstance(debug, dict):
                                debug["final_publication_cta_bending_terminal_fold_applied"] = True
                                debug["final_publication_cta_bending_terminal_fold_updates"] = dict(updates)
        if (
            str(canonical_cta_family or "").strip().upper()
            in {"COMBINED_OVERDESIGN_GOVERNS", "COMBINED_OVERDESIGN"}
            and updates
            and bool(set(updates) & _COMPOUND_SHEAR_UPDATE_KEYS)
        ):
            try:
                terminal_state_for_cta = dict(
                    (debug or {}).get("guidance_state_snapshot")
                    or (debug or {}).get("final_seed_state")
                    or _guidance_state_snapshot(_shared_state_snapshot())
                    or {}
                )
            except Exception:
                terminal_state_for_cta = {}
            if terminal_state_for_cta:
                try:
                    terminal_cta_merge = _publishable_same_click_shear_cleanup_merge(
                        terminal_state_for_cta,
                        dict(updates),
                    )
                except Exception:
                    terminal_cta_merge = {}
                terminal_cta_updates = dict((terminal_cta_merge or {}).get("updates") or {})
                terminal_cta_overview = dict((terminal_cta_merge or {}).get("overview") or {})
                terminal_cta_utils = dict(terminal_cta_overview.get("utils") or {})
                terminal_cta_objective_values = [
                    _parse_util_value(terminal_cta_utils.get("bending")),
                    _parse_util_value(terminal_cta_utils.get("shear")),
                    _parse_util_value(terminal_cta_overview.get("worst_util")),
                    _parse_util_value(terminal_cta_overview.get("governing_util")),
                    _parse_util_value((terminal_cta_merge or {}).get("expected_util")),
                ]
                terminal_cta_objective_values = [
                    float(value)
                    for value in terminal_cta_objective_values
                    if value is not None
                ]
                terminal_cta_expected = (
                    max(terminal_cta_objective_values)
                    if terminal_cta_objective_values
                    else None
                )
                terminal_cta_evidence = dict((terminal_cta_merge or {}).get("evidence") or {})
                if (
                    terminal_cta_updates
                    and terminal_cta_updates != updates
                    and terminal_cta_expected is not None
                    and not bool(terminal_cta_overview.get("any_fail"))
                    and _overview_required_checks_acceptable(terminal_cta_overview)
                    and not _candidate_preview_statuses_have_explicit_fail(
                        dict(terminal_cta_overview.get("statuses") or {})
                    )
                    and (
                        int(terminal_cta_evidence.get("target_band_candidate_count") or 0) > 0
                        or str(terminal_cta_evidence.get("terminal_candidate_status") or "").strip().upper()
                        == "TERMINAL_TARGET_BAND"
                    )
                ):
                    updates = dict(terminal_cta_updates)
                    terminal_cta_candidate_id = _guidance_cleanup_candidate_id(
                        "combined",
                        updates,
                    )
                    contract.update(
                        {
                            "updates": dict(updates),
                            "expected_util": float(terminal_cta_expected),
                            "candidate_id": terminal_cta_candidate_id,
                            "source_candidate_id": terminal_cta_candidate_id,
                            "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                            "further_cleanup_available": False,
                            "no_second_cta_required": True,
                        }
                    )
                    contract.pop("target_band_contract_blocked", None)
                    payload.update(
                        {
                            "updates": dict(updates),
                            "resolved_candidate_updates": dict(updates),
                            "candidate_id": terminal_cta_candidate_id,
                            "source_candidate_id": terminal_cta_candidate_id,
                            "expected_util": float(terminal_cta_expected),
                            "candidate_post_util": float(terminal_cta_expected),
                            "resolved_candidate_post_util": float(terminal_cta_expected),
                            "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                            "further_cleanup_available": False,
                            "no_second_cta_required": True,
                        }
                    )
                    cta_d.update(
                        {
                            "updates": dict(updates),
                            "expected_util": float(terminal_cta_expected),
                            "candidate_id": terminal_cta_candidate_id,
                            "source_candidate_id": terminal_cta_candidate_id,
                            "terminal_candidate_status": "TERMINAL_TARGET_BAND",
                            "further_cleanup_available": False,
                            "no_second_cta_required": True,
                        }
                    )
                    cta_d.pop("target_band_contract_blocked", None)
                    if isinstance(debug, dict):
                        debug["final_publication_cta_combined_terminal_fold_applied"] = True
                        debug["final_publication_cta_combined_terminal_fold_updates"] = dict(updates)
        expected_util_for_terminal = _parse_util_value(
            cta_d.get("expected_util")
            or contract.get("expected_util")
            or evidence.get("best_safe_final_util")
            or evidence.get("selected_candidate_util")
        )
        if (
            updates
            and expected_util_for_terminal is not None
            and float(expected_util_for_terminal)
            < float(FINAL_ACCEPTED_MIN_FAMILY_UTIL) - float(TARGET_BAND_EPS)
        ):
            exact_proof_sources = (
                dict(item_d.get("exact_stop_proof") or {}),
                dict((debug or {}).get("exact_stop_proof") or {}),
            )
            folded_terminal = _overdesign_terminal_folded_cleanup_from_proof_sources(
                *exact_proof_sources
            )
            folded_updates: dict = dict(folded_terminal.get("updates") or {})
            folded_candidate_id = str(folded_terminal.get("candidate_id") or "").strip()
            if folded_updates:
                updates = dict(folded_updates)
                cta_d["updates"] = dict(folded_updates)
                cta_d["terminal_candidate_status"] = "TERMINAL_TARGET_BAND"
                cta_d["further_cleanup_available"] = False
                cta_d["folded_candidate_ids"] = [
                    value
                    for value in (
                        str(contract.get("candidate_id") or contract.get("source_candidate_id") or "").strip(),
                        folded_candidate_id,
                    )
                    if value
                ]
                cta_d["candidate_id"] = folded_candidate_id or cta_d.get("candidate_id")
                cta_d["source_candidate_id"] = folded_candidate_id or cta_d.get("source_candidate_id")
            else:
                cleanup_no_action_sources = (
                    evidence,
                    dict(contract.get("candidate_search_evidence") or {}),
                    dict(payload.get("candidate_search_evidence") or {}),
                    dict(item_d.get("exact_stop_proof") or {}),
                    dict((debug or {}).get("exact_stop_proof") or {}),
                )
                cleanup_no_action_proof = _overdesign_no_second_cta_proof_from_sources(
                    *cleanup_no_action_sources
                )
                if cleanup_no_action_proof:
                    cta_d["enabled"] = False
                    cta_d["actionable"] = False
                    cta_d["action_type"] = None
                    cta_d["label"] = None
                    cta_d["updates"] = {}
                    cta_d["disabled_reason"] = "terminal_overdesign_cleanup_no_second_cta"
                    cta_d["terminal_candidate_status"] = (
                        cta_d.get("terminal_candidate_status")
                        or contract.get("terminal_candidate_status")
                        or evidence.get("terminal_candidate_status")
                        or cleanup_no_action_proof.get("terminal_candidate_status")
                        or "TERMINAL_EXACT_STOP"
                    )
                    cta_d["further_cleanup_available"] = False
                    cta_d["no_second_cta_required"] = True
                    cta_d["final_publication_cta_terminal_no_action"] = True
    if _final_design_guide_publication_is_terminal_no_action_surface(
        item=item_d,
        debug=dict(debug or {}),
        selected_family=canonical_cta_family,
    ):
        cta_d["enabled"] = False
        cta_d["actionable"] = False
        cta_d["action_type"] = None
        cta_d["label"] = None
        cta_d["disabled_reason"] = "terminal_pass_no_action"
    if bool(cta_d.get("enabled") or cta_d.get("actionable")):
        cta_d["updates"] = dict(updates)
    else:
        cta_d["updates"] = {}
    live_surface = {
        "enabled": bool(contract.get("enabled") or contract.get("actionable")),
        "family_id": canonical_cta_family,
        "cta_family_id": canonical_cta_family,
        "updates": dict(updates),
        "label": str(
            item_d.get("primary_action")
            or item_d.get("cta_label")
            or contract.get("label")
            or ""
        ).strip()
        or None,
        "disabled_reason": str(
            contract.get("disabled_reason")
            or contract.get("blocking_reason")
            or item_d.get("blocking_reason")
            or ""
        ).strip()
        or None,
        "action_type": str(
            contract.get("action_type")
            or item_d.get("action_type")
            or payload.get("action_type")
            or ""
        ).strip()
        or None,
        "apply_payload_fingerprint": _stable_final_publication_hash(payload or {"updates": updates}),
        "executor_backed_proof": dict(cta_d.get("executor_backed_proof") or {}),
        "stale_fresh_token_proof": dict(cta_d.get("stale_fresh_token_proof") or {}),
        "source_precedence_proof": dict(cta_d.get("source_precedence_proof") or {}),
        "one_click_action_handoff": dict(cta_d.get("one_click_action_handoff") or {}),
    }
    compare_fields = (
        "enabled",
        "family_id",
        "cta_family_id",
        "updates",
        "label",
        "disabled_reason",
        "action_type",
        "apply_payload_fingerprint",
        "executor_backed_proof",
        "stale_fresh_token_proof",
        "source_precedence_proof",
        "one_click_action_handoff",
    )
    mismatches = {
        key: {"live": live_surface.get(key), "publication_cta": cta_d.get(key)}
        for key in compare_fields
        if live_surface.get(key) != cta_d.get(key)
    }
    cta_hash = _stable_final_publication_hash(
        {key: cta_d.get(key) for key in compare_fields}
    )
    return {
        "authority": _FINAL_PUBLICATION_CTA_AUTHORITY,
        "cta": {key: cta_d.get(key) for key in compare_fields},
        "cta_hash": cta_hash,
        "live_surface": live_surface,
        "matches_live": not bool(mismatches),
        "mismatches": mismatches,
        "fallback_only": bool(fallback_only),
        "product_driving": True,
        "render_driving": False,
        "apply_routing_owner": "inputs_page",
    }


def _stamp_final_publication_cta_authority(
    *,
    item: dict | None,
    debug_sink: dict | None = None,
    button_contract: dict | None = None,
    action_payload: dict | None = None,
    fallback_only: bool = False,
) -> tuple[dict, dict]:
    """Attach CTA authority proof to the live contract without changing CTA semantics."""

    contract = dict(button_contract or {})
    authority = _final_publication_cta_authority_payload(
        item=item,
        debug=debug_sink,
        button_contract=contract,
        action_payload=action_payload,
        source_precedence={
            "button_contract_source": "FinalDesignGuidePublication.cta",
            "update_payload_source": "FinalDesignGuidePublication.cta",
            "candidate_source": "FinalDesignGuidePublication.cta",
        },
        fallback_only=fallback_only,
    )
    contract["final_publication_cta_authority"] = _FINAL_PUBLICATION_CTA_AUTHORITY
    contract["final_publication_cta_hash"] = authority["cta_hash"]
    contract["final_publication_cta_matches_live"] = bool(authority["matches_live"])
    contract["final_publication_cta_fallback_only"] = bool(fallback_only)
    if isinstance(debug_sink, dict):
        publication_hash = _final_publication_authority_hash_from_parts(
            cta_hash=authority["cta_hash"],
            display_hash=debug_sink.get("final_publication_display_hash"),
        )
        debug_sink["final_publication_cta_authority"] = _FINAL_PUBLICATION_CTA_AUTHORITY
        debug_sink["final_publication_cta_hash"] = authority["cta_hash"]
        debug_sink["final_publication_cta_matches_live"] = bool(authority["matches_live"])
        debug_sink["final_publication_cta_fallback_only"] = bool(fallback_only)
        debug_sink["final_publication_cta_authority_payload"] = dict(authority)
        debug_sink["final_publication_authority_hash"] = publication_hash
        _stamp_final_publication_same_object_verifier_payload(
            item=item,
            debug_sink=debug_sink,
            cta_authority=authority,
        )
    return contract, authority


def _apply_final_visible_contract_binding_cta_authority_projection(
    *,
    item: dict | None,
    debug_sink: dict | None = None,
    button_contract: dict | None = None,
    action_payload: dict | None = None,
    fallback_only: bool = False,
) -> tuple[dict, dict]:
    """Apply final-visible CTA authority projection without branch-local stamping."""

    return _stamp_final_publication_cta_authority(
        item=dict(item or {}),
        debug_sink=debug_sink if isinstance(debug_sink, dict) else None,
        button_contract=dict(button_contract or {}),
        action_payload=dict(action_payload or {}),
        fallback_only=bool(fallback_only),
    )


def _apply_final_publication_cta_to_primary_render_contract(
    *,
    item: dict | None,
    existing_contract: dict | None,
    debug_sink: dict | None,
    state: dict | None,
) -> tuple[dict, bool]:
    """Project existing FinalDesignGuidePublication CTA authority into card rendering."""

    item_d = dict(item or {})
    contract = dict(existing_contract or {})
    debug_d = dict(debug_sink or {})
    session_debug = {}
    try:
        session_debug_value = st.session_state.get(DESIGN_GUIDE_DEBUG_BUNDLE_KEY)
        if isinstance(session_debug_value, dict):
            session_debug = dict(session_debug_value)
    except Exception:
        session_debug = {}
    existing_contract_is_enabled_action = bool(
        _design_guide_button_contract_enabled(contract)
        and str(contract.get("action_type") or "").strip()
        and dict(contract.get("updates") or {})
    )
    if (
        not existing_contract_is_enabled_action
        and _final_design_guide_publication_is_terminal_no_action_surface(
        item=item_d,
        debug={**session_debug, **debug_d},
        )
    ):
        return (
            {
                **contract,
                "enabled": False,
                "actionable": False,
                "action_type": None,
                "updates": {},
                "blocking_reason": "terminal_pass_no_action",
                "disabled_reason": "terminal_pass_no_action",
                "final_publication_cta_render_projection": True,
                "final_publication_cta_authority": _FINAL_PUBLICATION_CTA_AUTHORITY,
                "final_publication_cta_no_action_projection": True,
                "final_publication_cta_terminal_no_action": True,
            },
            True,
        )
    verifier = dict(
        item_d.get("final_publication_verifier_payload")
        or debug_d.get("final_publication_verifier_payload")
        or session_debug.get("final_publication_verifier_payload")
        or {}
    )
    authority_payload = dict(
        debug_d.get("final_publication_cta_authority_payload")
        or session_debug.get("final_publication_cta_authority_payload")
        or {}
    )
    cta = dict(
        verifier.get("cta")
        or item_d.get("final_publication_cta")
        or debug_d.get("final_publication_cta")
        or session_debug.get("final_publication_cta")
        or authority_payload.get("cta")
        or {}
    )
    cta_terminal_no_action = bool(
        cta.get("final_publication_cta_terminal_no_action")
        or cta.get("no_second_cta_required")
        or str(cta.get("terminal_candidate_status") or "").strip().upper()
        in {"TERMINAL_EXACT_STOP", "TERMINAL_BLOCKED_WITH_PROOF"}
    )
    if not bool(cta.get("enabled") or cta.get("actionable")):
        if not cta_terminal_no_action:
            try:
                derivation_contract = (
                    contract
                    if bool(contract.get("enabled") or contract.get("actionable"))
                    else dict(item_d.get("button_contract") or contract)
                )
                derived_authority_payload = _final_publication_cta_authority_payload(
                    item=item_d,
                    debug={**session_debug, **debug_d},
                    button_contract=derivation_contract,
                    action_payload=dict(item_d.get("action_payload") or {}),
                )
            except Exception:
                derived_authority_payload = {}
            derived_cta = dict(derived_authority_payload.get("cta") or {})
            if derived_cta:
                authority_payload = dict(derived_authority_payload)
                cta = dict(derived_cta)
                cta_terminal_no_action = bool(
                    cta.get("final_publication_cta_terminal_no_action")
                    or cta.get("no_second_cta_required")
                    or str(cta.get("terminal_candidate_status") or "").strip().upper()
                    in {"TERMINAL_EXACT_STOP", "TERMINAL_BLOCKED_WITH_PROOF"}
                )
    if not bool(cta.get("enabled") or cta.get("actionable")):
        if cta:
            disabled_projected = {
                **contract,
                "enabled": False,
                "actionable": False,
                "action_type": None,
                "updates": {},
                "blocking_reason": cta.get("disabled_reason") or contract.get("blocking_reason"),
                "disabled_reason": cta.get("disabled_reason") or contract.get("disabled_reason"),
                "final_publication_cta_render_projection": True,
                "final_publication_cta_authority": _FINAL_PUBLICATION_CTA_AUTHORITY,
                "final_publication_cta_hash": (
                    verifier.get("final_publication_cta_hash")
                    or debug_d.get("final_publication_cta_hash")
                    or authority_payload.get("cta_hash")
                    or contract.get("final_publication_cta_hash")
                ),
                "final_publication_cta_no_action_projection": True,
                "final_publication_cta_terminal_no_action": bool(cta_terminal_no_action),
                "no_second_cta_required": bool(cta_terminal_no_action),
            }
            return disabled_projected, True
        return contract, False
    if cta.get("disabled_reason"):
        return contract, False
    cta_action_type = str(
        cta.get("action_type")
        or dict(cta.get("one_click_action_handoff") or {}).get("action_type")
        or contract.get("action_type")
        or item_d.get("action_type")
        or ""
    ).strip()
    if not cta_action_type:
        return contract, False
    updates = dict(
        cta.get("updates")
        or dict(cta.get("apply_payload_summary") or {}).get("updates")
        or {}
    )
    if not updates:
        updates = dict(contract.get("updates") or {})
    if not updates:
        updates = dict(_resolve_recommendation_updates(item_d, state=state) or {})
    if not updates:
        payload = dict(item_d.get("action_payload") or {})
        updates = dict(
            payload.get("resolved_candidate_updates")
            or payload.get("updates")
            or item_d.get("updates")
            or item_d.get("selected_action_updates")
            or {}
        )
    if not updates:
        return contract, False
    executor_proof = dict(cta.get("executor_backed_proof") or {})
    if executor_proof and not bool(executor_proof.get("executor_backed")):
        return contract, False
    if executor_proof and executor_proof.get("preview_pass") is False:
        return contract, False
    handoff = dict(cta.get("one_click_action_handoff") or {})
    cta_family = str(
        cta.get("cta_family_id")
        or cta.get("family_id")
        or cta.get("family")
        or contract.get("family")
        or item_d.get("selected_action_family")
        or item_d.get("family")
        or item_d.get("check_key")
        or ""
    ).strip()
    cta_family = (
        _canonical_family_owned_shear_overdesign_apply_family(
            cta_family,
            updates,
            context={**item_d, **contract, **cta},
        )
        or cta_family
    )
    overdesign_context_family = ""
    for family_source in (
        cta.get("selected_family_id"),
        cta.get("published_family_id"),
        cta.get("cta_family_id"),
        cta.get("family_id"),
        contract.get("selected_family_id"),
        contract.get("published_family_id"),
        contract.get("cta_family_id"),
        contract.get("family_id"),
        item_d.get("selected_family_id"),
        item_d.get("published_family_id"),
        item_d.get("cta_family_id"),
        item_d.get("family_id"),
        debug_d.get("selected_family_id"),
        debug_d.get("published_family_id"),
        debug_d.get("cta_family_id"),
    ):
        family_text = str(family_source or "").strip()
        if family_text.upper() in _OVERDESIGN_PUBLICATION_FAMILY_IDS:
            overdesign_context_family = family_text
            break
    cta_family = (
        _canonical_overdesign_family_from_updates(
            overdesign_context_family or cta_family,
            updates,
        )
        or cta_family
    )
    overdesign_family = str(cta_family or "").strip().upper()
    if overdesign_family in {
        "BENDING_OVERDESIGN_GOVERNS",
        "COMBINED_OVERDESIGN_GOVERNS",
        "COMBINED_OVERDESIGN",
    }:
        proof_sources = (
            dict(cta.get("candidate_search_evidence") or {}),
            dict(contract.get("candidate_search_evidence") or {}),
            dict(item_d.get("candidate_search_evidence") or {}),
            dict(debug_d.get("candidate_search_evidence") or {}),
            dict(session_debug.get("candidate_search_evidence") or {}),
            dict(item_d.get("exact_stop_proof") or {}),
            dict(debug_d.get("exact_stop_proof") or {}),
            dict(session_debug.get("exact_stop_proof") or {}),
        )
        folded_terminal = _overdesign_terminal_folded_cleanup_from_proof_sources(
            *proof_sources
        )
        if folded_terminal:
            updates = dict(folded_terminal.get("updates") or updates)
            cta["updates"] = dict(updates)
            cta["terminal_candidate_status"] = str(
                folded_terminal.get("terminal_candidate_status")
                or "TERMINAL_TARGET_BAND"
            )
            cta["further_cleanup_available"] = False
            folded_candidate_id_for_projection = str(
                folded_terminal.get("candidate_id") or ""
            ).strip()
            if folded_candidate_id_for_projection:
                cta["candidate_id"] = folded_candidate_id_for_projection
                cta["source_candidate_id"] = folded_candidate_id_for_projection
            if authority_payload:
                authority_payload.setdefault("terminal_folded_cleanup", dict(folded_terminal))
        terminal_status = ""
        target_candidate_count = 0
        expected_for_terminal_gate = None
        if folded_terminal:
            terminal_status = str(
                folded_terminal.get("terminal_candidate_status")
                or "TERMINAL_TARGET_BAND"
            ).strip().upper()
            try:
                target_candidate_count = max(
                    target_candidate_count,
                    int(folded_terminal.get("target_band_candidate_count") or 0),
                )
            except Exception:
                pass
        for proof_source in _iter_overdesign_proof_dicts(*proof_sources):
            if not isinstance(proof_source, dict) or not proof_source:
                continue
            if not terminal_status:
                terminal_status = str(
                    proof_source.get("terminal_candidate_status") or ""
                ).strip().upper()
            for count_key in (
                "target_band_candidate_count",
                "executable_target_band_candidate_count",
            ):
                try:
                    target_candidate_count = max(
                        target_candidate_count,
                        int(proof_source.get(count_key) or 0),
                    )
                except Exception:
                    pass
            if expected_for_terminal_gate is None:
                expected_for_terminal_gate = _parse_util_value(
                    proof_source.get("selected_candidate_util")
                    or proof_source.get("best_safe_final_util")
                    or proof_source.get("closest_safe_candidate_util")
                    or proof_source.get("expected_util")
                    or proof_source.get("preview_util")
                )
        terminal_no_second_cta = any(
            bool(proof_source.get("no_second_cta_required"))
            or bool(proof_source.get("best_safe_candidate_applied"))
            for proof_source in _iter_overdesign_proof_dicts(*proof_sources)
            if isinstance(proof_source, dict)
        )
        if expected_for_terminal_gate is None:
            expected_for_terminal_gate = _parse_util_value(
                cta.get("expected_util")
                or dict(cta.get("apply_payload_summary") or {}).get("expected_util")
                or contract.get("expected_util")
                or item_d.get("expected_util")
            )
        terminal_status_is_valid = terminal_status in {
            "TERMINAL_TARGET_BAND",
            "TERMINAL_EXACT_STOP",
            "TERMINAL_BLOCKED_WITH_PROOF",
        }
        if (
            expected_for_terminal_gate is not None
            and float(expected_for_terminal_gate)
            < float(FINAL_ACCEPTED_MIN_FAMILY_UTIL) - float(TARGET_BAND_EPS)
            and target_candidate_count <= 0
        ):
            terminal_no_action = bool(
                terminal_status_is_valid
                or terminal_no_second_cta
                or terminal_status in {"TERMINAL_EXACT_STOP", "TERMINAL_BLOCKED_WITH_PROOF"}
            )
            return (
                {
                    **contract,
                    "enabled": False,
                    "actionable": False,
                    "action_type": None,
                    "updates": {},
                    "blocking_reason": (
                        "terminal_overdesign_cleanup_no_second_cta"
                        if terminal_no_action
                        else "non_terminal_overdesign_cleanup_candidate"
                    ),
                    "disabled_reason": (
                        "terminal_overdesign_cleanup_no_second_cta"
                        if terminal_no_action
                        else "non_terminal_overdesign_cleanup_candidate"
                    ),
                    "terminal_candidate_status": (
                        terminal_status or "NON_TERMINAL_FURTHER_CLEANUP_AVAILABLE"
                    ),
                    "further_cleanup_available": False if terminal_no_action else True,
                    "final_publication_cta_render_projection": True,
                    "final_publication_cta_authority": _FINAL_PUBLICATION_CTA_AUTHORITY,
                    "final_publication_cta_no_action_projection": True,
                    "final_publication_cta_terminal_no_action": bool(terminal_no_action),
                    "no_second_cta_required": bool(terminal_no_action),
                },
                True,
            )
    candidate_id = str(
        handoff.get("candidate_id")
        or cta.get("source_candidate_id")
        or cta.get("candidate_id")
        or contract.get("source_candidate_id")
        or contract.get("candidate_id")
        or item_d.get("source_candidate_id")
        or item_d.get("candidate_id")
        or ""
    ).strip()
    projected = {
        **contract,
        "enabled": True,
        "actionable": True,
        "action_type": cta_action_type,
        "family": cta_family or contract.get("family"),
        "family_id": cta_family or contract.get("family_id"),
        "selected_family_id": cta_family or contract.get("selected_family_id"),
        "published_family_id": cta_family or contract.get("published_family_id"),
        "cta_family_id": cta_family or contract.get("cta_family_id"),
        "apply_payload_family_id": cta_family or contract.get("apply_payload_family_id"),
        "updates": dict(updates),
        "executor_backed": True,
        "safe_executor_backed": True,
        "is_executable": True,
        "blocking_reason": None,
        "disabled_reason": None,
        "preview_pass": True if executor_proof.get("preview_pass") is True else contract.get("preview_pass", True),
        "label": cta.get("label") or contract.get("label"),
        "source_candidate_id": candidate_id or contract.get("source_candidate_id"),
        "candidate_id": candidate_id or contract.get("candidate_id"),
        "final_publication_cta_render_projection": True,
        "final_publication_cta_authority": _FINAL_PUBLICATION_CTA_AUTHORITY,
        "final_publication_cta_hash": (
            verifier.get("final_publication_cta_hash")
            or debug_d.get("final_publication_cta_hash")
            or authority_payload.get("cta_hash")
            or contract.get("final_publication_cta_hash")
        ),
    }
    return projected, True


def _final_publication_display_authority_payload(
    *,
    view_model: dict | None = None,
    render_model: dict | None = None,
    fallback_shell_model: dict | None = None,
    fallback_only: bool = False,
) -> dict:
    """Build the live display authority proof without rendering HTML."""

    display = _build_final_publication_display_from_current_card_model(
        view_model=dict(view_model or {}),
        render_model=dict(render_model or {}),
        fallback_shell_model=dict(fallback_shell_model or {}),
    )
    view_model_d = dict(view_model or {})
    display_d = display.to_dict()
    authority_fields = {
        "selected_family_id": view_model_d.get("selected_family_id"),
        "published_family_id": view_model_d.get("published_family_id"),
        "cta_family_id": view_model_d.get("cta_family_id"),
        "apply_payload_family_id": view_model_d.get("apply_payload_family_id"),
        "title": display_d.get("title"),
        "badge": display_d.get("badge"),
        "summary": display_d.get("summary"),
        "status": display_d.get("status"),
        "bucket": display_d.get("bucket"),
        "colour_state": display_d.get("colour_state"),
        "card_class": display_d.get("card_class"),
        "display_state": display_d.get("display_state"),
        "blocker_explanation": display_d.get("blocker_explanation"),
        "expanded_evidence_sections": display_d.get("expanded_evidence_sections"),
        "final_card_model_hash": display_d.get("final_card_model_hash"),
        "render_fallback_shell_hash": display_d.get("render_fallback_shell_hash"),
    }
    return {
        "authority": _FINAL_PUBLICATION_DISPLAY_AUTHORITY,
        "display": authority_fields,
        "display_hash": _stable_final_publication_authority_hash(authority_fields),
        "matches_live": True,
        "mismatches": {},
        "fallback_only": bool(fallback_only),
        "product_driving": True,
        "render_driving": False,
    }


def _stamp_final_publication_display_authority(
    *,
    view_model: dict | None = None,
    render_model: dict | None = None,
    debug_sink: dict | None = None,
    fallback_shell_model: dict | None = None,
    fallback_only: bool = False,
) -> dict:
    """Attach display authority proof to live debug/view surfaces."""

    authority = _final_publication_display_authority_payload(
        view_model=view_model,
        render_model=render_model,
        fallback_shell_model=fallback_shell_model,
        fallback_only=fallback_only,
    )
    if isinstance(debug_sink, dict):
        publication_hash = _final_publication_authority_hash_from_parts(
            cta_hash=debug_sink.get("final_publication_cta_hash"),
            display_hash=authority["display_hash"],
        )
        debug_sink["final_publication_display_authority"] = _FINAL_PUBLICATION_DISPLAY_AUTHORITY
        debug_sink["final_publication_display_hash"] = authority["display_hash"]
        debug_sink["final_publication_display_matches_live"] = bool(authority["matches_live"])
        debug_sink["final_publication_display_fallback_only"] = bool(fallback_only)
        debug_sink["final_publication_display_authority_payload"] = dict(authority)
        debug_sink["final_publication_authority_hash"] = publication_hash
        _stamp_final_publication_same_object_verifier_payload(
            debug_sink=debug_sink,
            display_authority=authority,
        )
    return authority


def _collapsed_guidance_item_from_final_publication_authority(
    *,
    item: dict | None,
    debug_sink: dict | None = None,
    publication_reason: str | None = None,
    fallback_only: bool = False,
) -> dict:
    """Build collapsed-guidance item shape from DesignGuideController authority.

    This is a narrow live-wiring adapter. It preserves the existing item shape
    through compatibility data and keeps fallback/non-authoritative markers
    visible for verifiers.
    """

    legacy_item = dict(item or {})
    if not legacy_item:
        return {}
    try:
        debug = debug_sink if isinstance(debug_sink, dict) else {}
        controller_response = _run_design_guide_controller_publication_authority(
            _DesignGuideControllerRequest(
                item=dict(legacy_item),
                debug=dict(debug or {}),
                design_brain_result=dict(debug.get("design_brain_result") or {}),
                verifier_payload=dict(debug.get("final_publication_verifier_payload") or {}),
                final_visible_resolution={},
                guidance_debug=dict(debug or {}),
                publication_reason=publication_reason,
                source="inputs_page_collapsed_guidance_replacement",
            )
        )
        collapsed_item = dict(controller_response.collapsed_guidance_item or {})
        collapsed_item["collapsed_guidance_replacement_authority"] = "DesignGuideController"
        collapsed_item["collapsed_guidance_replacement_inner_authority"] = "FinalDesignGuidePublication"
        collapsed_item["collapsed_guidance_replacement_authority_hash"] = controller_response.publication_hash
        collapsed_item["collapsed_guidance_replacement_fallback_only"] = bool(fallback_only)
        collapsed_item["collapsed_guidance_replacement_matches_publication"] = True
        collapsed_item["collapsed_guidance_replacement_controller_hash"] = controller_response.controller_hash
        collapsed_item["collapsed_guidance_replacement_controller_request_hash"] = (
            controller_response.request_hash
        )
        collapsed_item["collapsed_guidance_replacement_controller_request_source"] = (
            controller_response.request_source
        )
        collapsed_item["collapsed_guidance_replacement_controller_memo_cache_hit"] = (
            controller_response.memo_cache_hit
        )
        collapsed_item["collapsed_guidance_replacement_controller_memo_cache_key"] = (
            controller_response.memo_cache_key
        )
        collapsed_item["collapsed_guidance_replacement_controller_memo_cache_reason"] = (
            controller_response.memo_cache_reason
        )
        if isinstance(debug_sink, dict):
            debug_sink["collapsed_guidance_replacement_authority"] = "DesignGuideController"
            debug_sink["collapsed_guidance_replacement_inner_authority"] = "FinalDesignGuidePublication"
            debug_sink["collapsed_guidance_replacement_authority_hash"] = controller_response.publication_hash
            debug_sink["collapsed_guidance_replacement_adapter_hash"] = collapsed_item.get(
                "collapsed_guidance_item_hash"
            )
            debug_sink["collapsed_guidance_replacement_fallback_only"] = bool(fallback_only)
            debug_sink["design_guide_controller_collapsed_replacement_live_wired"] = True
            debug_sink["design_guide_controller_collapsed_replacement_hash"] = (
                controller_response.controller_hash
            )
            debug_sink["design_guide_controller_collapsed_replacement_request_hash"] = (
                controller_response.request_hash
            )
            debug_sink["design_guide_controller_collapsed_replacement_request_source"] = (
                controller_response.request_source
            )
            debug_sink["design_guide_controller_collapsed_replacement_memo_cache_hit"] = (
                controller_response.memo_cache_hit
            )
            debug_sink["design_guide_controller_collapsed_replacement_memo_cache_key"] = (
                controller_response.memo_cache_key
            )
            debug_sink["design_guide_controller_collapsed_replacement_memo_cache_reason"] = (
                controller_response.memo_cache_reason
            )
            debug_sink["design_guide_controller_collapsed_replacement_product_driving"] = True
            debug_sink["design_guide_controller_collapsed_replacement_render_driving"] = False
            debug_sink["design_guide_controller_collapsed_replacement_apply_driving"] = False
            debug_sink["design_guide_controller_collapsed_replacement_session_driving"] = False
        return collapsed_item
    except Exception as exc:
        fallback_item = dict(legacy_item)
        fallback_item["collapsed_guidance_replacement_authority"] = "legacy_fallback"
        fallback_item["collapsed_guidance_replacement_fallback_only"] = True
        fallback_item["collapsed_guidance_replacement_matches_publication"] = False
        fallback_item["legacy_non_authoritative"] = True
        fallback_item["compatibility_only"] = True
        if isinstance(debug_sink, dict):
            debug_sink["collapsed_guidance_replacement_authority"] = "legacy_fallback"
            debug_sink["collapsed_guidance_replacement_fallback_only"] = True
            debug_sink["collapsed_guidance_replacement_adapter_error"] = str(exc)
        return fallback_item


def _final_visible_resolution_from_final_publication_authority(
    *,
    item: dict | None,
    overview: dict | None,
    presentation: dict | None = None,
    debug_sink: dict | None = None,
    publication_reason: str | None = None,
) -> dict:
    """Build render-stage final-visible resolution shape from publication authority."""

    legacy_item = dict(item or {})
    if not legacy_item:
        return {}
    reason = str(
        publication_reason
        or legacy_item.get("final_visible_resolver_reason")
        or legacy_item.get("publication_reason")
        or "final_visible_design_guide_resolver"
    ).strip() or "final_visible_design_guide_resolver"
    debug = debug_sink if isinstance(debug_sink, dict) else {}
    try:
        controller_response = _run_design_guide_controller_publication_authority(
            _DesignGuideControllerRequest(
                item=dict(legacy_item),
                debug=dict(debug or {}),
                design_brain_result=dict(debug.get("design_brain_result") or {}),
                verifier_payload=dict(debug.get("final_publication_verifier_payload") or {}),
                final_visible_resolution={},
                guidance_debug=dict(debug or {}),
                publication_reason=reason,
                source="inputs_page_final_visible_resolution",
            )
        )
        publication_payload = dict(controller_response.publication or {})
        final_item = dict(controller_response.collapsed_guidance_item or {})
        final_item["final_visible_resolution_authority"] = "DesignGuideController"
        final_item["final_visible_resolution_authority_hash"] = controller_response.publication_hash
        final_item["final_visible_resolution_compatibility_only"] = True
        final_item["final_publication_inner_authority"] = "FinalDesignGuidePublication"
        display = dict(publication_payload.get("display") or {})
        verifier_payload = dict(publication_payload.get("verifier_payload") or {})
        cta_payload = dict(publication_payload.get("cta") or {})
        resolution_presentation = dict(presentation or {})
        if not resolution_presentation:
            resolution_presentation = dict(display.get("final_card_model_fields") or {})
        if not resolution_presentation:
            resolution_presentation = {
                "headline": display.get("title") or final_item.get("title_main") or final_item.get("title"),
                "subtext": display.get("summary") or final_item.get("summary_line") or "",
                "guidance_intent": final_item.get("guidance_intent"),
                "css_bucket": display.get("bucket") or final_item.get("bucket"),
                "theme": display.get("colour_state") or final_item.get("bucket"),
                "show_apply_button": bool(cta_payload.get("enabled") or cta_payload.get("actionable")),
                "use_success_style": publication_payload.get("outcome_state") == "PASS",
            }
        resolution = {
            "item": dict(final_item),
            "render_reason": reason,
            "overview": dict(overview or {}),
            "design_brain_result": dict(debug.get("design_brain_result") or {}),
            "presentation": dict(resolution_presentation),
            "state_fingerprint": publication_payload.get("source_hash"),
            "debug": dict(verifier_payload.get("payload") or {}),
            "final_publication_authority_hash": controller_response.publication_hash,
            "publication_hash": controller_response.publication_hash,
            "final_visible_resolution_authority": "DesignGuideController",
            "final_publication_authority": "DesignGuideController",
            "final_publication_inner_authority": "FinalDesignGuidePublication",
            "final_visible_resolution_derived_from": "DesignGuideController.publication_authority",
            "final_visible_resolution_compatibility_only": True,
            "final_visible_resolution_product_driving": False,
            "controller_publication_authority": True,
            "controller_publication_authority_hash": controller_response.controller_hash,
            "controller_publication_authority_request_hash": controller_response.request_hash,
            "controller_publication_authority_request_source": controller_response.request_source,
            "controller_publication_authority_memo_cache_hit": controller_response.memo_cache_hit,
            "controller_publication_authority_memo_cache_key": controller_response.memo_cache_key,
            "controller_publication_authority_memo_cache_reason": controller_response.memo_cache_reason,
            "controller_publication_authority_memo_key_section_hashes": dict(
                controller_response.memo_key_section_hashes or {}
            ),
        }
        if isinstance(debug_sink, dict):
            _stamp_design_guide_controller_trace_only_parity(
                item=dict(legacy_item),
                debug_sink=debug_sink,
                final_visible_resolution=resolution,
                publication_reason=reason,
                expected_publication_hash=controller_response.publication_hash,
                prebuilt_controller_response=controller_response,
            )
            debug_sink["final_visible_resolution_authority"] = "DesignGuideController"
            debug_sink["final_publication_inner_authority"] = "FinalDesignGuidePublication"
            debug_sink["final_visible_resolution_authority_hash"] = controller_response.publication_hash
            debug_sink["final_visible_resolution_adapter_hash"] = _stable_final_publication_hash(
                resolution
            )
            debug_sink["final_visible_resolution_compatibility_only"] = True
            debug_sink["final_visible_resolution_product_driving"] = False
            debug_sink["design_guide_controller_publication_authority_live_wired"] = True
            debug_sink["design_guide_controller_publication_authority_hash"] = (
                controller_response.controller_hash
            )
            debug_sink["design_guide_controller_publication_authority_request_hash"] = (
                controller_response.request_hash
            )
            debug_sink["design_guide_controller_publication_authority_request_source"] = (
                controller_response.request_source
            )
            debug_sink["design_guide_controller_publication_authority_memo_cache_hit"] = (
                controller_response.memo_cache_hit
            )
            debug_sink["design_guide_controller_publication_authority_memo_cache_key"] = (
                controller_response.memo_cache_key
            )
            debug_sink["design_guide_controller_publication_authority_memo_cache_reason"] = (
                controller_response.memo_cache_reason
            )
            debug_sink["design_guide_controller_publication_authority_memo_key_section_hashes"] = dict(
                controller_response.memo_key_section_hashes or {}
            )
            debug_sink["design_guide_controller_publication_authority_product_driving"] = True
            debug_sink["design_guide_controller_publication_authority_render_driving"] = False
            debug_sink["design_guide_controller_publication_authority_apply_driving"] = False
            debug_sink["design_guide_controller_publication_authority_session_driving"] = False
        return resolution
    except Exception as exc:
        fallback_resolution = {
            "item": dict(legacy_item),
            "render_reason": reason,
            "overview": dict(overview or {}),
            "design_brain_result": dict(debug.get("design_brain_result") or {}),
            "presentation": dict(presentation or {}),
            "state_fingerprint": None,
            "debug": {},
            "final_visible_resolution_authority": "legacy_fallback",
            "final_visible_resolution_compatibility_only": True,
            "final_visible_resolution_product_driving": False,
            "legacy_non_authoritative": True,
        }
        if isinstance(debug_sink, dict):
            debug_sink["final_visible_resolution_authority"] = "legacy_fallback"
            debug_sink["final_visible_resolution_adapter_error"] = str(exc)
            debug_sink["final_visible_resolution_compatibility_only"] = True
        return fallback_resolution


def _stamp_design_guide_controller_trace_only_parity(
    *,
    item: dict | None,
    debug_sink: dict | None,
    final_visible_resolution: dict | None,
    publication_reason: str | None = None,
    expected_publication_hash: object = None,
    use_controller_publication_hash_as_live_hash: bool = False,
    prebuilt_controller_response: object = None,
) -> dict:
    """Trace-only controller parity beside the live final publication path."""

    if not isinstance(debug_sink, dict) or not isinstance(item, dict) or not item:
        return {}
    live_hash = str(
        expected_publication_hash
        or dict(final_visible_resolution or {}).get("publication_hash")
        or debug_sink.get("final_publication_publication_hash")
        or debug_sink.get("final_publication_authority_hash")
        or ""
    ).strip()
    try:
        trace_publication_debug = {
            key: value
            for key, value in dict(debug_sink or {}).items()
            if not str(key).startswith("design_guide_controller_")
            and not str(key).startswith("final_visible_resolution_")
            and str(key)
            not in {
                "final_publication_inner_authority",
                "final_publication_authority",
                "final_publication_authority_hash",
                "final_publication_publication_hash",
            }
        }
        if prebuilt_controller_response is not None:
            response = prebuilt_controller_response
        else:
            response = _run_design_guide_controller_trace_only(
                _DesignGuideControllerRequest(
                    item=dict(item or {}),
                    debug=dict(trace_publication_debug),
                    verifier_payload=dict(
                        trace_publication_debug.get("final_publication_verifier_payload") or {}
                    ),
                    final_visible_resolution=dict(final_visible_resolution or {}),
                    guidance_debug=dict(trace_publication_debug),
                    publication_reason=publication_reason,
                    source="inputs_page_live_trace_wiring",
                ),
            )
        if use_controller_publication_hash_as_live_hash:
            live_hash = str(response.publication_hash or "").strip()
        _trace_verifier_payload = dict(
            trace_publication_debug.get("final_publication_verifier_payload") or {}
        )
        _trace_controller_parity = dict(response.parity_payload or {})
        payload = {
            "authority": "DesignGuideController.trace_only",
            "compared_against": "FinalDesignGuidePublication",
            "live_publication_hash": live_hash,
            "controller_publication_hash": response.publication_hash,
            "controller_hash": response.controller_hash,
            "controller_request_hash": response.request_hash,
            "controller_request_source": response.request_source,
            "controller_memo_cache_key": response.memo_cache_key,
            "controller_memo_key_section_hashes": dict(
                response.memo_key_section_hashes or {}
            ),
            "controller_memo_cache_hit": response.memo_cache_hit,
            "controller_memo_cache_reason": response.memo_cache_reason,
            "controller_collapsed_publication_hash": response.collapsed_guidance_item.get(
                "publication_hash"
            ),
            "controller_resolution_publication_hash": response.final_visible_resolution.get(
                "publication_hash"
            ),
            "trace_input_title": str(
                item.get("title_main") or item.get("title") or ""
            ).strip(),
            "trace_input_status": str(item.get("status") or "").strip(),
            "trace_input_family": str(
                item.get("selected_family_id")
                or item.get("published_family_id")
                or item.get("family")
                or item.get("check_key")
                or ""
            ).strip(),
            "controller_display_title": str(
                dict(response.publication.get("display") or {}).get("title") or ""
            ).strip(),
            "controller_display_status": str(
                dict(response.publication.get("display") or {}).get("status") or ""
            ).strip(),
            "live_verifier_publication_hash": str(
                _trace_verifier_payload.get("publication_hash") or ""
            ).strip(),
            "live_verifier_cta_hash": str(
                _trace_verifier_payload.get("final_publication_cta_hash") or ""
            ).strip(),
            "live_verifier_display_hash": str(
                _trace_verifier_payload.get("final_publication_display_hash") or ""
            ).strip(),
            "live_verifier_evidence_hash": str(
                _trace_verifier_payload.get("final_publication_evidence_hash") or ""
            ).strip(),
            "controller_cta_hash": _trace_controller_parity.get("cta_hash"),
            "controller_display_hash": _trace_controller_parity.get("display_hash"),
            "controller_evidence_hash": _trace_controller_parity.get("evidence_hash"),
            "trace_debug_keys_hash": _stable_final_publication_hash(
                sorted(str(key) for key in trace_publication_debug.keys())
            ),
            "trace_debug_keys_count": len(trace_publication_debug),
            "trace_input_item_hash": _stable_final_publication_hash(item),
            "trace_final_visible_resolution_item_hash": _stable_final_publication_hash(
                dict(final_visible_resolution or {}).get("item") or {}
            ),
            "selected_family": response.parity_payload.get("selected_family"),
            "outcome_state": response.parity_payload.get("outcome_state"),
            "published_item_id": response.parity_payload.get("published_item_id"),
            "post_click_design_guide_state": response.parity_payload.get(
                "post_click_design_guide_state"
            ),
            "parity_pass": bool(live_hash and live_hash == response.publication_hash),
            "trace_only": True,
            "prebuilt_controller_response_used": prebuilt_controller_response is not None,
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
        }
        payload["trace_hash"] = _stable_final_publication_hash(payload)
        debug_sink["design_guide_controller_trace_only_parity"] = dict(payload)
        debug_sink["design_guide_controller_trace_only_parity_hash"] = payload["trace_hash"]
        debug_sink["design_guide_controller_trace_only_parity_pass"] = payload["parity_pass"]
        debug_sink["design_guide_controller_trace_only_request_hash"] = response.request_hash
        debug_sink["design_guide_controller_trace_only_request_source"] = response.request_source
        debug_sink["design_guide_controller_trace_only_memo_cache_hit"] = response.memo_cache_hit
        debug_sink["design_guide_controller_trace_only_memo_cache_key"] = response.memo_cache_key
        debug_sink["design_guide_controller_trace_only_memo_cache_reason"] = response.memo_cache_reason
        debug_sink["design_guide_controller_trace_only_memo_key_section_hashes"] = dict(
            response.memo_key_section_hashes or {}
        )
        debug_sink["design_guide_controller_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_trace_only_product_driving"] = False
        debug_sink["design_guide_controller_trace_only_render_driving"] = False
        debug_sink["design_guide_controller_trace_only_apply_driving"] = False
        debug_sink["design_guide_controller_trace_only_session_driving"] = False
        if use_controller_publication_hash_as_live_hash:
            debug_sink["final_visible_resolution_authority_hash"] = response.publication_hash
            debug_sink["final_visible_resolution_publication_hash"] = response.publication_hash
            debug_sink["final_publication_publication_hash"] = response.publication_hash
        return payload
    except Exception as exc:
        payload = {
            "authority": "DesignGuideController.trace_only",
            "compared_against": "FinalDesignGuidePublication",
            "live_publication_hash": live_hash,
            "parity_pass": False,
            "trace_only": True,
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
            "error": str(exc),
        }
        payload["trace_hash"] = _stable_final_publication_hash(payload)
        debug_sink["design_guide_controller_trace_only_parity"] = dict(payload)
        debug_sink["design_guide_controller_trace_only_parity_hash"] = payload["trace_hash"]
        debug_sink["design_guide_controller_trace_only_parity_pass"] = False
        debug_sink["design_guide_controller_trace_only_error"] = str(exc)
        debug_sink["design_guide_controller_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_trace_only_product_driving"] = False
        return payload


