def _run_post_click_low_bending_residual_shear_cleanup_primary_executor(
    *,
    state: dict,
    executor,
) -> tuple[dict | None, dict]:
    """Run the injected residual-shear primary executor without changing behavior."""

    residual_shear_debug: dict = {}
    if not callable(executor):
        return None, residual_shear_debug
    try:
        result = executor(
            state,
            out_debug=residual_shear_debug,
        )
    except Exception:
        result = None
    return (result if isinstance(result, dict) else None), residual_shear_debug


