def _run_post_click_low_bending_residual_shear_cleanup_result_packaging(
    *,
    state: dict,
    overview: dict,
    mode_config: dict,
    residual_shear_tighten: dict,
    packager,
    local_cleanup_evaluator,
) -> tuple[dict | None, dict | None, dict]:
    """Run injected residual-shear result packaging/evaluation without changing behavior."""

    if not callable(packager) or not callable(local_cleanup_evaluator):
        return None, None, {}
    residual_shear_item = packager(
        state,
        overview if isinstance(overview, dict) else {},
        {
            "actions_used": _resolve_design_actions_from_state(state),
            "shear_tightening": dict(residual_shear_tighten or {}),
        },
    )
    if not isinstance(residual_shear_item, dict):
        return None, None, {}
    residual_promoted, residual_detail = local_cleanup_evaluator(
        residual_shear_item,
        state=state,
        overview=overview if isinstance(overview, dict) else {},
        mode_config=mode_config,
        source="post_click_low_bending_residual_shear_cleanup",
    )
    return (
        residual_shear_item,
        residual_promoted if isinstance(residual_promoted, dict) else None,
        residual_detail if isinstance(residual_detail, dict) else {},
    )


def _run_post_click_low_bending_residual_shear_cleanup_materiality_safety_pre_screen(
    *,
    state: dict,
    fallback_variant: dict,
    delta_screen_builder,
    pure_updates_checker,
) -> dict:
    """Run injected residual-shear pre-evaluation screen without changing behavior."""

    if not callable(delta_screen_builder) or not callable(pure_updates_checker):
        return dict(
            _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_pre_screen_result(
                dependencies_available=False
            ).get("result")
            or {}
        )
    candidate_delta_screen = delta_screen_builder(
        base_state=state,
        variant_state=fallback_variant,
    )
    fallback_updates = dict(candidate_delta_screen.get("updates") or {})
    if not fallback_updates:
        return dict(
            _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_pre_screen_result(
                updates={}
            ).get("result")
            or {}
        )
    if _updates_match_state(state, fallback_updates):
        return dict(
            _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_pre_screen_result(
                updates=dict(fallback_updates),
                updates_match_state=True,
                materially_reduces_reinforcement=bool(
                    candidate_delta_screen.get("materially_reduces_reinforcement")
                ),
            ).get("result")
            or {}
        )
    if not bool(candidate_delta_screen.get("materially_reduces_reinforcement")):
        return dict(
            _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_pre_screen_result(
                updates=dict(fallback_updates),
                materially_reduces_reinforcement=False,
            ).get("result")
            or {}
        )
    pure_shear, bad_shear_keys = pure_updates_checker(dict(fallback_updates))
    return dict(
        _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_pre_screen_result(
            updates=dict(fallback_updates),
            materially_reduces_reinforcement=True,
            pure_shear_updates=bool(pure_shear),
            bad_update_keys=tuple(bad_shear_keys or ()),
        ).get("result")
        or {}
    )


def _run_post_click_low_bending_residual_shear_cleanup_materiality_safety_post_screen(
    *,
    fallback_candidate: dict,
    current_shear_util: float,
    acceptance_screen_builder,
) -> dict:
    """Run injected residual-shear post-evaluation screen without changing behavior."""

    if not callable(acceptance_screen_builder) or not isinstance(fallback_candidate, dict):
        return dict(
            _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_post_screen_result(
                candidate_available=False
            ).get("result")
            or {}
        )
    fallback_overview = dict(fallback_candidate.get("overview") or {})
    fallback_statuses = dict(fallback_overview.get("statuses") or {})
    fallback_utils = dict(fallback_overview.get("utils") or {})
    fallback_shear_util = _parse_util_value(fallback_utils.get("shear"))
    candidate_acceptance_screen = acceptance_screen_builder(
        candidate_overview=fallback_overview,
        candidate_statuses=fallback_statuses,
    )
    return dict(
        _build_design_guide_controller_post_click_low_bending_residual_shear_cleanup_post_screen_result(
            candidate_available=True,
            fallback_overview=dict(fallback_overview),
            fallback_statuses=dict(fallback_statuses),
            fallback_utils=dict(fallback_utils),
            fallback_shear_util=fallback_shear_util,
            current_shear_util=current_shear_util,
            target_band_eps=TARGET_BAND_EPS,
            acceptance_screen=dict(candidate_acceptance_screen or {}),
        ).get("result")
        or {}
    )


