def _compute_rebound_item_from_controller_publication_item(
    *,
    debug_sink: dict | None,
    path_id: str,
    primary_item: dict | None,
    rebound_contract: dict | None,
    rebound_update_payload: dict | None,
    publication_reason: str,
) -> dict:
    """Build compute rebound item through DesignGuideController authority."""

    primary = dict(primary_item or {})
    if not isinstance(debug_sink, dict):
        return dict(primary)
    try:
        response = _run_design_guide_controller_compute_rebound_publication_item_trace_only(
            {
                "path_id": str(path_id),
                "primary_item": dict(primary),
                "rebound_contract": dict(rebound_contract or {}),
                "rebound_update_payload": dict(rebound_update_payload or {}),
                "publication_reason": str(publication_reason or path_id),
                "source": f"inputs_page_compute_rebound_publication_item:{path_id}",
                "product_driving": True,
            }
        )
        item = dict(response.selected_item or primary)
        traces = dict(debug_sink.get("design_guide_controller_compute_rebound_publication_items") or {})
        traces[str(path_id)] = {
            "path_id": str(path_id),
            "request_hash": response.request_hash,
            "controller_hash": response.controller_hash,
            "selected_item_hash": response.selected_item_hash,
            "collapsed_guidance_item_hash": response.collapsed_guidance_item_hash,
            "publication_hash": response.publication_hash,
            "product_driving": True,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
        }
        debug_sink["design_guide_controller_compute_rebound_publication_items"] = dict(traces)
        debug_sink["design_guide_controller_compute_rebound_publication_item_latest_path"] = str(path_id)
        debug_sink["design_guide_controller_compute_rebound_publication_item_latest_hash"] = response.controller_hash
        debug_sink["design_guide_controller_compute_rebound_publication_item_product_driving"] = True
        debug_sink["design_guide_controller_compute_rebound_publication_item_render_driving"] = False
        debug_sink["design_guide_controller_compute_rebound_publication_item_apply_driving"] = False
        debug_sink["design_guide_controller_compute_rebound_publication_item_session_driving"] = False
        return item
    except Exception as exc:
        errors = dict(debug_sink.get("design_guide_controller_compute_rebound_publication_item_errors") or {})
        errors[str(path_id)] = str(exc)
        debug_sink["design_guide_controller_compute_rebound_publication_item_errors"] = errors
        debug_sink["design_guide_controller_compute_rebound_publication_item_product_driving"] = False
        debug_sink["design_guide_controller_compute_rebound_publication_item_fallback_used"] = True
        fallback = dict(primary)
        contract = dict(rebound_contract or {})
        updates = dict(rebound_update_payload or contract.get("updates") or {})
        if contract:
            if updates:
                contract["updates"] = dict(updates)
            fallback["button_contract"] = dict(contract)
            fallback["updates"] = dict(updates)
            fallback["selected_action_updates"] = dict(updates)
        fallback["legacy_non_authoritative"] = True
        fallback["compatibility_only"] = True
        fallback["controller_rebound_publication_item_fallback"] = True
        return fallback


def _design_guide_publication_object_payload(value) -> dict:
    if value is None:
        return {}
    if isinstance(value, dict):
        return dict(value)
    try:
        return asdict(value)
    except Exception:
        try:
            return dict(value)
        except Exception:
            return {}


def _stamp_design_guide_controller_compute_handoff_trace_only(
    *,
    debug_sink: dict | None,
    state: dict | None = None,
    overview: dict | None = None,
    collapsed_guidance_items: list | None = None,
    publication_context: dict | None = None,
    publication_dependencies: dict | None = None,
    final_compute_resolution: dict | None = None,
    blocker_evidence_surface: dict | None = None,
    pre_resolver_collapsed_item_mutation: dict | None = None,
) -> None:
    """Stamp controller compute handoff trace parity without driving product output."""

    if not isinstance(debug_sink, dict):
        return
    try:
        resolution = dict(final_compute_resolution or {})
        selected_item = dict(resolution.get("item") or {})
        contract = dict(selected_item.get("button_contract") or {})
        request = _DesignGuideControllerComputePublicationHandoffRequest(
            current_state=dict(state or {}),
            overview=dict(overview or {}),
            collapsed_guidance_items=[
                dict(item) for item in list(collapsed_guidance_items or []) if isinstance(item, dict)
            ],
            publication_context=_design_guide_publication_object_payload(publication_context),
            publication_dependencies=_design_guide_publication_object_payload(publication_dependencies),
            final_compute_resolution=dict(resolution),
            blocker_evidence_surface=dict(blocker_evidence_surface or {}),
            late_evidence_acceptance={},
            rebound_contract=dict(contract),
            rebound_update_payload=dict(contract.get("updates") or selected_item.get("updates") or {}),
            post_core_evidence_mismatch={},
            pre_resolver_collapsed_item_mutation=dict(pre_resolver_collapsed_item_mutation or {}),
            debug=dict(debug_sink or {}),
            verifier_payload=dict(debug_sink.get("final_publication_verifier_payload") or {}),
            publication_reason=str(resolution.get("render_reason") or "compute_publication_resolution"),
            source="inputs_page_compute_handoff_trace_only",
        )
        response = _run_design_guide_controller_compute_publication_handoff_trace_only(request)
        payload = response.to_dict()
        live_resolution_hash = _stable_final_publication_hash(resolution)
        live_selected_item_hash = _stable_final_publication_hash(selected_item)
        trace_payload = {
            "authority": "DesignGuideController.compute_publication_handoff.trace_only",
            "compared_against": "inputs_page.compute_stage.final_compute_resolution",
            "request_hash": response.request_hash,
            "controller_hash": response.controller_hash,
            "publication_hash": response.publication_hash,
            "selected_item_hash": response.selected_item_hash,
            "live_selected_item_hash": live_selected_item_hash,
            "selected_item_hash_match": response.selected_item_hash == live_selected_item_hash,
            "final_visible_resolution_hash": response.final_visible_resolution_hash,
            "live_final_compute_resolution_hash": live_resolution_hash,
            "compute_handoff_rebound_decision_hash": response.compute_handoff_rebound_decision_hash,
            "covered_blocking_fields": list(
                (response.compute_handoff_rebound_decision_proof or {}).get("covered_blocking_fields") or []
            ),
            "missing_blocking_fields": list(
                (response.compute_handoff_rebound_decision_proof or {}).get("missing_blocking_fields") or []
            ),
            "trace_only": True,
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
        }
        trace_payload["trace_hash"] = _stable_final_publication_hash(trace_payload)
        debug_sink["design_guide_controller_compute_handoff_trace_only"] = dict(trace_payload)
        debug_sink["design_guide_controller_compute_handoff_trace_only_hash"] = trace_payload["trace_hash"]
        debug_sink["design_guide_controller_compute_handoff_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_compute_handoff_trace_only_payload"] = dict(payload)
        debug_sink["design_guide_controller_compute_handoff_trace_only_product_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_render_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_apply_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_session_driving"] = False
    except Exception as exc:
        debug_sink["design_guide_controller_compute_handoff_trace_only_error"] = str(exc)
        debug_sink["design_guide_controller_compute_handoff_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_compute_handoff_trace_only_product_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_render_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_apply_driving"] = False
        debug_sink["design_guide_controller_compute_handoff_trace_only_session_driving"] = False


def _stamp_design_guide_controller_compute_selection_trace_only(
    *,
    debug_sink: dict | None,
    state: dict | None = None,
    overview: dict | None = None,
    collapsed_guidance_items: list | None = None,
    publication_context: dict | None = None,
    publication_dependencies: dict | None = None,
    final_compute_resolution: dict | None = None,
) -> None:
    """Stamp controller compute selector parity without driving product output."""

    if not isinstance(debug_sink, dict):
        return
    try:
        resolution = dict(final_compute_resolution or {})
        legacy_item = dict(resolution.get("item") or {})
        legacy_render_reason = str(resolution.get("render_reason") or "")
        try:
            session_controls = {
                key: st.session_state.get(key)
                for key in (
                    "actions_mode",
                    "actions_source",
                    "inputs_use_calculated_actions",
                    "loads_edit_mode",
                    "results_version",
                )
                if key in st.session_state
            }
        except Exception:
            session_controls = {}
        try:
            signature_state = (
                dict(publication_context.get("guidance_state_snapshot") or {})
                if isinstance(publication_context, dict)
                and isinstance(publication_context.get("guidance_state_snapshot"), dict)
                else dict(state or {})
            )
            design_actions_signature = tuple(
                _resolve_design_actions_from_state(signature_state).get("signature", ())
            )
        except Exception:
            design_actions_signature = ()
        try:
            optimisation_goal = str(_design_optimisation_goal(dict(state or {})))
        except Exception:
            optimisation_goal = ""
        request = _DesignGuideControllerComputeSelectionRequest(
            current_state=dict(state or {}),
            overview=dict(overview or {}),
            collapsed_guidance_items=[
                dict(item) for item in list(collapsed_guidance_items or []) if isinstance(item, dict)
            ],
            publication_context=_design_guide_publication_object_payload(publication_context),
            publication_dependencies=_design_guide_publication_object_payload(publication_dependencies),
            session_controls=dict(session_controls or {}),
            design_actions_signature=tuple(design_actions_signature or ()),
            optimisation_goal=str(optimisation_goal or ""),
            publication_reason=str(
                legacy_render_reason or "compute_publication_selection_trace"
            ),
            source="inputs_page_compute_selection_trace_only",
        )
        response = _run_design_guide_controller_compute_selection_trace_only(request)
        legacy_selected_item_hash = _stable_final_publication_hash(legacy_item)
        legacy_state_fingerprint = resolution.get("state_fingerprint")
        route_is_no_active_primary = legacy_render_reason == "final_visible_no_active_strength_fail"
        trace_payload = {
            "authority": "DesignGuideController.compute_selection.trace_only",
            "compared_against": "inputs_page.compute_stage.final_compute_resolution",
            "request_hash": response.request_hash,
            "selection_hash": response.selection_hash,
            "selection_policy": response.selection_policy,
            "selected_item_index": response.selected_item_index,
            "selected_item_hash": response.selected_item_hash,
            "legacy_selected_item_hash": legacy_selected_item_hash,
            "selected_item_hash_match": response.selected_item_hash == legacy_selected_item_hash,
            "render_reason": response.render_reason,
            "legacy_render_reason": legacy_render_reason,
            "render_reason_match": response.render_reason == legacy_render_reason,
            "state_fingerprint": response.state_fingerprint,
            "legacy_state_fingerprint": legacy_state_fingerprint,
            "state_fingerprint_match": response.state_fingerprint == legacy_state_fingerprint,
            "route_is_no_active_primary": route_is_no_active_primary,
            "route_replacement_ready": (
                route_is_no_active_primary
                and response.selected_item_hash == legacy_selected_item_hash
                and response.render_reason == legacy_render_reason
                and response.state_fingerprint == legacy_state_fingerprint
            ),
            "trace_only": True,
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
        }
        trace_payload["trace_hash"] = _stable_final_publication_hash(trace_payload)
        debug_sink["design_guide_controller_compute_selection_trace_only"] = dict(trace_payload)
        debug_sink["design_guide_controller_compute_selection_trace_only_hash"] = trace_payload["trace_hash"]
        debug_sink["design_guide_controller_compute_selection_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_compute_selection_trace_only_payload"] = response.to_dict()
        debug_sink["design_guide_controller_compute_selection_trace_only_product_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_render_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_apply_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_session_driving"] = False
    except Exception as exc:
        debug_sink["design_guide_controller_compute_selection_trace_only_error"] = str(exc)
        debug_sink["design_guide_controller_compute_selection_trace_only_live_wired"] = True
        debug_sink["design_guide_controller_compute_selection_trace_only_product_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_render_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_apply_driving"] = False
        debug_sink["design_guide_controller_compute_selection_trace_only_session_driving"] = False


