def _stamp_design_guide_controller_no_active_blocked_primary_cleanup_probe_result_trace_only(
    *,
    debug_sink: dict,
    authority: str,
    live_result: dict,
    controller_result: dict,
) -> None:
    """Stamp proof-only parity between live assembler result and controller result."""

    def _projection(result: dict) -> dict:
        return {
            "item": dict(result.get("item") or {}),
            "overview": dict(result.get("overview") or {}),
            "presentation": dict(result.get("presentation") or {}),
            "render_reason": result.get("render_reason"),
            "state_fingerprint": result.get("state_fingerprint"),
        }

    try:
        live_projection = _projection(dict(live_result or {}))
        controller_projection = _projection(dict(controller_result or {}))
        live_hash = _stable_final_publication_hash(live_projection)
        controller_hash = _stable_final_publication_hash(controller_projection)
        debug_sink[
            "design_guide_controller_no_active_blocked_primary_cleanup_probe_result_trace_only"
        ] = {
            "authority": str(authority or "DesignGuideController.no_active_blocked_primary_cleanup_probe_result"),
            "live_wired": True,
            "live_result_hash": live_hash,
            "controller_result_hash": controller_hash,
            "result_hash_match": live_hash == controller_hash,
            "item_hash_match": _stable_final_publication_hash(live_projection.get("item") or {})
            == _stable_final_publication_hash(controller_projection.get("item") or {}),
            "presentation_hash_match": _stable_final_publication_hash(
                live_projection.get("presentation") or {}
            )
            == _stable_final_publication_hash(controller_projection.get("presentation") or {}),
            "render_reason_match": live_projection.get("render_reason")
            == controller_projection.get("render_reason"),
            "state_fingerprint_match": live_projection.get("state_fingerprint")
            == controller_projection.get("state_fingerprint"),
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
        }
    except Exception as exc:
        debug_sink[
            "design_guide_controller_no_active_blocked_primary_cleanup_probe_result_trace_only"
        ] = {
            "authority": str(authority or "DesignGuideController.no_active_blocked_primary_cleanup_probe_result"),
            "live_wired": False,
            "product_driving": False,
            "render_driving": False,
            "apply_driving": False,
            "session_driving": False,
            "error": f"{type(exc).__name__}: {exc}",
        }


