def _local_cleanup_acceptance_fingerprint(state: dict | None) -> tuple:
    snap = _guidance_state_snapshot(dict(state or {}))
    keys = (
        "b",
        "D",
        "bot1_count",
        "db_bot_1",
        "bot2_count",
        "db_bot_2",
        "bot_row_count",
        "bot_row_1_bars",
        "bot_row_1_dia",
        "bot_row_2_bars",
        "bot_row_2_dia",
        "lig_d",
        "lig_legs",
        "s_lig",
    )
    return tuple((key, str(snap.get(key))) for key in keys)


def _local_cleanup_post_apply_acceptance_matches(state: dict | None) -> bool:
    try:
        current_fp = _local_cleanup_acceptance_fingerprint(state)
        expected_fp = st.session_state.get("_design_guide_post_cleanup_acceptance_fp")
        if expected_fp == current_fp or current_fp in _DESIGN_GUIDE_POST_CLEANUP_ACCEPTED_FPS:
            return True
        if expected_fp is not None and expected_fp != current_fp:
            _clear_stale_design_guide_cleanup_state("post_cleanup_acceptance_fingerprint_changed")
            return False
        last_apply = dict(st.session_state.get(DESIGN_GUIDE_LAST_APPLY_ROUTE_KEY) or {})
        return bool(
            st.session_state.get("_design_guide_post_cleanup_acceptance_enabled")
            or last_apply.get("apply_direct_resolved_candidate")
            or last_apply.get("apply_used_resolved_candidate_payload")
        )
    except Exception:
        return False


def _post_apply_active_repair_route_matches_current_state(
    route: dict | None,
    state: dict | None,
) -> bool:
    route_d = dict(route or {})
    state_d = dict(state or {})
    update_surfaces = [
        dict(route_d.get("actual_changed_updates") or {}),
        dict(route_d.get("applied_updates") or {}),
        dict(route_d.get("queued_apply_updates") or {}),
    ]
    update_surfaces = [surface for surface in update_surfaces if surface]
    if not update_surfaces:
        return False
    state_surfaces = [state_d]
    try:
        state_surfaces.append(_guidance_state_snapshot(state_d))
    except Exception:
        pass
    for updates in update_surfaces:
        for state_surface in state_surfaces:
            try:
                if _updates_match_state(state_surface, updates):
                    return True
            except Exception:
                continue
    return False


def _post_apply_active_repair_required_checks_terminal_ready(
    route: dict | None,
    state: dict | None,
    *,
    allowed_families: set[str] | None = None,
    cleanup_terminal_families: set[str] | None = None,
) -> bool:
    route_d = dict(route or {})
    overview = dict(route_d.get("post_apply_overview") or {})
    family = str(route_d.get("resolved_candidate_family_tag") or "").strip().lower()
    label = str(
        route_d.get("resolved_candidate_label")
        or route_d.get("post_apply_resolved_candidate_label")
        or route_d.get("one_click_candidate_label_at_step_start")
        or ""
    ).strip().lower()
    allowed = {str(f or "").strip().lower() for f in (allowed_families or {"bending", "shear", "combined", "geometry"})}
    cleanup_allowed = {
        str(f or "").strip().lower()
        for f in (
            cleanup_terminal_families
            or {
                "bending",
                "shear",
                "combined",
                "bending_overdesign_governs",
                "shear_overdesign_governs",
                "combined_overdesign",
                "combined_overdesign_governs",
            }
        )
    }
    if family not in allowed:
        return False
    if not bool(route_d.get("post_apply_resolved_candidate_attempted")):
        return False
    cleanup_like_label = any(
        token in label
        for token in ("cleanup", "overdesign", "optimisation", "optimization", "tighten")
    )
    if cleanup_like_label:
        terminal_status = str(route_d.get("terminal_candidate_status") or "").strip().upper()
        terminal_cleanup_proven = bool(
            terminal_status
            in {"TERMINAL_TARGET_BAND", "TERMINAL_EXACT_STOP", "TERMINAL_BLOCKED_WITH_PROOF"}
            and not bool(route_d.get("further_cleanup_available"))
            and bool(route_d.get("no_second_cta_required"))
        )
        if family not in cleanup_allowed or not terminal_cleanup_proven:
            return False
    if not overview:
        return False
    if not bool(overview.get("all_key_pass")) or bool(overview.get("any_fail")):
        return False
    if not _overview_required_checks_acceptable(overview):
        return False
    return _post_apply_active_repair_route_matches_current_state(route_d, state)


def _post_apply_combined_chained_terminal_recent_refresh_ready(
    route: dict | None,
    state: dict | None = None,
) -> bool:
    route_d = dict(route or {})
    if str(route_d.get("resolved_candidate_family_tag") or "").strip().lower() not in {
        "combined",
        "combined_bending_shear_fail",
        "combined_bending_shear_fail_governs",
    }:
        return False
    if not bool(route_d.get("combined_fail_post_repair_shear_cleanup_chained")):
        return False
    if not bool(route_d.get("post_apply_resolved_candidate_attempted")):
        return False
    overview = dict(route_d.get("post_apply_overview") or {})
    if not overview:
        return False
    if not bool(overview.get("all_key_pass")) or bool(overview.get("any_fail")):
        return False
    if not _overview_required_checks_acceptable(overview):
        return False
    pending_terminal_render = dict(
        st.session_state.get("_design_guide_combined_terminal_apply_pending_render") or {}
    )
    if bool(pending_terminal_render.get("pending")):
        pending_expected_worst = _parse_util_value(
            pending_terminal_render.get("expected_util")
            or dict(pending_terminal_render.get("post_apply_overview") or {}).get("worst_util")
        )
        route_expected_worst = _parse_util_value(
            route_d.get("combined_fail_post_repair_shear_cleanup_expected_util")
            or route_d.get("expected_post_util")
            or overview.get("worst_util")
        )
        if (
            pending_expected_worst is None
            or route_expected_worst is None
            or abs(float(pending_expected_worst) - float(route_expected_worst)) <= 1e-6
        ):
            return True
    if bool(st.session_state.get("_inputs_pending_refresh_present_before_pop")):
        return True
    state_d = dict(state or {})
    if state_d:
        try:
            current_context = _build_design_actions_context(state_d)
            current_overview = _collect_design_overview(state_d, context=current_context)
            current_worst = _parse_util_value(current_overview.get("worst_util"))
            expected_worst = _parse_util_value(
                route_d.get("combined_fail_post_repair_shear_cleanup_expected_util")
                or route_d.get("expected_post_util")
                or overview.get("worst_util")
            )
            if (
                bool(current_overview.get("all_key_pass"))
                and not bool(current_overview.get("any_fail"))
                and _overview_required_checks_acceptable(current_overview)
                and current_worst is not None
                and expected_worst is not None
                and abs(float(current_worst) - float(expected_worst)) <= 1e-6
            ):
                return True
        except Exception:
            pass
    state_surfaces = [dict(state or {})]
    try:
        state_surfaces.append(_guidance_state_snapshot(dict(state or {})))
    except Exception:
        pass
    physical_keys = {
        "D",
        "b",
        "bot_row_1_bars",
        "bot_row_1_dia",
        "bot_row_2_bars",
        "bot_row_2_dia",
        "db_top_1",
        "db_top_2",
        "lig_d",
        "lig_legs",
        "s_lig",
        "top1_count",
        "top2_count",
    }
    update_surfaces = [
        dict(route_d.get("actual_changed_updates") or {}),
        dict(route_d.get("applied_updates") or {}),
        dict(route_d.get("queued_apply_updates") or {}),
    ]
    for updates in update_surfaces:
        comparable = {
            key: value
            for key, value in dict(updates or {}).items()
            if key in physical_keys
        }
        for state_surface in state_surfaces:
            comparable_present = {
                key: value
                for key, value in comparable.items()
                if key in dict(state_surface or {})
            }
            if len(comparable_present) < 3:
                continue
            try:
                if _updates_match_state(dict(state_surface or {}), comparable_present):
                    return True
            except Exception:
                continue
    return False


def _post_apply_combined_terminal_solver_result_ready() -> bool:
    result = st.session_state.get("_solver_result")
    if not isinstance(result, dict):
        return False
    if str(result.get("status") or "").strip().lower() != "pass":
        return False
    if str(result.get("stop_reason") or "").strip() != "applied_recommendation":
        return False
    dbg = dict(result.get("one_click_solver_debug") or {})
    if not bool(dbg.get("combined_fail_post_repair_shear_cleanup_chained")):
        return False
    overview = dict(result.get("post_apply_overview") or {})
    if not overview:
        return False
    if not bool(overview.get("all_key_pass")) or bool(overview.get("any_fail")):
        return False
    return _overview_required_checks_acceptable(overview)


def _canonical_post_apply_terminal_family_id(raw_family: object, *, default: str = "BENDING_FAIL_GOVERNS") -> str:
    family = str(raw_family or "").strip()
    if family.lower() in {"combined", "combined_bending_shear_fail", "combined_bending_shear_fail_governs"}:
        return "COMBINED_BENDING_SHEAR_FAIL"
    if family.lower() == "bending":
        return "BENDING_FAIL_GOVERNS"
    if family.lower() == "shear":
        return "SHEAR_FAIL_GOVERNS"
    return family or str(default)


