def _explicit_locked_no_repair_signal(source: dict | None, classifier: dict | None = None) -> bool:
    state_d = dict(source or {})
    classifier_d = dict(classifier or {})
    explicit_no_repair = any(
        bool(state_d.get(key))
        for key in (
            "locked_no_repair",
            "locked_repair_blocked",
            "all_repair_paths_locked",
            "repair_blocked_by_lock",
            "no_valid_repair_available",
        )
    )
    explicit_lock = any(
        bool(state_d.get(key))
        for key in (
            "reinforcement_lock",
            "reo_locked",
            "shear_lock",
            "optimisation_lock_geometry",
            "geometry_lock",
            "optimisation_lock_width",
            "optimisation_lock_depth",
        )
    )
    classifier_locked = str(classifier_d.get("governing_state") or "").strip() == "LOCKED_NO_REPAIR"
    return bool(classifier_locked or (explicit_no_repair and explicit_lock))


