def _sync_design_action_widget_to_shared(
    widget_key: str,
    shared_key: str,
    proxy_key: str | None = None,
    *,
    trigger_rerun: bool = False,
) -> None:
    value = st.session_state.get(widget_key)
    if value is None:
        return
    numeric_value = float(value or 0.0)
    if shared_key.endswith("_Mstar_pos_manual") or shared_key.endswith("_Mstar_neg_manual"):
        numeric_value = max(0.0, numeric_value)
    try:
        st.session_state["_last_user_widget_key"] = str(widget_key)
    except Exception:
        pass
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        try:
            _append_design_guide_trace(
                "design_action_widget_sync_entry",
                {
                    "widget_key": str(widget_key),
                    "shared_key": str(shared_key),
                    "proxy_key": str(proxy_key) if proxy_key else None,
                    "widget_value_raw": value,
                    "numeric_value": numeric_value,
                    "shared_before": get_param(shared_key, None),
                    "proxy_before": get_param(proxy_key, None) if proxy_key else None,
                },
                run_id=f"daws_{int(time.time() * 1000)}",
                source="design_action_widget_sync",
            )
        except Exception:
            pass
    mark_user_edit(widget_key, shared_key)
    set_shared(shared_key, numeric_value, source="design_action_widget_sync")
    if proxy_key:
        set_shared(proxy_key, numeric_value, source="design_action_widget_sync")
    if shared_key.endswith("_Mstar_pos_manual") or shared_key.endswith("_Mstar_neg_manual"):
        prefix = "uls" if shared_key.startswith("uls_") else "sls"
        pos = float(get_param(f"{prefix}_Mstar_pos_manual", 0.0) or 0.0)
        neg = float(get_param(f"{prefix}_Mstar_neg_manual", 0.0) or 0.0)
        set_shared(f"{prefix}_Mstar", float(pos - neg), source="design_action_widget_sync")
        if prefix == "uls":
            set_shared("Mu_star_pos_manual", float(pos), source="design_action_widget_sync")
            set_shared("Mu_star_neg_manual", float(neg), source="design_action_widget_sync")
            set_shared("Mu_star_manual", float(pos - neg), source="design_action_widget_sync")
            set_shared("load_Mstar_proxy", float(pos - neg), source="design_action_widget_sync")
    if shared_key in {"uls_Nstar", "sls_Nstar"}:
        set_shared("N_star", numeric_value, source="design_action_widget_sync")
    _invalidate_inputs_summary_packs(
        source="design_action_widget_sync",
        updated_keys=[k for k in (shared_key, proxy_key) if k],
    )
    # Prevent old published result buckets from being reused while the router-level
    # recompute/publish path catches up to this newly edited action state.
    st.session_state["cached_results"] = None
    st.session_state["_cached_compute_results"] = None
    st.session_state["_last_compute_fp"] = None
    _queue_inputs_refresh(
        "design_action_widget_sync",
        [k for k in (shared_key, proxy_key) if k],
    )
    _invalidate_design_guide_caches(
        reason="design_action_widget_sync",
        updated_keys=[k for k in (shared_key, proxy_key) if k],
        preserve_apply_banner=False,
    )
    st.session_state.pop("pending_recommendation", None)
    st.session_state.pop("pending_recommendation_applied_id", None)
    st.session_state.pop("_solver_result", None)
    st.session_state.pop("_one_click_run_feedback", None)
    st.session_state.pop("auto_design_status", None)
    st.session_state.pop("auto_design_steps", None)
    st.session_state["inputs_dirty"] = True
    st.session_state["_inputs_dirty"] = True
    st.session_state["run_design_clicked"] = True
    _mark_design_guide_dirty()
    try:
        persist_active_beam_from_shared()
    except Exception:
        pass
    try:
        persist_state_snapshot()
    except Exception:
        pass
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        try:
            _append_design_guide_trace(
                "design_action_widget_sync_exit",
                {
                    "widget_key": str(widget_key),
                    "shared_key": str(shared_key),
                    "proxy_key": str(proxy_key) if proxy_key else None,
                    "shared_after": get_param(shared_key, None),
                    "proxy_after": get_param(proxy_key, None) if proxy_key else None,
                    "resolved_actions": _debug_resolved_guidance_actions(_shared_state_snapshot()),
                },
                run_id=f"daws_{int(time.time() * 1000)}",
                source="design_action_widget_sync",
            )
        except Exception:
            pass
    _sync_auto_design_invalidation(_shared_state_snapshot())
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        _debug_check_design_action_consistency(_shared_state_snapshot())
    if trigger_rerun and not bool(st.session_state.get("_solver_running", False)):
        _record_inputs_rerun_trigger("design_action_widget_callback", widget_key=widget_key, shared_key=shared_key)
        st.rerun()


def _make_design_action_widget_callback(widget_key: str, shared_key: str, proxy_key: str | None = None):
    def _callback() -> None:
        _sync_design_action_widget_to_shared(
            widget_key,
            shared_key,
            proxy_key,
            # Streamlit already reruns after on_change callbacks; requesting
            # another rerun here only produces a warning banner.
            trigger_rerun=False,
        )

    return _callback


def _commit_design_action_widgets_to_shared(selected_prefix: str) -> None:
    for spec in _design_action_widget_specs(selected_prefix):
        widget_key = spec["widget_key"]
        if widget_key not in st.session_state:
            continue
        _sync_design_action_widget_to_shared(
            widget_key,
            str(spec["shared_key"]),
            spec.get("proxy_key"),
        )


def _reconcile_design_action_widgets_with_shared(selected_prefix: str) -> list[str]:
    """Fallback sync for live edits when widget state drifted but on_change did not land."""
    changed: list[str] = []
    reconcile_probe: list[dict[str, object]] = []
    for spec in _design_action_widget_specs(selected_prefix):
        widget_key = str(spec["widget_key"])
        shared_key = str(spec["shared_key"])
        if widget_key not in st.session_state:
            reconcile_probe.append(
                {
                    "widget_key": widget_key,
                    "shared_key": shared_key,
                    "status": "missing_widget",
                }
            )
            continue
        try:
            widget_value = float(st.session_state.get(widget_key) or 0.0)
        except (TypeError, ValueError):
            reconcile_probe.append(
                {
                    "widget_key": widget_key,
                    "shared_key": shared_key,
                    "status": "bad_widget_value",
                    "widget_value_raw": st.session_state.get(widget_key),
                }
            )
            continue
        try:
            shared_value = float(get_param(shared_key, 0.0) or 0.0)
        except (TypeError, ValueError):
            shared_value = 0.0
        reconcile_probe.append(
            {
                "widget_key": widget_key,
                "shared_key": shared_key,
                "widget_value": widget_value,
                "shared_value": shared_value,
                "diff": float(widget_value - shared_value),
                "status": "equal" if abs(widget_value - shared_value) <= 1e-9 else "diff",
            }
        )
        if abs(widget_value - shared_value) <= 1e-9:
            continue
        _sync_design_action_widget_to_shared(
            widget_key,
            shared_key,
            spec.get("proxy_key"),
        )
        changed.append(shared_key)
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        try:
            _append_design_guide_trace(
                "design_action_reconcile",
                {
                    "selected_prefix": str(selected_prefix),
                    "changed": list(changed),
                    "probe": reconcile_probe,
                },
                run_id=f"dar_{int(time.time() * 1000)}",
                source="design_action_reconcile",
            )
        except Exception:
            pass
    return changed


def _reconcile_inputs_shear_widgets_with_shared() -> list[str]:
    """Fallback sync for visible Inputs-page shear widgets before one-click starts."""
    changed: list[str] = []
    reconcile_probe: list[dict[str, object]] = []
    shared_before = _shared_state_snapshot()
    widget_specs = (
        ("inputs_lig_d", "lig_d", int, 0),
        ("inputs_lig_legs", "lig_legs", int, 0),
        ("inputs_s_lig", "s_lig", float, float(CANONICAL_NO_SHEAR_SLIG_MM)),
    )
    pending_updates: dict[str, object] = {}
    for widget_key, shared_key, caster, default in widget_specs:
        if widget_key not in st.session_state:
            reconcile_probe.append(
                {
                    "widget_key": widget_key,
                    "shared_key": shared_key,
                    "status": "missing_widget",
                }
            )
            continue
        raw_widget_value = st.session_state.get(widget_key)
        try:
            widget_value = caster(raw_widget_value if raw_widget_value is not None else default)
        except (TypeError, ValueError):
            reconcile_probe.append(
                {
                    "widget_key": widget_key,
                    "shared_key": shared_key,
                    "status": "bad_widget_value",
                    "widget_value_raw": raw_widget_value,
                }
            )
            continue
        try:
            shared_value = caster(shared_before.get(shared_key, default) if shared_before.get(shared_key, default) is not None else default)
        except (TypeError, ValueError):
            shared_value = caster(default)
        diff = float(widget_value) - float(shared_value)
        reconcile_probe.append(
            {
                "widget_key": widget_key,
                "shared_key": shared_key,
                "widget_value": widget_value,
                "shared_value": shared_value,
                "diff": diff,
                "status": "equal" if abs(diff) <= 1e-9 else "diff",
            }
        )
        if abs(diff) <= 1e-9:
            continue
        pending_updates[shared_key] = widget_value
    if pending_updates:
        normalized_updates = _normalise_invalid_shear_state_updates(
            shared_before,
            pending_updates,
            source="handle_auto_design:inputs_shear_reconcile",
        )
        for shared_key, value in normalized_updates.items():
            try:
                prior_value = shared_before.get(shared_key)
                value_f = float(value) if isinstance(value, (int, float)) else value
                prior_f = float(prior_value) if isinstance(prior_value, (int, float)) else prior_value
                same = (
                    abs(value_f - prior_f) <= 1e-9
                    if isinstance(value_f, (int, float)) and isinstance(prior_f, (int, float))
                    else value_f == prior_f
                )
            except Exception:
                same = value == shared_before.get(shared_key)
            if same:
                continue
            set_shared(shared_key, value, source="handle_auto_design:inputs_shear_reconcile")
            changed.append(shared_key)
        if changed:
            _normalise_invalid_shear_state_in_shared(source="handle_auto_design:inputs_shear_reconcile")
            _refresh_canonical_shear_widgets(source="handle_auto_design:inputs_shear_reconcile")
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        try:
            _append_design_guide_trace(
                "inputs_shear_reconcile",
                {
                    "changed": list(changed),
                    "pending_updates": dict(pending_updates),
                    "probe": reconcile_probe,
                },
                run_id=f"isr_{int(time.time() * 1000)}",
                source="inputs_shear_reconcile",
            )
        except Exception:
            pass
    return changed


def _mirror_design_action_proxies_from_shared(selected_prefix: str) -> None:
    proxy_pairs = (
        ("load_Mstar_pos_proxy", f"{selected_prefix}_Mstar_pos_manual"),
        ("load_Mstar_neg_proxy", f"{selected_prefix}_Mstar_neg_manual"),
        ("load_Mstar_proxy", f"{selected_prefix}_Mstar"),
        ("load_Vstar_proxy", f"{selected_prefix}_Vstar"),
        ("load_Nstar_proxy", f"{selected_prefix}_Nstar"),
    )
    for proxy_key, shared_key in proxy_pairs:
        set_shared(proxy_key, float(get_param(shared_key, 0.0) or 0.0), source="design_action_proxy_mirror")


def _hydrate_design_action_widgets_from_shared(selected_prefix: str, *, force: bool = False, design_controls: bool = False) -> None:
    specs = _design_action_widget_specs(selected_prefix)
    signature = (
        selected_prefix,
        bool(design_controls),
        tuple(
            float(get_param(str(spec["shared_key"]), 0.0) or 0.0)
            for spec in specs
        ),
    )
    should_hydrate = force or design_controls or st.session_state.get("_design_action_widget_signature") != signature
    # Snapshot widget keys before sync (for dev-only hydration trace).
    _dbg_w_pos = st.session_state.get("inputs_load_Mstar_pos_proxy")
    _dbg_w_neg = st.session_state.get("inputs_load_Mstar_neg_proxy")
    _dbg_w_signed = st.session_state.get("inputs_load_Mstar_proxy")
    for spec in specs:
        widget_key = str(spec["widget_key"])
        shared_key = str(spec["shared_key"])
        if should_hydrate or widget_key not in st.session_state:
            shared_value = float(get_param(shared_key, 0.0) or 0.0)
            old_widget_value = st.session_state.get(widget_key)
            if old_widget_value != shared_value:
                st.session_state[widget_key] = shared_value
    st.session_state["_design_action_widget_signature"] = signature

    # TODO(remove): temporary hydration trace for design-action ghost values (canonical vs widget).
    if bool(st.session_state.get("_dev_mode")):
        try:
            hc_log(
                "[design_action_hydrate]",
                selected_prefix=selected_prefix,
                actions_mode=st.session_state.get("actions_mode"),
                design_controls=bool(design_controls),
                should_hydrate=bool(should_hydrate),
                canonical_pos=float(
                    get_param(f"{selected_prefix}_Mstar_pos_manual", 0.0) or 0.0
                ),
                canonical_neg=float(
                    get_param(f"{selected_prefix}_Mstar_neg_manual", 0.0) or 0.0
                ),
                canonical_signed=float(
                    get_param(f"{selected_prefix}_Mstar", 0.0) or 0.0
                ),
                widget_pos_before=_dbg_w_pos,
                widget_neg_before=_dbg_w_neg,
                widget_signed_before=_dbg_w_signed,
                widget_pos_after_render=st.session_state.get("inputs_load_Mstar_pos_proxy"),
                widget_neg_after_render=st.session_state.get("inputs_load_Mstar_neg_proxy"),
                widget_signed_after_render=st.session_state.get("inputs_load_Mstar_proxy"),
            )
        except Exception:
            pass


def _render_design_action_number_row(
    *,
    label: str,
    widget_key: str,
    help_text: str,
    on_change,
    disabled: bool = False,
    col_label=None,
    col_input=None,
) -> float:
    if col_label is None or col_input is None:
        col1, col2 = st.columns([1, 2], gap="medium", vertical_alignment="center")
    else:
        col1, col2 = col_label, col_input
    with col1:
        label_with_hover(label, help_text, required=False)
    with col2:
        _register_rendered_key(widget_key)
        return float(
            st.number_input(
                label,
                key=widget_key,
                format="%.1f",
                step=1.0,
                label_visibility="collapsed",
                on_change=on_change,
                disabled=disabled,
            )
            or 0.0
        )


def _debug_check_design_action_consistency(state: dict) -> None:
    if not DEBUG_DESIGN_GUIDANCE_PROBE:
        return
    if str(st.session_state.get("loads_edit_mode", "ULS") or "ULS").upper() != "ULS":
        return
    actions = _resolve_design_actions_from_state(state)
    payload = {
        "widget_M_pos": st.session_state.get("inputs_load_Mstar_pos_proxy"),
        "widget_M_neg": st.session_state.get("inputs_load_Mstar_neg_proxy"),
        "widget_V": st.session_state.get("inputs_load_Vstar_proxy"),
        "shared_uls_M": st.session_state.get("uls_Mstar"),
        "shared_uls_M_pos": st.session_state.get("uls_Mstar_pos_manual"),
        "shared_uls_M_neg": st.session_state.get("uls_Mstar_neg_manual"),
        "shared_uls_V": st.session_state.get("uls_Vstar"),
        "resolved_M": actions.get("Mu"),
        "resolved_V": actions.get("Vu"),
    }
    _agent_debug_log(
        "Design action consistency check",
        payload,
        location="inputs_page.py:_debug_check_design_action_consistency",
        hypothesis_id="H51",
    )


