def _candidate_leg_counts(cur_legs: int, *, conservative: bool) -> list[int]:
    cur = max(int(cur_legs or 2), 2)
    if conservative:
        return [n for n in range(cur - 1, 1, -1)]
    return [n for n in range(cur + 1, 9)]


def _iter_shear_recommendation_ladder_states(state: dict, *, conservative: bool) -> list[tuple[str, dict]]:
    trials: list[tuple[str, dict]] = []
    geo_lock = _geometry_lock_enabled(state)
    cur_s = float(_float_from_state(state, "s_lig", 0.0) or 0.0)
    cur_legs = max(_int_from_state(state, "lig_legs", 2), 2)
    cur_dia = max(_int_from_state(state, "lig_d", 10), 10)
    width_key, _, cur_w = _resolve_geometry_width_context(state)
    cur_d = float(_float_from_state(state, "D", 600.0) or 600.0)
    cur_fc = float(_float_from_state(state, "fc", 32.0) or 32.0)

    def _push(branch: str, st: dict) -> None:
        trials.append((branch, dict(st)))

    if conservative:
        if _shear_reinforcement_is_active(state):
            looser = [float(x) for x in REO_SPACINGS if float(x) > cur_s + 1e-9]
            for s in sorted(looser)[:4]:
                ns = dict(state)
                ns["lig_legs"] = int(max(_int_from_state(state, "lig_legs", 2), 2))
                ns["lig_d"] = int(max(_int_from_state(state, "lig_d", 10), 10))
                ns["s_lig"] = float(s)
                _push("spacing_looser", ns)
            for nl in _candidate_leg_counts(cur_legs, conservative=True):
                ns = dict(state)
                ns["lig_legs"] = int(max(2, nl))
                ns["lig_d"] = int(cur_dia)
                ns["s_lig"] = float(cur_s)
                _push("legs_down", ns)
            smaller_dias = [int(d) for d in REO_BAR_DIAS if int(d) < int(cur_dia) and int(d) >= 10]
            for nd in sorted(smaller_dias, reverse=True)[:3]:
                ns = dict(state)
                ns["lig_d"] = int(nd)
                ns["lig_legs"] = int(cur_legs)
                ns["s_lig"] = float(cur_s)
                _push("dia_down", ns)
        if _int_from_state(state, "lig_legs", 0) > 0 and _shear_state_eligible_for_no_links(state):
            ns = dict(state)
            ns["lig_legs"] = 0
            ns["lig_d"] = 0
            ns["s_lig"] = float(max(_float_from_state(state, "s_lig", 200.0), 1.0))
            _push("no_ligs", ns)
        return trials

    if not _shear_reinforcement_is_active(state):
        act = _activation_shear_state(state)
        if _make_auto_design_candidate_key(act) != _make_auto_design_candidate_key(state):
            _push("shear_activation", act)
        return trials

    eligible_s = [float(x) for x in REO_SPACINGS if float(x) < cur_s - 1e-9]
    for s in sorted(eligible_s)[:5]:
        ns = dict(state)
        ns["lig_legs"] = int(cur_legs)
        ns["lig_d"] = int(cur_dia)
        ns["s_lig"] = float(s)
        _push("spacing_tighter", ns)
    for nl in _candidate_leg_counts(cur_legs, conservative=False):
        if nl < 2 or nl == cur_legs:
            continue
        ns = dict(state)
        ns["lig_legs"] = int(nl)
        ns["lig_d"] = int(cur_dia)
        ns["s_lig"] = float(cur_s)
        _push("legs_up", ns)
    for nd in REO_BAR_DIAS:
        if int(nd) > int(cur_dia) and int(nd) <= 24:
            ns = dict(state)
            ns["lig_d"] = int(nd)
            ns["lig_legs"] = int(cur_legs)
            ns["s_lig"] = float(cur_s)
            _push("dia_up", ns)

    if not geo_lock:
        for delta in GUIDANCE_GEOMETRY_TRIAL_DELTAS_MM:
            ns = dict(state)
            ns["D"] = float(int(round(max(350.0, cur_d + float(delta)) / 10.0) * 10))
            _push("depth_up", ns)
        for delta in GUIDANCE_GEOMETRY_TRIAL_DELTAS_MM:
            ns = dict(state)
            nw = float(int(round(max(250.0, cur_w + float(delta)) / 10.0) * 10))
            ns[width_key] = nw
            if width_key != "b":
                ns["b"] = nw
            _push("width_up", ns)

    if cur_fc < 65.0:
        ns = dict(state)
        ns["fc"] = float(min(65.0, int(round((cur_fc + 5.0) / 5.0) * 5)))
        if abs(float(ns["fc"]) - cur_fc) > 1e-9:
            _push("material_fc", ns)

    return trials


def _shear_ladder_validate_candidate(
    state: dict,
    candidate: dict | None,
    *,
    branch: str,
    conservative: bool,
    baseline_shear_util: float | None,
) -> tuple[bool, str]:
    if candidate is None:
        return False, "eval_none"
    updates = candidate.get("updates") or {}
    if not updates:
        return False, "empty_updates"
    if _updates_match_state(state, updates):
        return False, "no_state_change"
    if conservative:
        _pure_u, _bad_u = _shear_detailing_updates_pure(dict(updates))
        if not _pure_u:
            return False, "non_shear_detailing_updates_in_conservative_shear_ladder"
    cs = dict(candidate.get("state") or {})
    legs = _int_from_state(cs, "lig_legs", 0)
    if legs == 1:
        return False, "lig_legs_single_leg_forbidden"
    dia = _int_from_state(cs, "lig_d", 0)
    if legs > 0 and dia <= 0:
        return False, "zero_link_diameter"
    s_prop = _float_from_state(cs, "s_lig", 0.0)
    s_cur = _float_from_state(state, "s_lig", 0.0)
    leg_cur = max(_int_from_state(state, "lig_legs", 2), 2)
    new_util = ((candidate.get("overview") or {}).get("utils") or {}).get("shear")

    if conservative:
        if not bool(candidate.get("is_compliant")):
            return False, "not_compliant"
        if branch == "no_ligs":
            if legs != 0:
                return False, "no_ligs_branch_requires_zero_legs"
            if not _shear_state_eligible_for_no_links(state):
                return False, "no_links_not_eligible_precheck"
            if not _shear_no_links_candidate_passes_code(state, candidate):
                return False, "no_links_torsion_or_min_shear_or_strength"
            return True, "accepted"
        if legs == 0:
            return False, "zero_ligs_only_via_no_ligs_branch"
        if legs < 2:
            return False, "lig_legs_below_2"
        if branch == "spacing_looser" and s_prop <= s_cur + 1e-9:
            return False, "spacing_not_increased"
        if branch == "legs_down":
            if leg_cur <= 2 or legs >= leg_cur:
                return False, "legs_not_reduced"
        if branch == "dia_down":
            if dia >= _int_from_state(state, "lig_d", 0):
                return False, "dia_not_reduced"
        return True, "accepted"

    if legs == 0:
        return False, "zero_ligs_in_failing_branch"
    if legs < 2:
        return False, "lig_legs_below_2"
    if legs < leg_cur:
        return False, "removed_closed_ligs"
    if branch == "spacing_tighter" and s_cur > 1e-9 and s_prop >= s_cur - 1e-9:
        return False, "spacing_not_reduced"
    if new_util is None:
        return False, "missing_shear_util"
    try:
        nu = float(new_util)
        if math.isnan(nu):
            return False, "missing_shear_util"
    except (TypeError, ValueError):
        return False, "missing_shear_util"
    if baseline_shear_util is not None:
        if float(nu) >= float(baseline_shear_util) - 1e-9:
            return False, "shear_util_not_improved"
    return True, "accepted"


def _log_design_reco_candidate_rank(
    *,
    domain: str,
    event: str,
    candidate: dict | None,
    reason: str,
    util_before: float | None = None,
    util_after: float | None = None,
) -> None:
    payload = {
        "domain": domain,
        "event": event,
        "reason": reason,
        "candidate_label": None if candidate is None else str(candidate.get("label") or ""),
        "candidate_source": None if candidate is None else str(candidate.get("source") or ""),
        "candidate_type": None
        if candidate is None
        else str(
            candidate.get("shear_candidate_type")
            or candidate.get("shear_ladder_branch")
            or candidate.get("recommendation_geometry_trial")
            or "",
        ),
        "branch": None if candidate is None else str(candidate.get("shear_ladder_branch") or ""),
        "updates": None if candidate is None else dict(candidate.get("updates") or {}),
        "score": None if candidate is None else candidate.get("score"),
        "util_before": util_before,
        "util_after": util_after,
        "candidate_post_util": None if candidate is None else candidate.get("candidate_post_util"),
        "candidate_reaches_target_band": None if candidate is None else candidate.get("candidate_reaches_target_band"),
        "candidate_distance_to_target_band": None
        if candidate is None
        else candidate.get("candidate_distance_to_target_band"),
    }
    if DEBUG_DESIGN_GUIDANCE_PROBE:
        _agent_debug_log(
            "Design recommendation ranking",
            payload,
            location="inputs_page.py:_log_design_reco_candidate_rank",
            hypothesis_id="H_DESIGN_RECO_RANK",
        )
    if _ACTIVE_GUIDANCE_RECO_TRACE is not None:
        _append_design_guide_reco_trace(payload)


def _shear_util_from_overview_candidate(candidate: dict | None) -> float | None:
    if not candidate:
        return None
    try:
        u = ((candidate.get("overview") or {}).get("utils") or {}).get("shear")
        if u is None:
            return None
        f = float(u)
        return None if math.isnan(f) else f
    except (TypeError, ValueError):
        return None


def _shear_recommendation_prefinal_eligible(
    candidate: dict | None,
    *,
    state: dict,
    conservative: bool,
    baseline_su: float | None,
) -> tuple[bool, str]:
    if not candidate:
        return False, "none"
    updates = candidate.get("updates") or {}
    if not updates:
        return False, "empty_updates"
    if _updates_match_state(state, updates):
        return False, "noop"
    if not str(candidate.get("label") or "").strip():
        return False, "missing_label"
    if candidate.get("score") is None:
        return False, "missing_score"
    su = _shear_util_from_overview_candidate(candidate)
    if su is None:
        return False, "missing_shear_util"
    if not conservative and baseline_su is not None and float(su) >= float(baseline_su) - 1e-9:
        return False, "shear_util_not_improved"
    branch = str(candidate.get("shear_ladder_branch") or "")
    cs = dict(candidate.get("state") or {})
    if branch == "spacing_tighter":
        s_prop = _float_from_state(cs, "s_lig", _float_from_state(state, "s_lig", 0.0))
        s_cur = _float_from_state(state, "s_lig", 0.0)
        if s_cur > 1e-9 and s_prop >= s_cur - 1e-9:
            return False, "spacing_not_reduced"
    if not conservative:
        legs = _int_from_state(cs, "lig_legs", 0)
        if legs > 0 and legs < 2:
            return False, "lig_legs_below_2"
    return True, "ok"


def _pick_best_shear_recommendation_by_selector(
    candidates: list[dict],
    *,
    state: dict,
    seed_candidate: dict,
    mode_config: dict,
    conservative: bool,
    baseline_su: float | None,
) -> dict | None:
    pool = [c for c in candidates if c]
    while pool:
        ranked_pool = sorted(
            pool,
            key=lambda item: _shear_candidate_selector_key(item, seed_candidate, mode_config),
        )
        pick = ranked_pool[0] if ranked_pool else None
        if pick is None:
            return None
        if _updates_match_state(state, pick.get("updates") or {}):
            _log_design_reco_candidate_rank(
                domain="shear",
                event="rejected",
                candidate=pick,
                reason="noop_updates_match_state",
                util_after=_shear_util_from_overview_candidate(pick),
            )
            pool = [x for x in pool if x is not pick]
            continue
        su = _shear_util_from_overview_candidate(pick)
        if su is None:
            _log_design_reco_candidate_rank(
                domain="shear",
                event="rejected",
                candidate=pick,
                reason="missing_shear_util",
            )
            pool = [x for x in pool if x is not pick]
            continue
        if not conservative and baseline_su is not None and float(su) >= float(baseline_su) - 1e-9:
            _log_design_reco_candidate_rank(
                domain="shear",
                event="rejected",
                candidate=pick,
                reason="shear_util_not_improved_vs_baseline",
                util_before=float(baseline_su),
                util_after=float(su),
            )
            pool = [x for x in pool if x is not pick]
            continue
        _log_design_reco_candidate_rank(
            domain="shear",
            event="accepted",
            candidate=pick,
            reason="selector_top_valid",
            util_before=None if conservative else baseline_su,
            util_after=float(su),
        )
        return pick
    return None


def _is_strictly_rejectable_band_winner(candidate: dict | None, *, state: dict) -> tuple[bool, str]:
    if not isinstance(candidate, dict):
        return True, "invalid_candidate"
    if not bool(candidate.get("is_compliant")):
        return True, "noncompliant_candidate"
    if not bool(candidate.get("candidate_reaches_target_band")):
        return True, "not_target_band_candidate"
    updates = candidate.get("updates")
    if not isinstance(updates, dict) or not updates:
        return True, "missing_or_unusable_updates"
    if _updates_match_state(state, updates):
        return True, "noop_updates_match_state"
    if not str(candidate.get("label") or "").strip():
        return True, "missing_label"
    return False, "ok"


def _legacy_bottom_local_rejection_reason(
    pick: dict,
    *,
    seed_candidate: dict,
    seed_bu_f: float | None,
    ductility_seed: bool,
    seed_du: float | None,
) -> str | None:
    bu = ((pick.get("overview") or {}).get("utils") or {}).get("bending")
    try:
        bu_f = float(bu) if bu is not None else None
    except (TypeError, ValueError):
        bu_f = None
    if bu_f is None:
        return "missing_bending_util"
    if ductility_seed:
        pdu = _candidate_ductility_util(pick)
        if seed_du is not None and pdu is not None and float(pdu) >= float(seed_du) - 1e-9:
            return "ductility_not_improved"
        return None
    if seed_bu_f is not None and float(bu_f) >= float(seed_bu_f) - 1e-9:
        return "bending_util_not_improved"
    return None


def _pick_best_bottom_recommendation_by_selector(
    candidates: list[dict],
    *,
    state: dict,
    seed_candidate: dict,
    mode_config: dict,
) -> dict | None:
    pool = [c for c in candidates if c]
    seed_bu = ((seed_candidate.get("overview") or {}).get("utils") or {}).get("bending")
    try:
        seed_bu_f = float(seed_bu) if seed_bu is not None else None
    except (TypeError, ValueError):
        seed_bu_f = None
    ductility_seed = _candidate_ductility_governs(seed_candidate)
    seed_du = _candidate_ductility_util(seed_candidate)
    while pool:
        pick = _select_best_auto_design_candidate(pool, mode_config, seed_candidate)
        if pick is None:
            return None
        _band_seen = bool(pick.get("candidate_reaches_target_band")) and bool(pick.get("is_compliant"))
        if _band_seen:
            _strict_reject, _strict_reason = _is_strictly_rejectable_band_winner(pick, state=state)
            if _strict_reject:
                _log_design_reco_candidate_rank(
                    domain="bending",
                    event="rejected",
                    candidate=pick,
                    reason=f"strict_band_reject:{_strict_reason}",
                )
                _merge_design_guide_rank_trace(
                    {
                        "final_selector_band_winner_seen": True,
                        "final_selector_band_winner_accepted": False,
                        "final_selector_band_winner_rejected_reason": str(_strict_reason),
                        "final_selector_used_strict_band_accept_rule": True,
                        "winner_pool_mode": pick.get("winner_pool_mode"),
                        "selected_because_band": bool(pick.get("winning_candidate_selected_from_band_reachers")),
                    },
                )
                pool = [x for x in pool if x is not pick]
                continue
            _legacy_reason = _legacy_bottom_local_rejection_reason(
                pick,
                seed_candidate=seed_candidate,
                seed_bu_f=seed_bu_f,
                ductility_seed=ductility_seed,
                seed_du=seed_du,
            )
            _log_design_reco_candidate_rank(
                domain="bending",
                event="accepted",
                candidate=pick,
                reason="strict_band_winner_accept",
                util_before=seed_du if ductility_seed else seed_bu_f,
                util_after=_candidate_ductility_util(pick) if ductility_seed else pick.get("candidate_post_util"),
            )
            _merge_design_guide_rank_trace(
                {
                    "final_selector_band_winner_seen": True,
                    "final_selector_band_winner_accepted": True,
                    "final_selector_band_winner_rejected_reason": None,
                    "final_selector_used_strict_band_accept_rule": True,
                    "winner_pool_mode": pick.get("winner_pool_mode"),
                    "selected_because_band": bool(pick.get("winning_candidate_selected_from_band_reachers")),
                    "final_winner_label": str(pick.get("label") or ""),
                    "final_winner_reaches_target_band": bool(pick.get("candidate_reaches_target_band")),
                    "final_winner_post_util": pick.get("candidate_post_util"),
                    "final_winner_goal_score": pick.get("candidate_goal_score"),
                    "final_selector_band_winner_would_have_legacy_reject_reason": _legacy_reason,
                    "final_selector_band_winner_accepted_over_legacy_gate": bool(_legacy_reason),
                },
            )
            return pick
        if not str(pick.get("label") or "").strip():
            _log_design_reco_candidate_rank(
                domain="bending",
                event="rejected",
                candidate=pick,
                reason="missing_label",
            )
            pool = [x for x in pool if x is not pick]
            continue
        if _updates_match_state(state, pick.get("updates") or {}):
            _log_design_reco_candidate_rank(
                domain="bending",
                event="rejected",
                candidate=pick,
                reason="noop_updates_match_state",
            )
            pool = [x for x in pool if x is not pick]
            continue
        bu = ((pick.get("overview") or {}).get("utils") or {}).get("bending")
        try:
            bu_f = float(bu) if bu is not None else None
        except (TypeError, ValueError):
            bu_f = None
        if bu_f is None:
            _log_design_reco_candidate_rank(
                domain="bending",
                event="rejected",
                candidate=pick,
                reason="missing_bending_util",
            )
            pool = [x for x in pool if x is not pick]
            continue
        if ductility_seed:
            pdu = _candidate_ductility_util(pick)
            if seed_du is not None and pdu is not None and float(pdu) >= float(seed_du) - 1e-9:
                _log_design_reco_candidate_rank(
                    domain="bending",
                    event="rejected",
                    candidate=pick,
                    reason="ductility_not_improved",
                    util_before=float(seed_du),
                    util_after=float(pdu) if pdu is not None else None,
                )
                pool = [x for x in pool if x is not pick]
                continue
        elif seed_bu_f is not None and float(bu_f) >= float(seed_bu_f) - 1e-9:
            _log_design_reco_candidate_rank(
                domain="bending",
                event="rejected",
                candidate=pick,
                reason="bending_util_not_improved",
                util_before=float(seed_bu_f),
                util_after=float(bu_f),
            )
            pool = [x for x in pool if x is not pick]
            continue
        _log_design_reco_candidate_rank(
            domain="bending",
            event="accepted",
            candidate=pick,
            reason="selector_top_valid",
            util_before=seed_du if ductility_seed else seed_bu_f,
            util_after=_candidate_ductility_util(pick) if ductility_seed else bu_f,
        )
        _merge_design_guide_rank_trace(
            {
                "final_selector_band_winner_seen": False,
                "final_selector_band_winner_accepted": False,
                "final_selector_band_winner_rejected_reason": None,
                "final_selector_used_strict_band_accept_rule": False,
                "winner_pool_mode": pick.get("winner_pool_mode"),
                "selected_because_band": bool(pick.get("winning_candidate_selected_from_band_reachers")),
                "final_winner_label": str(pick.get("label") or ""),
                "final_winner_reaches_target_band": bool(pick.get("candidate_reaches_target_band")),
                "final_winner_post_util": pick.get("candidate_post_util"),
                "final_winner_goal_score": pick.get("candidate_goal_score"),
            },
        )
        return pick
    return None


def _try_shear_no_demand_cleanup_recommendation(state: dict, overview: dict, actions: dict) -> dict | None:
    if not _shear_demands_negligible(actions):
        return None
    if not _shear_reinforcement_is_active(state):
        return None
    su = ((overview or {}).get("utils") or {}).get("shear")
    try:
        su_f = float(su) if su is not None else 0.0
        if math.isnan(su_f):
            su_f = 0.0
    except (TypeError, ValueError):
        su_f = 0.0
    if su_f > GUIDANCE_SHEAR_UTIL_NEGLIGIBLE:
        return None
    cleanup_updates = {
        "lig_d": 0,
        "lig_legs": 0,
        "s_lig": float(CANONICAL_NO_SHEAR_SLIG_MM),
    }
    if _updates_match_state(state, cleanup_updates):
        return None
    trial_state = dict(state)
    trial_state.update(cleanup_updates)
    cand = evaluate_candidate_full(
        _guidance_state_snapshot(trial_state),
        source="shear_no_demand_cleanup_probe",
        updates=cleanup_updates,
    )
    if not cand or not bool(cand.get("is_compliant")):
        _merge_design_guide_rank_trace(
            {"shear_no_demand_cleanup": {"accepted": False, "reason": "non_compliant_when_links_cleared"}},
        )
        return None
    shear_preview = _evaluate_shear_with_state(dict(cand.get("state") or trial_state)) or {}
    _merge_design_guide_rank_trace(
        {
            "shear_no_demand_cleanup": {
                "accepted": True,
                "removed_shear_links": True,
                "prior_lig_d": _int_from_state(state, "lig_d", 0),
                "prior_lig_legs": _int_from_state(state, "lig_legs", 0),
            },
        },
    )
    return {
        "updates": dict(cleanup_updates),
        "label": "Remove shear reinforcement (no shear/torsion design demand)",
        "util": float(((cand.get("overview") or {}).get("utils") or {}).get("shear", 0.0) or 0.0),
        "web_util": float(shear_preview.get("web_util", 0.0) or 0.0),
        "phi_vu": float(shear_preview.get("phi_vu", 0.0) or 0.0),
        "veq": float(shear_preview.get("veq", 0.0) or 0.0),
        "score": 0.0,
        "severity_band": "cleanup",
        "candidate_type": "no_shear_design_cleanup",
    }


def _compute_shear_recommendation(state: dict) -> dict | None:
    state = _guidance_state_snapshot(state)
    if not _recommendation_search_allowed(state):
        return None
    design_context = _build_design_actions_context(state)
    overview = _collect_design_overview(state, context=design_context)
    actions = design_context.get("actions") or {}
    cleanup_rec = _try_shear_no_demand_cleanup_recommendation(state, overview, actions)
    if cleanup_rec is not None:
        return cleanup_rec
    _reco_gate = _combined_underdesign_shear_strengthening_truth_gate_payload(
        state,
        overview=overview,
        efficiency_classification=None,
    )
    if bool(_reco_gate.get("combined_underdesign_shear_truth_block_active")):
        _merge_design_guide_rank_trace({"shear_recommendation_truth_gate": dict(_reco_gate)})
        return None
    if not _shear_change_is_relevant(overview, actions):
        return None
    mode_config = _design_mode_config(_design_optimisation_goal(state))
    seed_candidate = evaluate_candidate_full(state, source="shear_recommendation_seed")
    if not seed_candidate:
        return None
    context = _build_auto_design_context(
        seed_candidate["state"],
        mode_config,
        reference_overview=seed_candidate.get("overview"),
    )
    eval_cache: dict = {}
    metrics = {
        "_reference_overview": seed_candidate.get("overview"),
        "generated_count": 0,
        "unique_eval_count": 0,
        "cache_hits": 0,
        "fast_eval_total_ms": 0.0,
        "cap_hit": False,
    }
    seed_shear_util = (((seed_candidate or {}).get("overview") or {}).get("utils") or {}).get("shear")
    try:
        baseline_su = float(seed_shear_util) if seed_shear_util is not None else None
    except (TypeError, ValueError):
        baseline_su = None
    severity_band = _shear_severity_band(seed_shear_util)
    family_audit: dict[str, list[dict]] = {}
    conservative = _shear_recommendation_overview_is_conservative_cleanup(overview)
    ladder_mode = "conservative" if conservative else "strengthening"
    if _shear_spacing_layout_must_not_trigger_strengthening(state, overview) and not conservative:
        _merge_design_guide_rank_trace(
            {"shear_recommendation_suppressed": {"reason": "spacing_layout_non_governing_sectional_pass"}},
        )
        return None
    cur_legs_log = _int_from_state(state, "lig_legs", 0)
    cur_s_log = _float_from_state(state, "s_lig", 0.0)
    leg_search_counts = _candidate_leg_counts(cur_legs_log, conservative=conservative)

    trial_states = _iter_shear_recommendation_ladder_states(state, conservative=conservative)
    seen_keys: set[tuple] = set()
    candidates: list[dict] = []

    for branch, candidate_state in trial_states:
        ck = _make_auto_design_candidate_key(candidate_state)
        if ck in seen_keys:
            _log_shear_ladder_attempt(
                state,
                ladder_mode=ladder_mode,
                branch=branch,
                lig_legs=cur_legs_log,
                s_lig=cur_s_log,
                proposed_updates=None,
                expected_util_after=None,
                decision="rejected",
                reason="duplicate_candidate_state",
            )
            continue
        seen_keys.add(ck)
        if _invalid_shear_spacing_change_without_activation(
            state,
            candidate_state,
            source="shear_recommendation",
        ):
            _log_shear_ladder_attempt(
                state,
                ladder_mode=ladder_mode,
                branch=branch,
                lig_legs=cur_legs_log,
                s_lig=cur_s_log,
                proposed_updates=None,
                expected_util_after=None,
                decision="rejected",
                reason="invalid_spacing_without_activation",
            )
            continue
        candidate = _evaluate_candidate_fast(
            candidate_state,
            seed_state=seed_candidate["state"],
            context=context,
            eval_cache=eval_cache,
            metrics=metrics,
            source="shear_recommendation",
            label=_shear_state_label(candidate_state),
            action_type="apply_shear_recommendation",
        )
        pu = (candidate or {}).get("updates")
        eu = None
        if candidate:
            try:
                eu = float(((candidate.get("overview") or {}).get("utils") or {}).get("shear") or float("nan"))
                if math.isnan(eu):
                    eu = None
            except (TypeError, ValueError):
                eu = None
        ok, reason = _shear_ladder_validate_candidate(
            state,
            candidate,
            branch=branch,
            conservative=conservative,
            baseline_shear_util=None if conservative else baseline_su,
        )
        _log_shear_ladder_attempt(
            state,
            ladder_mode=ladder_mode,
            branch=branch,
            lig_legs=cur_legs_log,
            s_lig=cur_s_log,
            proposed_updates=dict(pu) if isinstance(pu, dict) else None,
            expected_util_after=eu,
            decision="accepted" if ok else "rejected",
            reason=reason,
        )
        if not ok or candidate is None:
            _log_shear_candidate_debug(
                source="shear_recommendation",
                candidate_state=candidate_state,
                candidate=candidate,
            )
            continue
        if not conservative and candidate_materially_worsens(candidate, seed_candidate, mode_config, phase="shear_recommendation"):
            _log_shear_ladder_attempt(
                state,
                ladder_mode=ladder_mode,
                branch=branch,
                lig_legs=cur_legs_log,
                s_lig=cur_s_log,
                proposed_updates=dict(candidate.get("updates") or {}),
                expected_util_after=eu,
                decision="rejected",
                reason="materially_worse_non_shear",
            )
            continue
        candidate["score"] = _score_auto_design_candidate(candidate, mode_config, seed_candidate)
        candidate["shear_candidate_type"] = _shear_candidate_type(state, candidate.get("state") or candidate_state)
        candidate["shear_ladder_branch"] = branch
        _log_shear_candidate_debug(
            source="shear_recommendation",
            candidate_state=candidate_state,
            candidate=candidate,
        )
        candidates.append(candidate)

    if not conservative and _severe_shear_failure(seed_shear_util) and candidates:
        existing_keys = {_make_auto_design_candidate_key(dict(candidate.get("state") or {})) for candidate in candidates}
        ranked_base = _combined_shear_seed_candidates(
            candidates,
            seed_candidate=seed_candidate,
            base_state=state,
            severity_band=severity_band,
            seed_shear_util=seed_shear_util,
            limit=8,
        )
        for base_candidate in ranked_base:
            for combined_state in _generate_secondary_bending_tightening_states(base_candidate, limit=3):
                combined_key = _make_auto_design_candidate_key(combined_state)
                if combined_key in existing_keys:
                    continue
                combined_candidate = _evaluate_candidate_fast(
                    combined_state,
                    seed_state=seed_candidate["state"],
                    context=context,
                    eval_cache=eval_cache,
                    metrics=metrics,
                    source="shear_recommendation_combined",
                    label=(
                        f"Combined: {_shear_state_label(combined_state)}"
                        f" + {_bottom_reo_state_label(combined_state)}"
                    ),
                    action_type="apply_shear_recommendation",
                )
                pu_c = (combined_candidate or {}).get("updates")
                eu_c = None
                if combined_candidate:
                    try:
                        eu_c = float(((combined_candidate.get("overview") or {}).get("utils") or {}).get("shear") or float("nan"))
                        if math.isnan(eu_c):
                            eu_c = None
                    except (TypeError, ValueError):
                        eu_c = None
                ok_c, reason_c = _shear_ladder_validate_candidate(
                    state,
                    combined_candidate,
                    branch="combined_secondary_bending",
                    conservative=False,
                    baseline_shear_util=baseline_su,
                )
                _log_shear_ladder_attempt(
                    state,
                    ladder_mode=ladder_mode,
                    branch="combined_secondary_bending",
                    lig_legs=cur_legs_log,
                    s_lig=cur_s_log,
                    proposed_updates=dict(pu_c) if isinstance(pu_c, dict) else None,
                    expected_util_after=eu_c,
                    decision="accepted" if ok_c else "rejected",
                    reason=reason_c,
                )
                if not ok_c or combined_candidate is None:
                    continue
                if candidate_materially_worsens(combined_candidate, seed_candidate, mode_config, phase="shear_recommendation"):
                    _log_shear_ladder_attempt(
                        state,
                        ladder_mode=ladder_mode,
                        branch="combined_secondary_bending",
                        lig_legs=cur_legs_log,
                        s_lig=cur_s_log,
                        proposed_updates=dict(combined_candidate.get("updates") or {}),
                        expected_util_after=eu_c,
                        decision="rejected",
                        reason="materially_worse_non_shear",
                    )
                    continue
                combined_candidate["score"] = _score_auto_design_candidate(combined_candidate, mode_config, seed_candidate)
                combined_candidate["shear_candidate_type"] = "combined"
                combined_candidate["secondary_actions_combined"] = True
                combined_candidate["shear_ladder_branch"] = "combined_secondary_bending"
                candidates.append(combined_candidate)
                existing_keys.add(combined_key)

    if not candidates:
        _log_severe_shear_escalation(
            source="_compute_shear_recommendation",
            seed_candidate=seed_candidate,
            severity_band=severity_band,
            candidates=[],
            selected=None,
            family_audit=family_audit,
        )
        return None

    for cand in candidates:
        if cand.get("score") is None:
            cand["score"] = _score_auto_design_candidate(cand, mode_config, seed_candidate)

    eligible_shear: list[dict] = []
    for cand in candidates:
        ok_el, rsn_el = _shear_recommendation_prefinal_eligible(
            cand,
            state=state,
            conservative=conservative,
            baseline_su=None if conservative else baseline_su,
        )
        if ok_el:
            eligible_shear.append(cand)
        else:
            _log_design_reco_candidate_rank(
                domain="shear",
                event="rejected",
                candidate=cand,
                reason=str(rsn_el),
                util_before=None if conservative else baseline_su,
                util_after=_shear_util_from_overview_candidate(cand),
            )
    if conservative and _efficiency_reduction_profile_from_overview(overview):
        filtered_es: list[dict] = []
        for cand in eligible_shear:
            if _candidate_is_growth_move(seed_candidate, cand):
                _log_efficiency_growth_rejection(
                    candidate_family="shear",
                    seed_candidate=seed_candidate,
                    candidate=cand,
                )
                continue
            filtered_es.append(cand)
        eligible_shear = filtered_es
    if not eligible_shear:
        _log_severe_shear_escalation(
            source="_compute_shear_recommendation",
            seed_candidate=seed_candidate,
            severity_band=severity_band,
            candidates=candidates,
            selected=None,
            family_audit=family_audit,
        )
        return None

    _, target_hi, _ = _resolved_efficiency_target_band(
        mode_config,
        goal=_design_optimisation_goal(state),
    )
    shortlisted_shear = _shortlist_smallest_successful_shear_candidates(
        eligible_shear,
        state,
        target_hi=target_hi,
    )
    shortlist_used = len(shortlisted_shear) < len(eligible_shear)
    shortlist_best_magnitude = (
        _shear_change_magnitude(shortlisted_shear[0], state)
        if shortlisted_shear else None
    )
    selector_pool = [
        c for c in shortlisted_shear
        if _candidate_is_within_smallest_fix_band(c, shortlist_best_magnitude, state)
    ]
    if not selector_pool:
        selector_pool = list(shortlisted_shear)
    selector_pool_band_reachers = [
        c for c in selector_pool
        if bool(c.get("candidate_reaches_target_band"))
    ]
    selector_pool_best_post_util = min(
        (
            float(c.get("candidate_post_util"))
            for c in selector_pool
            if c.get("candidate_post_util") is not None
        ),
        default=None,
    )
    reintroduced_larger_candidates: list[dict] = []
    for cand in shortlisted_shear:
        if cand in selector_pool:
            continue
        cand_reaches_band = bool(cand.get("candidate_reaches_target_band"))
        cand_post_util = cand.get("candidate_post_util")
        materially_better = False
        if cand_post_util is not None and selector_pool_best_post_util is not None:
            try:
                materially_better = float(cand_post_util) < float(selector_pool_best_post_util) - 0.05
            except (TypeError, ValueError):
                materially_better = False
        only_band_candidate = cand_reaches_band and not selector_pool_band_reachers
        if materially_better or only_band_candidate:
            reintroduced_larger_candidates.append(cand)
    if reintroduced_larger_candidates:
        selector_pool.extend(reintroduced_larger_candidates)
    ranked_shear = _keep_top_candidates(selector_pool, mode_config, limit=min(24, len(selector_pool)))

    best = _pick_best_shear_recommendation_by_selector(
        ranked_shear,
        state=state,
        seed_candidate=seed_candidate,
        mode_config=mode_config,
        conservative=conservative,
        baseline_su=None if conservative else baseline_su,
    )
    if not best:
        _log_severe_shear_escalation(
            source="_compute_shear_recommendation",
            seed_candidate=seed_candidate,
            severity_band=severity_band,
            candidates=candidates,
            selected=None,
            family_audit=family_audit,
        )
        return None
    shear_preview = _evaluate_shear_with_state(best.get("state") or state) or {}
    _log_severe_shear_escalation(
        source="_compute_shear_recommendation",
        seed_candidate=seed_candidate,
        severity_band=severity_band,
        candidates=candidates,
        selected=best,
        family_audit=family_audit,
    )
    if _ACTIVE_GUIDANCE_RECO_TRACE is not None:
        _append_design_guide_reco_trace(
            {
                "domain": "shear",
                "event": "final_selected",
                "candidate_label": str(best.get("label") or ""),
                "branch": str(best.get("shear_ladder_branch") or ""),
                "candidate_type": str(best.get("shear_candidate_type") or ""),
                "updates": dict(best.get("updates") or {}),
                "score": best.get("score"),
                "util_before": None if conservative else baseline_su,
                "util_after": _shear_util_from_overview_candidate(best),
                "shear_leg_search_counts": list(leg_search_counts),
                "shear_leg_search_mode": ladder_mode,
                "shear_best_candidate_leg_count": best.get("shear_candidate_leg_count"),
                "shear_best_candidate_leg_delta": best.get("shear_candidate_leg_delta"),
                "shear_best_candidate_practicality_penalty": best.get("shear_candidate_total_practicality_penalty"),
                "shear_smallest_fix_shortlist_used": bool(shortlist_used),
                "shear_smallest_fix_shortlist_count": int(len(shortlisted_shear)),
                "shear_smallest_fix_best_magnitude": shortlist_best_magnitude,
                "shear_selector_smallest_mag": shortlist_best_magnitude,
                "shear_selector_pool_count": len(selector_pool),
                "shear_selector_larger_candidates_reintroduced_count": len(reintroduced_larger_candidates),
                "shear_selected_change_magnitude": _shear_change_magnitude(best, state),
            }
        )
    return {
        "updates": dict(best.get("updates") or {}),
        "label": str(best.get("label") or ""),
        "util": float(best.get("overview", {}).get("utils", {}).get("shear", 0.0) or 0.0),
        "web_util": float(shear_preview.get("web_util", 0.0) or 0.0),
        "phi_vu": float(shear_preview.get("phi_vu", 0.0) or 0.0),
        "veq": float(shear_preview.get("veq", 0.0) or 0.0),
        "score": float(best.get("score", 0.0) or 0.0),
        "severity_band": severity_band,
        "candidate_type": str(best.get("shear_candidate_type") or _shear_candidate_type(state, best.get("state") or state)),
        "shear_leg_search_counts": list(leg_search_counts),
        "shear_leg_search_mode": "conservative" if conservative else "strengthening",
        "shear_best_candidate_leg_count": best.get("shear_candidate_leg_count"),
        "shear_best_candidate_leg_delta": best.get("shear_candidate_leg_delta"),
        "shear_best_candidate_practicality_penalty": best.get("shear_candidate_total_practicality_penalty"),
        "shear_smallest_fix_shortlist_used": bool(shortlist_used),
        "shear_smallest_fix_shortlist_count": int(len(shortlisted_shear)),
        "shear_smallest_fix_best_magnitude": shortlist_best_magnitude,
        "shear_selector_smallest_mag": shortlist_best_magnitude,
        "shear_selector_pool_count": len(selector_pool),
        "shear_selector_larger_candidates_reintroduced_count": len(reintroduced_larger_candidates),
        "shear_selected_change_magnitude": _shear_change_magnitude(best, state),
    }


def _compute_geometry_recommendation(state: dict) -> dict | None:
    state = _guidance_state_snapshot(state)
    started_at = time.perf_counter()
    if _geometry_lock_enabled(state):
        return None
    if not _recommendation_search_allowed(state):
        return None
    mode_config = _design_mode_config(_design_optimisation_goal(state))
    seed_candidate = evaluate_candidate_full(state, source="geometry_recommendation_seed")
    if not seed_candidate:
        return None
    context = _build_auto_design_context(
        seed_candidate["state"],
        mode_config,
        reference_overview=seed_candidate.get("overview"),
    )
    eval_cache: dict = {}
    metrics = {
        "_reference_overview": seed_candidate.get("overview"),
        "generated_count": 0,
        "unique_eval_count": 0,
        "cache_hits": 0,
        "fast_eval_total_ms": 0.0,
        "cap_hit": False,
    }
    geometry_states: list[dict] = []
    if bool(seed_candidate.get("is_compliant")):
        for updates in _geometry_tightening_trial_updates(state):
            candidate_state = dict(state)
            candidate_state.update(updates)
            geometry_states.append(candidate_state)
    else:
        goal = _design_optimisation_goal(state)
        if goal == "shallower_beam":
            geometry_states.extend(generate_shallower_or_equal_depths(seed_candidate))
            geometry_states.extend(generate_slightly_deeper_depths(seed_candidate))
        elif goal == "less_longitudinal_reinforcement":
            geometry_states.extend(generate_same_or_larger_geometry_options(seed_candidate))
        else:
            geometry_states.extend(_generate_balanced_geometry_options(seed_candidate))

    deduped_states: dict[tuple, dict] = {}
    for candidate_state in geometry_states:
        deduped_states[_make_auto_design_candidate_key(candidate_state)] = candidate_state
    candidates: list[dict] = []
    for candidate_state in list(deduped_states.values())[:AUTO_DESIGN_MAX_STAGE_CANDIDATES]:
        candidate = _evaluate_candidate_fast(
            candidate_state,
            seed_state=seed_candidate["state"],
            context=context,
            eval_cache=eval_cache,
            metrics=metrics,
            source="geometry_recommendation",
            label=f"{int(_design_width_value(candidate_state))} x {int(_float_from_state(candidate_state, 'D', 0.0))} mm",
            action_type="apply_geometry_recommendation",
        )
        if candidate is None or _updates_match_state(state, candidate.get("updates", {})):
            continue
        candidates.append(candidate)
    best = _keep_top_candidates(candidates, mode_config, limit=1)
    best = best[0] if best else None
    if not best or _updates_match_state(state, best.get("updates", {})):
        return None
    width_key, width_label, _ = _resolve_geometry_width_context(state)
    return {
        "updates": dict(best.get("updates") or {}),
        "width_key": width_key,
        "width_label": width_label,
        "width": float(best.get("width", 0.0) or 0.0),
        "depth": float(best.get("depth", 0.0) or 0.0),
        "bending_util": float(best.get("overview", {}).get("utils", {}).get("bending", 0.0) or 0.0),
        "shear_util": float(best.get("overview", {}).get("utils", {}).get("shear", 0.0) or 0.0),
        "web_util": float((_evaluate_shear_with_state(best.get("state") or state) or {}).get("web_util", 0.0) or 0.0),
        "required_ast": float(best.get("required_ast", 0.0) or 0.0),
        "score": float(best.get("score", 0.0) or 0.0),
    }


def _sanitize_shared_update_bundle(
    updates: dict | None,
    *,
    source: str,
) -> tuple[dict, dict]:
    """
    Filter an updates dict down to keys that are valid shared-state writes.

    Returns:
      (
        sanitized_updates,
        meta = {
          "source": ...,
          "input_key_count": ...,
          "sanitized_key_count": ...,
          "dropped_nonshared_keys": [...],
          "dropped_private_keys": [...],
        }
      )
    """
    raw = dict(updates or {})
    sanitized: dict[str, object] = {}
    dropped_nonshared: list[str] = []
    dropped_private: list[str] = []

    for key, value in raw.items():
        k = str(key or "")
        if not k:
            continue
        if k.startswith("_"):
            dropped_private.append(k)
            continue
        if k not in SHARED_DEFAULTS:
            dropped_nonshared.append(k)
            continue
        sanitized[k] = value

    meta = {
        "source": str(source or ""),
        "input_key_count": len(raw),
        "sanitized_key_count": len(sanitized),
        "dropped_nonshared_keys": sorted(set(dropped_nonshared)),
        "dropped_private_keys": sorted(set(dropped_private)),
    }
    return sanitized, meta


def _one_click_committable_candidate_eval(
    base_state: dict,
    updates: dict | None,
    *,
    source: str,
    label: str | None,
    action_type: str | None,
) -> tuple[dict | None, dict, dict]:
    """Evaluate a one-click winner through the exact shared-state commit surface."""
    sanitized_updates, sanitize_meta = _sanitize_shared_update_bundle(
        updates,
        source=source,
    )
    if not sanitized_updates:
        return None, sanitized_updates, sanitize_meta
    committed_state = _guidance_state_snapshot(dict(base_state or {}))
    committed_state.update(dict(sanitized_updates))
    try:
        committed_state.update(
            _normalise_invalid_shear_state_updates(
                committed_state,
                {},
                source=f"{source}:preview_normalise",
            )
        )
    except Exception:
        pass
    try:
        convenience_updates = dict(_canonical_convenience_fields_from_state(committed_state) or {})
        convenience_meta = dict(convenience_updates.pop(_CANONICAL_CONVENIENCE_META_KEY, {}) or {})
        if bool(convenience_meta.get("canonical_convenience_resync_valid")):
            committed_state.update(convenience_updates)
    except Exception:
        pass
    try:
        eval_obj = _evaluate_auto_design_candidate(
            committed_state,
            updates={},
            source=source,
            label=label,
            action_type=action_type,
        )
    except Exception:
        eval_obj = None
    return eval_obj, sanitized_updates, sanitize_meta


def _set_shared_updates(updates: dict, *, source: str) -> None:
    sanitized_updates, sanitize_meta = _sanitize_shared_update_bundle(
        updates,
        source=source,
    )

    st.session_state["_last_shared_update_sanitize_meta"] = dict(sanitize_meta)
    st.session_state["_nonshared_update_drop_audit"] = {
        "source": sanitize_meta["source"],
        "dropped_nonshared_keys": list(sanitize_meta.get("dropped_nonshared_keys") or []),
        "dropped_private_keys": list(sanitize_meta.get("dropped_private_keys") or []),
        "raw_key_count": sanitize_meta.get("input_key_count"),
        "sanitized_key_count": sanitize_meta.get("sanitized_key_count"),
    }

    try:
        _append_design_guide_trace(
            "shared_update_sanitize",
            dict(sanitize_meta),
            source=str(source or ""),
        )
    except Exception:
        pass

    if not sanitized_updates:
        return
    for shared_key, value in sanitized_updates.items():
        set_shared(shared_key, value, source=source)
    if any(key in {"lig_d", "lig_legs", "s_lig"} for key in sanitized_updates):
        _normalise_invalid_shear_state_in_shared(source=f"{source}:shear_shared_normalise")
        _refresh_canonical_shear_widgets(source=f"{source}:shear_widget_refresh")
    _apply_canonical_convenience_resync_to_shared(source=f"{source}:canonical_convenience")


def _record_one_click_shear_publish_audit(
    *,
    stage: str,
    source: str,
    candidate_updates: dict | None,
    publish_attempted: bool,
    publish_blocked: bool,
) -> None:
    updates = dict(candidate_updates or {})
    relevant = {
        key: updates.get(key)
        for key in ("lig_legs", "lig_d", "s_lig")
        if key in updates
    }
    if not relevant:
        return
    entry = {
        "stage": str(stage or ""),
        "source": str(source or ""),
        "candidate_shear": dict(relevant),
        "publish_attempted": bool(publish_attempted),
        "publish_blocked": bool(publish_blocked),
        "shared_shear_snapshot": {
            "s_lig": st.session_state.get("s_lig"),
            "lig_d": st.session_state.get("lig_d"),
            "lig_legs": st.session_state.get("lig_legs"),
        },
    }
    audit = list(st.session_state.get("_one_click_shear_publish_audit") or [])
    audit.append(entry)
    if len(audit) > 20:
        audit = audit[-20:]
    st.session_state["_one_click_shear_publish_audit"] = audit


def _pop_inputs_widget_keys_for_shared_updates(updates: dict) -> set[str]:
    """
    After canonical ``set_shared`` writes, remove stale ``inputs_*`` widget mirrors and hydration
    map entries so the next ``hydrate_active_page_widgets_from_shared`` / ``safe_hydrate`` pass
    re-seeds widgets from shared (same idea as ``_commit_auto_design_candidate_to_shared``).
    """
    if not updates:
        return set()
    alias_widget_keys: dict[str, list[str]] = {
        "db_bot_1": ["inputs_db_bot_1", "inputs_nb_or_s_bot_1"],
        "db_bot_2": ["inputs_db_bot_2", "inputs_nb_or_s_bot_2"],
        "db_top_1": ["inputs_db_top_1", "inputs_nb_or_s_top_1"],
        "db_top_2": ["inputs_db_top_2", "inputs_nb_or_s_top_2"],
        "bot1_layout_mode": ["inputs_bot1_layout_mode"],
        "bot1_count": ["inputs_bot1_count"],
        "bot1_spacing": ["inputs_bot1_spacing"],
        "bot2_layout_mode": ["inputs_bot2_layout_mode"],
        "bot2_count": ["inputs_bot2_count"],
        "bot2_spacing": ["inputs_bot2_spacing"],
        "top1_layout_mode": ["inputs_top1_layout_mode"],
        "top1_count": ["inputs_top1_count"],
        "top1_spacing": ["inputs_top1_spacing"],
        "top2_layout_mode": ["inputs_top2_layout_mode"],
        "top2_count": ["inputs_top2_count"],
        "top2_spacing": ["inputs_top2_spacing"],
    }
    shear_widget_trio = {"inputs_s_lig", "inputs_lig_d", "inputs_lig_legs"}
    cleared: set[str] = set()
    hydrated_map = st.session_state.get("_hydrated_from_shared_map")
    clear_shear_trio = any(key in {"s_lig", "lig_d", "lig_legs"} for key in list(updates.keys()))
    for key in list(updates.keys()):
        widget_keys_to_clear = [f"inputs_{key}"]
        widget_keys_to_clear.extend(alias_widget_keys.get(key, []))
        if clear_shear_trio:
            widget_keys_to_clear.extend(sorted(shear_widget_trio))
        if key.startswith(("bot_row_", "top_row_")):
            widget_keys_to_clear.append(f"inputs_{key}")
        for widget_key in widget_keys_to_clear:
            st.session_state.pop(widget_key, None)
            st.session_state.pop(f"_cached_{widget_key}", None)
            cleared.add(widget_key)
    if isinstance(hydrated_map, dict):
        for key in updates:
            hydrated_map.pop(f"inputs_{key}", None)
            for widget_key in alias_widget_keys.get(key, []):
                hydrated_map.pop(widget_key, None)
        for widget_key in cleared:
            hydrated_map.pop(widget_key, None)
    for key in list(updates.keys()):
        st.session_state.pop(f"_cached_inputs_{key}", None)
    return cleared


def _one_click_post_commit_audit_subset(intended: dict) -> dict:
    """
    Return the authoritative subset of final_updates that should be compared
    exactly against fresh shared state after commit.

    Purpose:
    - compare only raw committed input truth
    - ignore derived / resolved / rebuilt / diagnostic keys
    """
    if not isinstance(intended, dict):
        return {
            "audited_updates": {},
            "ignored_keys": [],
            "has_row_model_updates": False,
            "ignored_row_model_legacy_mirror_keys": [],
        }

    DERIVED_OR_REBUILT_KEYS = {
        "d",
        "do",
        "Ast_bot",
        "Ast_top",
        "nb_bot",
        "nb_top",
        "db_bot",
        "db_top",
        "bot_rows_resolved",
        "top_rows_resolved",
        "bot_bar_coords",
        "top_bar_coords",
        "resolved_longitudinal_bars",
        "resolved_longitudinal_warnings",
        "Ast_top_web",
        "Ast_top_flange",
        "Ast_bottom_web",
        "Ast_bottom_flange",
        "total_bot_bars",
        "total_top_bars",
        "A_g",
        "ybar_top_g",
        "Ixx_g",
        "Ztop_g",
        "Zbot_g",
        "b_web",
        "b_crack",
        "A_ct_default",
        "Ec",
        "Eceff",
        "defl_bw",
        "canonical_pack_built",
        "canonical_pack_valid",
        "canonical_pack_source",
        "canonical_pack_error",
        "canonical_pack_error_stage",
        "longitudinal_reo_truth_source",
    }
    ROW_MODEL_LEGACY_MIRROR_KEYS = {
        "bot1_count",
        "bot2_count",
        "top1_count",
        "top2_count",
        "nb_bot",
        "nb_top",
        "db_bot_1",
        "db_bot_2",
        "db_top_1",
        "db_top_2",
        "db_bot",
        "db_top",
        "bot_entry",
        "top_entry",
        "s_bot",
        "s_top",
        "total_bot_bars",
        "total_top_bars",
        "Ast_bot",
        "Ast_top",
    }
    row_model_prefixes = (
        "bot_row_",
        "top_row_",
    )
    has_row_model_updates = any(str(k).startswith(row_model_prefixes) for k in intended.keys())

    audited: dict[str, object] = {}
    ignored: list[str] = []

    for key, value in intended.items():
        k = str(key or "")
        if not k:
            continue
        if k.startswith("_"):
            ignored.append(k)
            continue
        if k not in SHARED_DEFAULTS:
            ignored.append(k)
            continue
        if k in DERIVED_OR_REBUILT_KEYS:
            ignored.append(k)
            continue
        if has_row_model_updates and k in ROW_MODEL_LEGACY_MIRROR_KEYS:
            ignored.append(k)
            continue
        audited[k] = value

    ignored_row_model_legacy_mirror_keys = sorted(
        [k for k in ignored if k in ROW_MODEL_LEGACY_MIRROR_KEYS]
    )
    return {
        "audited_updates": audited,
        "ignored_keys": sorted(set(ignored)),
        "has_row_model_updates": bool(has_row_model_updates),
        "ignored_row_model_legacy_mirror_keys": ignored_row_model_legacy_mirror_keys,
    }

@speed_profiled("post_commit_audit.one_click_post_commit_audit", category="state_mutation")
def _one_click_post_commit_audit(intended: dict) -> dict:
    """Fresh shared snapshot vs intended updates (authoritative subset only), plus live worst util from evaluation."""
    subset_meta = _one_click_post_commit_audit_subset(intended)
    audited_updates = dict(subset_meta.get("audited_updates") or {})
    ignored_keys = list(subset_meta.get("ignored_keys") or [])
    has_row_model_updates = bool(subset_meta.get("has_row_model_updates"))
    ignored_row_model_legacy_mirror_keys = list(subset_meta.get("ignored_row_model_legacy_mirror_keys") or [])
    snap = _shared_state_snapshot()
    subset = {k: snap.get(k) for k in audited_updates.keys()}
    mismatch_keys: list[str] = []
    mismatch_details: dict[str, dict] = {}
    for k, intended_val in audited_updates.items():
        live = snap.get(k)
        mismatch = False
        if isinstance(intended_val, float) or isinstance(live, float):
            try:
                mismatch = abs(float(live) - float(intended_val)) > 1e-9
            except (TypeError, ValueError):
                mismatch = live != intended_val
        else:
            mismatch = live != intended_val
        if mismatch:
            mismatch_keys.append(k)
            mismatch_details[k] = {
                "intended": intended_val,
                "live": live,
            }
    post_worst: float | None = None
    post_statuses: dict | None = None
    post_eval_shared_worst: float | None = None
    post_eval_shared_statuses: dict | None = None
    post_eval_shared_packed_worst: float | None = None
    post_eval_shared_packed_statuses: dict | None = None
    post_eval_summary_worst: float | None = None
    post_eval_summary_statuses: dict | None = None
    post_summary_state_subset: dict | None = None
    try:
        summary_state, _ = _resolved_inputs_summary_state()
        post_summary_state_subset = {
            "b": summary_state.get("b"),
            "D": summary_state.get("D"),
            "bot1_count": summary_state.get("bot1_count"),
            "bot2_count": summary_state.get("bot2_count"),
            "db_bot_1": summary_state.get("db_bot_1"),
            "db_bot_2": summary_state.get("db_bot_2"),
            "lig_d": summary_state.get("lig_d"),
            "lig_legs": summary_state.get("lig_legs"),
            "s_lig": summary_state.get("s_lig"),
            "Ast_bot": summary_state.get("Ast_bot"),
            "d": summary_state.get("d"),
            "Mu_star": summary_state.get("Mu_star"),
            "Vu_star": summary_state.get("Vu_star"),
        }
        overview = _collect_design_overview(dict(summary_state or {}))
        post_worst = float((overview.get("worst_util") or 0.0))
        post_statuses = dict((overview.get("statuses") or {}))
        shared_eval = evaluate_candidate_full(
            _guidance_state_snapshot(snap),
            source="one_click_post_commit_audit_shared_eval",
            label="Post-commit shared eval",
            action_type="one_click",
            updates={},
        )
        if isinstance(shared_eval, dict):
            shared_overview = dict(shared_eval.get("overview") or {})
            post_eval_shared_worst = float(shared_overview.get("worst_util", 0.0) or 0.0)
            post_eval_shared_statuses = dict(shared_overview.get("statuses") or {})
        shared_packed_eval = evaluate_candidate_full(
            _build_canonical_design_state_pack(copy.deepcopy(snap)),
            source="one_click_post_commit_audit_shared_packed_eval",
            label="Post-commit shared packed eval",
            action_type="one_click",
            updates={},
        )
        if isinstance(shared_packed_eval, dict):
            shared_packed_overview = dict(shared_packed_eval.get("overview") or {})
            post_eval_shared_packed_worst = float(shared_packed_overview.get("worst_util", 0.0) or 0.0)
            post_eval_shared_packed_statuses = dict(shared_packed_overview.get("statuses") or {})
        summary_eval = evaluate_candidate_full(
            _guidance_state_snapshot(summary_state),
            source="one_click_post_commit_audit_summary_eval",
            label="Post-commit summary eval",
            action_type="one_click",
            updates={},
        )
        if isinstance(summary_eval, dict):
            summary_overview = dict(summary_eval.get("overview") or {})
            post_eval_summary_worst = float(summary_overview.get("worst_util", 0.0) or 0.0)
            post_eval_summary_statuses = dict(summary_overview.get("statuses") or {})
    except Exception:
        try:
            ev = evaluate_candidate_full(
                _guidance_state_snapshot(snap),
                source="one_click_post_commit_audit",
                label="Post-commit",
                action_type="one_click",
                updates={},
            )
            if isinstance(ev, dict):
                post_worst = float((ev.get("overview") or {}).get("worst_util", 0.0) or 0.0)
                post_statuses = dict((ev.get("overview") or {}).get("statuses") or {})
        except Exception:
            post_worst = None
            post_statuses = None
    return {
        "applied_final_updates": dict(intended),
        "audited_commit_updates": dict(audited_updates),
        "ignored_commit_update_keys": list(ignored_keys),
        "has_row_model_updates": has_row_model_updates,
        "ignored_row_model_legacy_mirror_keys": ignored_row_model_legacy_mirror_keys,
        "post_commit_shared_subset": subset,
        "post_commit_matches_intended_updates": bool(not mismatch_keys),
        "post_commit_mismatch_keys": list(mismatch_keys),
        "post_commit_mismatch_details": dict(mismatch_details),
        "post_commit_live_worst_util": post_worst,
        "post_commit_live_statuses": post_statuses,
        "post_commit_eval_shared_worst_util": post_eval_shared_worst,
        "post_commit_eval_shared_statuses": post_eval_shared_statuses,
        "post_commit_eval_shared_packed_worst_util": post_eval_shared_packed_worst,
        "post_commit_eval_shared_packed_statuses": post_eval_shared_packed_statuses,
        "post_commit_eval_summary_worst_util": post_eval_summary_worst,
        "post_commit_eval_summary_statuses": post_eval_summary_statuses,
        "post_commit_summary_state_subset": post_summary_state_subset,
    }


def _one_click_commit_audit_passes(
    commit_audit: dict | None,
    *,
    partial_progress_commit: bool = False,
    best_effort_cleanup_commit: bool = False,
    pre_commit_worst_util: float | None = None,
    pre_commit_statuses: dict | None = None,
) -> tuple[bool, str]:
    """
    Conservative live gate after one-click writes to shared state.
    Returns (passes, reject_reason_code) for ``_one_click_post_commit_audit`` output.

    When ``partial_progress_commit`` is True (combined-domain underdesign hop that
    deliberately may not clear all FAIL statuses in one batch), require intended updates
    to match and util to improve vs pre-commit instead of util<=1.0 with all PASS.
    """
    if not isinstance(commit_audit, dict):
        return False, "post_commit_missing_validation"
    if not bool(commit_audit.get("post_commit_matches_intended_updates")):
        return False, "post_commit_mismatch"
    post_worst = commit_audit.get("post_commit_live_worst_util")
    if post_worst is None:
        return False, "post_commit_missing_validation"
    try:
        w = float(post_worst)
    except (TypeError, ValueError):
        return False, "post_commit_missing_validation"
    if (partial_progress_commit or best_effort_cleanup_commit) and pre_commit_worst_util is not None:
        try:
            pre_w = float(pre_commit_worst_util)
        except (TypeError, ValueError):
            return False, "post_commit_missing_validation"
        if w > pre_w - 0.01:
            return False, (
                "post_commit_no_util_improvement_best_effort_cleanup"
                if best_effort_cleanup_commit
                else "post_commit_no_util_improvement_partial_path"
            )
    elif w > 1.0 + 1e-9:
        return False, "post_commit_util_exceeds_limit"
    st = commit_audit.get("post_commit_live_statuses")
    if st is None:
        return False, "post_commit_missing_validation"
    if best_effort_cleanup_commit:
        if not isinstance(st, dict):
            return False, "post_commit_missing_validation"
        try:
            pre_fail_count = sum(
                1
                for v in dict(pre_commit_statuses or {}).values()
                if str(v).strip() == "FAIL" or v == BEAM_STATUS_FAIL
            )
            post_fail_count = sum(
                1
                for v in dict(st or {}).values()
                if str(v).strip() == "FAIL" or v == BEAM_STATUS_FAIL
            )
        except Exception:
            return False, "post_commit_missing_validation"
        if post_fail_count >= pre_fail_count:
            return False, "post_commit_no_fail_count_improvement_best_effort_cleanup"
        return True, ""
    if isinstance(st, dict) and not partial_progress_commit:
        for v in st.values():
            if str(v).strip() == "FAIL" or v == BEAM_STATUS_FAIL:
                return False, "post_commit_fail_status"
    return True, ""


def _restore_shared_state_snapshot(snapshot: dict, *, source: str) -> None:
    """Restore full shared beam state from a prior ``_shared_state_snapshot()`` (no partial merge)."""
    snap = copy.deepcopy(snapshot)
    for key, default in SHARED_DEFAULTS.items():
        set_shared(key, snap.get(key, default), source=source)
    _normalise_invalid_shear_state_in_shared(source=f"{source}:shear_shared_normalise")
    _refresh_canonical_shear_widgets(source=f"{source}:shear_widget_refresh")
    _apply_canonical_convenience_resync_to_shared(source=f"{source}:canonical_convenience")


def _combined_shear_seed_candidates(
    candidates: list[dict],
    *,
    seed_candidate: dict,
    base_state: dict,
    severity_band: str,
    seed_shear_util: float | None,
    limit: int = 8,
) -> list[dict]:
    if not candidates:
        return []
    ranked = sorted(
        candidates,
        key=lambda item: _shear_recommendation_rank_key(
            item,
            base_state=base_state,
            severity_band=severity_band,
            seed_shear_util=seed_shear_util,
        ),
    )
    selected: dict[tuple, dict] = {}
    for candidate in ranked:
        family = _shear_family_label(
            str(candidate.get("shear_candidate_type") or _shear_candidate_type(base_state, dict(candidate.get("state") or {}))),
            candidate,
            seed_candidate=seed_candidate,
        )
        if family not in selected:
            selected[family] = candidate
    ordered: list[dict] = []
    seen: set[tuple] = set()
    for candidate in list(selected.values()) + ranked[: max(2, limit // 2)]:
        candidate_key = _make_auto_design_candidate_key(dict(candidate.get("state") or {}))
        if candidate_key in seen:
            continue
        seen.add(candidate_key)
        ordered.append(candidate)
        if len(ordered) >= limit:
            break
    return ordered


def _commit_auto_design_candidate_to_shared(candidate: dict) -> dict:
    print(
        "DG ALT APPLY ENTRY\n"
        "function=_commit_auto_design_candidate_to_shared\n",
        file=sys.stderr,
        end="",
        flush=True,
    )
    if not candidate:
        return {}

    candidate_state = dict(candidate.get("state") or {})
    if not candidate_state:
        return {}
    pre_commit_state = _shared_state_snapshot()

    tracked_keys = [
        "b", "bw", "D", "tw", "bf", "tf", "bf_bot", "tf_bot",
        "cover_top", "cover_bot", "cover_side",
        "rowgap_top", "rowgap_bot",
        "lig_d", "lig_legs", "s_lig",
        "n_ducts", "duct_dia",
        "k_d_option", "k_v_method",
        "bot_row_count", "top_row_count",
        "bot1_layout_mode", "bot1_count", "bot1_spacing", "db_bot_1",
        "bot2_layout_mode", "bot2_count", "bot2_spacing", "db_bot_2",
        "top1_layout_mode", "top1_count", "top1_spacing", "db_top_1",
        "top2_layout_mode", "top2_count", "top2_spacing", "db_top_2",
        "bot_row_1_mode", "bot_row_1_bars", "bot_row_1_spacing", "bot_row_1_dia",
        "bot_row_2_mode", "bot_row_2_bars", "bot_row_2_spacing", "bot_row_2_dia",
        "bot_row_3_mode", "bot_row_3_bars", "bot_row_3_spacing", "bot_row_3_dia",
        "bot_row_4_mode", "bot_row_4_bars", "bot_row_4_spacing", "bot_row_4_dia",
        "top_row_1_mode", "top_row_1_bars", "top_row_1_spacing", "top_row_1_dia",
        "top_row_2_mode", "top_row_2_bars", "top_row_2_spacing", "top_row_2_dia",
        "top_row_3_mode", "top_row_3_bars", "top_row_3_spacing", "top_row_3_dia",
        "top_row_4_mode", "top_row_4_bars", "top_row_4_spacing", "top_row_4_dia",
    ]

    updates: dict[str, float | int | str | bool | None] = {}
    for key in tracked_keys:
        if key in candidate_state:
            updates[key] = candidate_state.get(key)
    updates = _normalise_invalid_shear_state_updates(
        _shared_state_snapshot(),
        updates,
        source="auto_design_commit",
    )

    _set_shared_updates(updates, source="auto_design_commit")

    hydrated_map = st.session_state.get("_hydrated_from_shared_map")
    cleared_widget_keys: set[str] = set()

    alias_widget_keys: dict[str, list[str]] = {
        "db_bot_1": ["inputs_db_bot_1", "inputs_nb_or_s_bot_1"],
        "db_bot_2": ["inputs_db_bot_2", "inputs_nb_or_s_bot_2"],
        "db_top_1": ["inputs_db_top_1", "inputs_nb_or_s_top_1"],
        "db_top_2": ["inputs_db_top_2", "inputs_nb_or_s_top_2"],
        "bot1_layout_mode": ["inputs_bot1_layout_mode"],
        "bot1_count": ["inputs_bot1_count"],
        "bot1_spacing": ["inputs_bot1_spacing"],
        "bot2_layout_mode": ["inputs_bot2_layout_mode"],
        "bot2_count": ["inputs_bot2_count"],
        "bot2_spacing": ["inputs_bot2_spacing"],
        "top1_layout_mode": ["inputs_top1_layout_mode"],
        "top1_count": ["inputs_top1_count"],
        "top1_spacing": ["inputs_top1_spacing"],
        "top2_layout_mode": ["inputs_top2_layout_mode"],
        "top2_count": ["inputs_top2_count"],
        "top2_spacing": ["inputs_top2_spacing"],
    }

    for key in list(updates.keys()):
        widget_keys_to_clear = [f"inputs_{key}"]
        widget_keys_to_clear.extend(alias_widget_keys.get(key, []))
        if key.startswith(("bot_row_", "top_row_")):
            widget_keys_to_clear.append(f"inputs_{key}")
        for widget_key in widget_keys_to_clear:
            st.session_state.pop(widget_key, None)
            st.session_state.pop(f"_cached_{widget_key}", None)
            cleared_widget_keys.add(widget_key)

    if isinstance(hydrated_map, dict):
        for key in updates:
            hydrated_map.pop(f"inputs_{key}", None)
            for widget_key in alias_widget_keys.get(key, []):
                hydrated_map.pop(widget_key, None)
        for widget_key in cleared_widget_keys:
            hydrated_map.pop(widget_key, None)

    for key in list(updates.keys()):
        st.session_state.pop(f"_cached_inputs_{key}", None)

    invalidated_recommendation_cache_keys = _invalidate_design_guide_caches(
        reason="auto_design_commit",
        updated_keys=list(updates.keys()),
        )
    _agent_debug_log(
        "Cleared row widget keys after auto-design commit",
        {
            "updated_keys": sorted(list(updates.keys())),
            "cleared_widget_keys": sorted(cleared_widget_keys),
            "remaining_inputs_bot_row_1_dia": st.session_state.get("inputs_bot_row_1_dia"),
            "shared_bot_row_1_dia": st.session_state.get("bot_row_1_dia"),
            "remaining_inputs_db_bot_1": st.session_state.get("inputs_db_bot_1"),
            "shared_db_bot_1": st.session_state.get("db_bot_1"),
        },
        location="inputs_page.py:_commit_auto_design_candidate_to_shared",
        hypothesis_id="H121",
    )
    _apply_canonical_convenience_resync_to_shared(source="auto_design_commit:canonical_convenience")
    publish_payload = finalize_auto_design_publish(
        updated_keys=sorted(list(updates.keys())),
        source="auto_design_commit",
        focus_section="shear" if any(k in {"lig_d", "lig_legs", "s_lig"} for k in updates.keys()) else None,
        set_run_design_clicked=True,
    )
    st.session_state["_commit_auto_design_candidate_to_shared_debug"] = {
        "updated_keys": sorted(list(updates.keys())),
        "invalidated_recommendation_cache_keys": invalidated_recommendation_cache_keys,
        "publish_payload": dict(publish_payload),
    }
    return updates


def _queue_inputs_refresh(source: str, keys: list[str], *, focus_section: str | None = None) -> None:
    """
    Schedule one forced Inputs widget reconciliation on the next render_inputs (via pop + hydrate).
    Clears _force_inputs_widget_reseed_once: pending apply-refresh subsumes the same recovery intent
    so router + one forced pass do not compete with a separate reseed flag.
    """
    try:
        import session_state_final_log as _ssl

        _ssl.append_session_state_final_log(
            "queue_inputs_refresh",
            {
                "source": source,
                "keys": list(keys)[:48],
                "had_reseed_before_pop": bool(st.session_state.get("_force_inputs_widget_reseed_once")),
            },
        )
        _ssl.ssl_increment("queue_inputs_refresh_count", 1)
    except Exception:
        pass
    st.session_state.pop("_force_inputs_widget_reseed_once", None)
    next_focus_map = {
        "fast_mode:geometry_recommendation": "model",
        "fast_mode:bottom_recommendation": "shear",
    }
    next_focus_section = focus_section or next_focus_map.get(source)
    if next_focus_section:
        st.session_state["_fast_mode_focus_section"] = next_focus_section
    if str(source).startswith("guidance:"):
        st.session_state["_design_guide_banner_generic_only"] = True
    st.session_state["_pending_inputs_apply_refresh"] = {
        "source": source,
        "keys": keys,
    }
    _inputs_hydration_trace_log("queue_inputs_refresh", source=source, keys=list(keys)[:24])


def _recommendation_fingerprint_state(state: dict) -> dict:
    fingerprint_state = {
        key: state.get(key, default)
        for key, default in SHARED_DEFAULTS.items()
    }
    fingerprint_state["_resolved_design_actions"] = _resolve_design_actions_from_state(state)
    return fingerprint_state


def _recommendation_cache_fingerprint(state: dict) -> str:
    fingerprint_state = _recommendation_fingerprint_state(state)
    try:
        return json.dumps(fingerprint_state, sort_keys=True, default=str)
    except Exception:
        return str(sorted((str(key), str(value)) for key, value in fingerprint_state.items()))


def _cached_recommendation(cache_name: str, state: dict):
    cache_key = f"_recommendation_cache_{cache_name}"
    cache_entry = st.session_state.get(cache_key)
    fingerprint = _recommendation_cache_fingerprint(state)
    if isinstance(cache_entry, dict) and cache_entry.get("fingerprint") == fingerprint:
        return cache_entry.get("recommendation")
    return None


def _store_cached_recommendation(cache_name: str, state: dict, recommendation) -> None:
    cache_key = f"_recommendation_cache_{cache_name}"
    st.session_state[cache_key] = {
        "fingerprint": _recommendation_cache_fingerprint(state),
        "recommendation": recommendation,
    }


def _invalidate_design_guide_caches(
    *,
    reason: str,
    updated_keys: list[str] | None = None,
    preserve_apply_banner: bool = False,
) -> list[str]:
    removed: list[str] = []
    _clear_design_guide_transient_ui_state(
        clear_history=False,
        preserve_apply_banner=preserve_apply_banner,
    )
    for session_key in list(st.session_state.keys()):
        if str(session_key).startswith("_recommendation_cache_"):
            removed.append(str(session_key))
            st.session_state.pop(session_key, None)
    if bool(st.session_state.get("_dev_mode")):
        _agent_debug_log(
            "Invalidated design guide caches",
            {
                "reason": reason,
                "updated_keys": list(updated_keys or []),
                "removed_cache_keys": removed,
            },
            location="inputs_page.py:_invalidate_design_guide_caches",
            hypothesis_id="H301",
        )
    return removed


def _debug_log_design_guide_consistency(*, source: str, applied_candidate: dict | None = None) -> None:
    if not bool(st.session_state.get("_dev_mode")):
        return
    if (
        str(source or "").strip() == "guidance:apply_resolved_candidate"
        and isinstance(applied_candidate, dict)
        and isinstance(applied_candidate.get("overview"), dict)
    ):
        fresh_state = dict(applied_candidate.get("state") or {})
        fresh_overview = dict(applied_candidate.get("overview") or {})
        guide_debug: dict = {"overview": dict(fresh_overview), "guidance_branch": "apply_resolved_candidate"}
        next_mode_recommendation: dict = {}
    else:
        fresh_state, _ = _resolved_inputs_summary_state()
        design_context = _build_design_actions_context(fresh_state)
        fresh_overview = _collect_design_overview(fresh_state, context=design_context)
        guidance_payload = _compute_design_guidance_items(
            fresh_state,
            guidance_debug_verbose=True,
            debug_enabled=False,
        )
        guide_debug = dict(guidance_payload.get("debug_trace") or {})
        guide_debug.setdefault("overview", fresh_overview)
        efficiency_state = dict(guide_debug.get("efficiency_tightening_state") or {})
        next_mode_recommendation = dict(efficiency_state.get("mode_tightening") or {})
    current_summary = _overview_debug_summary(fresh_state, fresh_overview)
    applied_summary = _candidate_debug_summary(applied_candidate)
    warning = False
    if applied_summary is not None and applied_summary.get("bottom_reo_label") != current_summary.get("bottom_reo_label"):
        warning = True
    if next_mode_recommendation and str(next_mode_recommendation.get("label") or "") == str(current_summary.get("bottom_reo_label") or ""):
        warning = True
    _agent_debug_log(
        "Post-commit design guide consistency check",
        {
            "source": source,
            "warning": warning,
            "committed_bottom_reo_label": current_summary.get("bottom_reo_label"),
            "overview_bottom_reo_label": current_summary.get("bottom_reo_label"),
            "applied_candidate_label": None if applied_summary is None else applied_summary.get("bottom_reo_label"),
            "current_utilisation_shown": current_summary.get("worst_util"),
            "actual_overview_utilisation": current_summary.get("worst_util"),
            "next_recommendation_label": next_mode_recommendation.get("label"),
            "next_recommendation_expected_util": next_mode_recommendation.get("expected_util"),
            "next_recommendation_optimisation_score": next_mode_recommendation.get("optimisation_score"),
            "guidance_branch": guide_debug.get("guidance_branch"),
            "overview_summary": current_summary,
            "applied_summary": applied_summary,
            "next_recommendation_summary": next_mode_recommendation.get("candidate_summary"),
        },
        location="inputs_page.py:_debug_log_design_guide_consistency",
        hypothesis_id="H302",
    )


def _resolve_popover_recommendation(
    *,
    cache_name: str,
    state: dict,
    button_key: str,
    compute_fn,
    empty_message: str,
):
    recommendation = _cached_recommendation(cache_name, state)
    generate_pressed = st.button(
        "Generate current recommendation" if recommendation is None else "Refresh recommendation",
        key=f"{button_key}_generate",
        type="secondary",
        use_container_width=True,
    )
    if generate_pressed:
        recommendation = compute_fn(state)
        _store_cached_recommendation(cache_name, state, recommendation)
    if recommendation is None:
        st.caption(empty_message)
    return recommendation


def _clear_legacy_auto_design_request_flags(
    *,
    clear_invoke: bool = False,
    idle_reason_on_cancel: str = "request_cancelled_by_guidance_commit",
) -> None:
    """
    Legacy string cleanup. One-shot auto-design invoke keys are preserved unless
    ``clear_invoke=True`` (explicit cancellation of a pending one-click request).
    """
    st.session_state.pop("_auto_design_reason", None)
    if not clear_invoke:
        return
    st.session_state.pop(AUTO_DESIGN_AUTO_INVOKE_KEY, None)
    st.session_state.pop(AUTO_DESIGN_REQUEST_TS_KEY, None)
    st.session_state.pop(AUTO_DESIGN_REQUEST_SOURCE_KEY, None)
    st.session_state.pop("auto_design_request_source", None)
    try:
        st.session_state["auto_design_invoke_pending"] = False
        st.session_state["auto_design_invoke_set"] = False
        st.session_state["auto_design_idle_reason"] = str(idle_reason_on_cancel)
        st.session_state["_auto_design_idle_reason"] = str(idle_reason_on_cancel)
    except Exception:
        pass


def _cancel_pending_auto_design_request(
    *,
    idle_reason: str = "request_cancelled_by_guidance_commit",
) -> None:
    """Explicit cancel: drop pending one-click invoke + request metadata and surface reason."""
    _clear_legacy_auto_design_request_flags(clear_invoke=True, idle_reason_on_cancel=idle_reason)


def _sync_auto_design_invoke_pending_field() -> None:
    """Keep ``auto_design_invoke_pending`` aligned with the one-shot invoke session key."""
    try:
        st.session_state["auto_design_invoke_pending"] = bool(st.session_state.get(AUTO_DESIGN_AUTO_INVOKE_KEY, False))
    except Exception:
        pass


_ONE_CLICK_NO_ACTION_STOP_REASON_USER_TEXT: dict[str, str] = {
    "no_actionable_candidates": "All candidates were filtered out; none preserved the governing checks with executable updates.",
    "no_actionable_candidates_after_full_tightening_search": "After the full tightening search, no actionable candidate remained.",
    "non_material_remaining_candidates": "Remaining candidates would not materially improve the design.",
    "no_improving_candidate": "No candidate improved the worst-case objective on this step.",
}


def _one_click_build_user_visible_no_action_fields(stop_reason: str, dbg: dict | None) -> dict[str, str | None]:
    """
    Compact, user-facing copy when one-click ran but returned ``no_action``.
    Does not alter solver behaviour — packaging only.
    """
    dbg = dict(dbg or {})
    sr = str(stop_reason or "").strip()
    detail = _ONE_CLICK_NO_ACTION_STOP_REASON_USER_TEXT.get(sr)
    if detail is None:
        if sr == "state_incoherent_after_rebuild":
            detail = "The canonical beam state was incoherent after rebuild, so the one-click pass could not continue."
        elif sr == "no_bars_resolved":
            detail = "Add longitudinal reinforcement before running auto-design."
        elif sr == "evaluate_failed":
            detail = "Initial evaluation failed, so no trial updates could be scored."
        else:
            detail = f"Stop reason: {sr}." if sr else "The solver stopped before applying an update."

    gdom = str(dbg.get("governing_domain") or "").strip().lower()
    shear = gdom == "shear"

    if sr == "state_incoherent_after_rebuild":
        headline = "One-click did not complete."
    elif shear:
        headline = "One-click ran, but the current shear candidate set was exhausted by practicality/code filters."
    else:
        headline = "One-click auto design ran, but no practical candidate was found."

    user_visible_no_action_reason = f"{headline} — {detail}".strip()

    parts: list[str] = []
    counter_keys = (
        ("rejected_as_impractical_shear_layout", "rejected_as_impractical_shear_layout"),
        ("rejected_as_spacing_too_weak", "rejected_as_spacing_too_weak"),
        ("rejected_as_web_crushing_marginal", "rejected_as_web_crushing_marginal"),
        ("rejected_as_non_governing_cleanup", "rejected_as_non_governing_cleanup"),
    )
    for dbg_key, label in counter_keys:
        try:
            n = int(dbg.get(dbg_key) or 0)
        except (TypeError, ValueError):
            n = 0
        if n > 0:
            parts.append(f"{label}: {n}")
    user_visible_rejection_summary = "; ".join(parts) if parts else None

    return {
        "user_visible_no_action_reason": user_visible_no_action_reason,
        "user_visible_rejection_summary": user_visible_rejection_summary,
    }


def _set_one_click_run_feedback(
    *,
    status: str,
    reason: str | None,
    winning_label: str | None = None,
    winning_action_type: str | None = None,
    pre_commit_worst_util: float | None = None,
    extra_payload: dict | None = None,
    debug_target: dict | None = None,
) -> None:
    payload = {
        "status": str(status or "").strip() or "blocked",
        "reason": str(reason or "").strip() or "unknown",
        "winning_label": str(winning_label or "").strip() or None,
        "winning_action_type": str(winning_action_type or "").strip() or None,
        "pre_commit_worst_util": pre_commit_worst_util,
    }
    if isinstance(extra_payload, dict):
        payload.update(dict(extra_payload))
    st.session_state["_one_click_run_feedback"] = payload
    if isinstance(debug_target, dict):
        debug_target["one_click_run_feedback_status"] = payload["status"]
        debug_target["one_click_run_feedback_reason"] = payload["reason"]


def _render_auto_design_main_panel_status() -> None:
    """
    Lightweight main-panel copy for idle/deferred/cancel — no debug sidebar required.
    Skips noise when there is nothing to report.
    """
    try:
        ads = str(st.session_state.get("auto_design_status") or "").strip()
        if ads == "running":
            st.caption("Auto-design is running on the current inputs.")
            return
        if ads == "rejected":
            sr0 = st.session_state.get("_solver_result")
            if isinstance(sr0, dict):
                uvc = sr0.get("user_visible_commit_rejection")
                if uvc:
                    st.warning(str(uvc))
                    return
    except Exception:
        pass

    idle = str(
        st.session_state.get("auto_design_idle_reason")
        or st.session_state.get("_auto_design_idle_reason")
        or "",
    ).strip()
    if not idle or idle == "idle_not_invoked":
        return
    _sync_auto_design_invoke_pending_field()
    src = str(
        st.session_state.get("auto_design_request_source")
        or st.session_state.get(AUTO_DESIGN_REQUEST_SOURCE_KEY)
        or "",
    ).strip()
    labels = {
        "idle_should_run_false": "Auto-design did not run: waiting for invoke.",
        "deferred_compute_in_progress": "Auto-design deferred: compute in progress.",
        "deferred_solver_running": "Auto-design deferred: solver already running.",
        "request_cancelled_by_guidance_commit": "Auto-design request was cancelled.",
    }
    base = labels.get(idle, f"Auto-design did not run ({idle}).")
    if src and idle not in ("request_cancelled_by_guidance_commit",):
        base = f"{base} (request: {src})"
    st.caption(base)


