                        web_sort_util=web_sort_util,
                        practical_spacing_penalty=practical_spacing_penalty,
                        congestion_penalty=congestion_penalty,
                        goal_bias=goal_bias,
                        new_distance=new_d,
                        wrong_dir_penalty=wrong_dir_penalty,
                        reduction_bias=reduction_bias,
