def _deflection_guidance_item(state: dict, pack: dict) -> dict | None:
    if not _has_meaningful_deflection_sls_demand(state):
        return None
    rows = pack.get("rows") or []
    util = _parse_util_value(pack.get("summary_util_total"))
    status, _ = _overall_status_from_rows(rows)
    bucket = _guidance_bucket(status, util)
    if bucket not in ("fail", "warn"):
        return None
    base = _evaluate_deflection_with_state(state)
    if not base or base.get("util") is None:
        return None
    base_u = float(base["util"])
    picked = _pick_deflection_ladder_first_improvement(state, base_util=base_u)
    span_note = " Advisory only: a shorter effective span L_eff also reduces deflection (not applied automatically)."
    is_fail = bucket == "fail"
    title = "Deflection is high" if is_fail else "Deflection is close to the limit"
    levers = "Key levers: D, b, sustained loads, span (advisory)"
    secondary = "Alternative: review deflection inputs on the Deflection page." + span_note
    if not picked:
        if not is_fail:
            return None
        failed_row = next(
            (row for row in rows if str((row or {}).get("status") or "").strip().upper() == "FAIL"),
            {},
        )
        attempted_updates = {
            "D": "increase section depth trial",
            "b": "increase section width trial",
            "sustained_load": "reduce sustained load advisory trial",
        }
        reason = (
            "No one-click deflection arrangement from the practical depth, width, and sustained-load "
            "trials resolved the deflection limit while preserving bending, shear, crack control, "
            "spacing, ductility, cover, and detailing checks."
        )
        evidence = {
            "candidate_search_exhaustive": True,
            "search_scope": "serviceability_deflection_active_failure_ladder",
            "total_candidates_considered": len(attempted_updates),
            "safe_executor_backed_candidates_count": 0,
            "target_band_candidate_count": 0,
            "active_under_capacity_blocker": True,
            "active_under_capacity_blocker_family": "deflection",
            "active_under_capacity_blocker_reason": reason,
            "outside_target_band_allowed": False,
            "outside_target_band_allowed_reason": reason,
            "outside_target_band_allowed_category": "deflection_would_fail",
            "attempted_candidate_id": "deflection_serviceability_practical_ladder_exhausted",
            "attempted_updates": attempted_updates,
            "failed_check_name": str(failed_row.get("title") or "Deflection limit"),
            "failed_check_status": str(failed_row.get("status") or status or "FAIL"),
            "failed_check_util": util if util is not None else base_u,
            "failed_check_demand": str(
                failed_row.get("calculated")
                or failed_row.get("value")
                or failed_row.get("action")
                or "deflection demand"
            ),
            "failed_check_capacity_or_limit": str(
                failed_row.get("requirement")
                or failed_row.get("limit")
                or "deflection limit"
            ),
            "one_click_target_reaching_candidate_exists": False,
        }
        item = _guidance_item(
            "deflection",
            title,
            "No one-click deflection update is available from this state.",
            secondary,
            f"Why: {reason}",
            levers,
            None,
            None,
            status=status,
            util=util,
        )
        item["guidance_intent"] = "specific_blocker"
        item["active_under_capacity_blocker"] = True
        item["active_under_capacity_blocker_reason"] = reason
        item["candidate_search_evidence"] = dict(evidence)
        item["button_contract"] = {
            "enabled": False,
            "actionable": False,
            "family": "deflection",
            "updates": {},
            "preview_pass": False,
            "blocking_reason": reason,
        }
        return item
    u_after = float(picked.get("util_after", 0.0) or 0.0)
    kind = str(picked.get("kind") or "")
    if kind == "sustained_load":
        reasoning = (
            f"Why: deflection ladder ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â depth and width trials first; then one small sustained-load step ({util:.2f} ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ {u_after:.2f})."
            if util is not None
            else f"Why: sustained-load adjustment ({u_after:.2f})."
        )
        return _guidance_item(
            "deflection",
            title,
            str(picked.get("label") or "Reduce sustained load slightly"),
            secondary,
            reasoning,
            levers,
            "deflection_reduce_sustained_load",
            {"updates": dict(picked.get("updates") or {})},
            status=status,
            util=util,
            guidance_before_after=str(picked.get("before_after") or "") or None,
        )
    reasoning = (
        f"Why: deflection ladder ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â depth, then width if it helps stiffness, before load tweaks ({util:.2f} ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ {u_after:.2f})."
        if util is not None
        else f"Why: geometry step ({u_after:.2f})."
    )
    return _guidance_item(
        "deflection",
        title,
        str(picked.get("label") or "Increase depth"),
        secondary,
        reasoning + span_note,
        levers,
        str(picked.get("action_type") or "increase_depth"),
        dict(picked.get("payload") or {}),
        status=status,
        util=util,
        guidance_before_after=str(picked.get("before_after") or "") or None,
    )


def _one_click_candidate_payload_signature(updates: dict) -> tuple:
    sig: list[tuple[str, object]] = []
    for k in sorted((updates or {}).keys()):
        v = updates.get(k)
        if isinstance(v, float):
            sig.append((k, round(float(v), 6)))
        else:
            sig.append((k, v))
    return tuple(sig)


def _guidance_item_from_selected_candidate(
    candidate: dict,
    *,
    guidance_state: dict,
    overview: dict,
    title: str,
    action_type: str,
    updates: dict,
    action_payload: dict,
    reasoning: str,
    change_lines: list[str] | None = None,
    family_tag: str | None = None,
    subfamilies: list[str] | None = None,
) -> dict:
    item = _guidance_item(
        str(_governing_focus_from_overview(overview) or "bending"),
        title,
        title,
        None,
        reasoning,
        "Key levers: geometry and reinforcement updates selected by one-click convergence ranking",
        str(action_type),
        dict(action_payload),
        status=str((overview.get("statuses") or {}).get("bending") or "FAIL"),
        util=overview.get("worst_util"),
        guidance_change_lines=(change_lines or None),
    )
    resolved_updates = dict(updates or {})
    resolved_candidate = dict(candidate or {})
    resolved_candidate["label"] = str(title)
    resolved_candidate["action_type"] = str(action_type)
    resolved_candidate["updates"] = dict(resolved_updates)
    resolved_candidate["candidate_post_util"] = candidate.get("candidate_post_util")
    resolved_candidate["candidate_reaches_target_band"] = bool(candidate.get("candidate_reaches_target_band"))
    item["resolved_candidate_label"] = str(title)
    item["resolved_candidate_action_type"] = str(action_type)
    item["resolved_candidate_updates"] = resolved_updates
    item["resolved_candidate_family_tag"] = family_tag
    item["resolved_candidate_subfamilies"] = list(subfamilies or [])
    item["resolved_candidate_post_util"] = candidate.get("candidate_post_util")
    item["resolved_candidate_reaches_target_band"] = bool(candidate.get("candidate_reaches_target_band"))
    item["resolved_candidate"] = resolved_candidate
    item["has_resolved_candidate_payload"] = bool(resolved_updates)
    return item


def _candidate_failure_coverage_summary(
    current_state: dict,
    candidate: dict,
) -> dict:
    current_overview = _collect_design_overview(current_state) if isinstance(current_state, dict) else {}
    candidate_overview = dict(candidate.get("overview") or {}) if isinstance(candidate, dict) else {}
    return _repair_candidate_failure_coverage_summary_from_overviews(
        current_overview,
        candidate_overview,
    )


def _requires_full_coverage_for_primary_one_click(overview: dict) -> tuple[bool, list[str]]:
    return _repair_requires_full_coverage_for_primary_one_click(overview)


def _candidate_is_valid_primary_one_click(
    candidate: dict | None,
    overview: dict,
) -> tuple[bool, dict]:
    return _repair_candidate_is_valid_primary_one_click(
        candidate,
        overview,
        fail_status_value=BEAM_STATUS_FAIL,
    )


def _guidance_item_from_resolved_candidate(
    candidate: dict,
    *,
    state: dict,
    overview: dict,
    title: str | None = None,
    reasoning: str | None = None,
    status: str = "FAIL",
    primary_action: str = "Apply recommendation",
) -> dict:
    if not isinstance(candidate, dict):
        return {}
    updates = dict(candidate.get("updates") or {})
    if not updates:
        return {}

    raw_label = str(
        candidate.get("resolved_candidate_label_raw")
        or candidate.get("label")
        or title
        or "Apply recommendation",
    ).strip()
    if bool(candidate.get("title_locked_from_final_winner")):
        label = str(
            candidate.get("canonical_winner_label")
            or raw_label
            or candidate.get("label")
            or "",
        ).strip() or raw_label
    else:
        label = _resolve_canonical_guidance_title_from_candidate(
            candidate,
            updates,
            state=state,
            spec_label=None,
            fallback_title=str(title or raw_label or ""),
        )
    family_tag = (
        candidate.get("recommendation_family_tag")
        or candidate.get("family_tag")
        or candidate.get("family")
        or "resolved_candidate"
    )
    subfamilies = list(candidate.get("subfamilies") or []) if isinstance(candidate.get("subfamilies"), list) else []
    alternatives_text = str(
        candidate.get("guidance_alternatives_text_compact")
        or _guidance_default_alternatives_text(state, updates, subfamilies)
        or "",
    ).strip()

    change_lines = list(
        candidate.get("guidance_change_lines")
        or candidate.get("recommendation_change_lines")
        or _guidance_change_lines_for_updates(state, updates)
        or []
    )

    candidate_post_util = candidate.get("worst_util")
    try:
        candidate_post_util = float(candidate_post_util) if candidate_post_util is not None else None
    except Exception:
        candidate_post_util = None

    original_candidate_action_type = str(
        candidate.get("action_type")
        or candidate.get("resolved_candidate_action_type")
        or "apply_compound_guidance"
    )

    failure_coverage = _candidate_failure_coverage_summary(state, candidate)
    candidate_search_evidence = dict(candidate.get("candidate_search_evidence") or {})
    guidance_change_summary_compact = _guidance_compact_change_text(change_lines)
    guidance_expected_util_text = _guidance_expected_util_text(candidate_post_util)
    guidance_why_text_compact = _guidance_compact_why_text(
        {
            "reasoning": reasoning or str(candidate.get("reasoning") or ""),
            "action_payload": {},
        },
    )
    compact_text_pack = _build_design_guide_controller_resolved_candidate_guidance_item_compact_text_pack(
        alternatives_text=alternatives_text,
        guidance_change_summary_compact=guidance_change_summary_compact,
        guidance_expected_util_text=guidance_expected_util_text,
        guidance_why_text_compact=guidance_why_text_compact,
    )
    alternatives_text = str(compact_text_pack.get("guidance_alternatives_text_compact") or "")
    guidance_change_summary_compact = str(compact_text_pack.get("guidance_change_summary_compact") or "")
    guidance_expected_util_text = str(compact_text_pack.get("guidance_expected_util_text") or "")
    guidance_why_text_compact = str(compact_text_pack.get("guidance_why_text_compact") or "")
    input_pack = _build_design_guide_controller_resolved_candidate_guidance_item_input_pack(
        candidate=dict(candidate or {}),
        updates=dict(updates),
        label=label,
        original_candidate_action_type=original_candidate_action_type,
        family_tag=family_tag,
        subfamilies=list(subfamilies),
        candidate_post_util=candidate_post_util,
        change_lines=list(change_lines),
        guidance_change_summary_compact=guidance_change_summary_compact,
        guidance_expected_util_text=guidance_expected_util_text,
        guidance_why_text_compact=guidance_why_text_compact,
        alternatives_text=alternatives_text,
    )
    action_payload_preview = dict(input_pack.get("action_payload_preview") or {})
    before_after_request_pack = _build_design_guide_controller_resolved_candidate_guidance_item_before_after_request_pack(
        action_payload_preview=action_payload_preview,
        change_lines=change_lines,
    )
    guidance_before_after = _guidance_before_after_text(
        dict(before_after_request_pack.get("before_after_item") or {}),
        state,
    )
    return _build_design_guide_controller_resolved_candidate_guidance_item(
        candidate=dict(candidate or {}),
        updates=updates,
        label=label,
        raw_label=raw_label,
        family_tag=family_tag,
        subfamilies=subfamilies,
        alternatives_text=alternatives_text,
        change_lines=change_lines,
        candidate_post_util=candidate_post_util,
        original_candidate_action_type=original_candidate_action_type,
        primary_action=primary_action,
        reasoning_text=reasoning
        or str(candidate.get("reasoning") or "This option brings the design into the target range in one move."),
        status=status,
        overview_worst_util=overview.get("worst_util"),
        failure_coverage=dict(failure_coverage),
        candidate_search_evidence=candidate_search_evidence,
        guidance_change_summary_compact=guidance_change_summary_compact,
        guidance_expected_util_text=guidance_expected_util_text,
        guidance_why_text_compact=guidance_why_text_compact,
        guidance_before_after=guidance_before_after,
    )


def _get_one_click_band_reaching_candidate(
    guidance_state: dict,
    overview: dict,
    *,
    mode_config: dict,
    primary_hint: dict | None = None,
    debug_extra: dict | None = None,
) -> dict | None:
    if isinstance(debug_extra, dict):
        debug_extra["one_click_critical_candidate_exists"] = False
        debug_extra["one_click_critical_candidate_label"] = None
        debug_extra["one_click_critical_candidate_action_type"] = None
        debug_extra["one_click_critical_candidate_post_util"] = None
        debug_extra["one_click_critical_candidate_reaches_target_band"] = False
        debug_extra["compound_shear_augmented"] = False
        debug_extra["covers_all_current_failures"] = False
        debug_extra["covered_fail_keys"] = []
        debug_extra["remaining_fail_keys"] = []
        debug_extra["one_click_critical_candidate_surfaced"] = False
        debug_extra["one_click_critical_candidate_suppressed_reason"] = "not_checked"
        debug_extra["critical_branch_used_one_click_override"] = False

    seed_candidate = evaluate_candidate_full(
        _guidance_state_snapshot(guidance_state),
        source="one_click_critical_seed",
    )
    if not seed_candidate:
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "seed_eval_failed"
        return None
    overview_in_band = bool(overview.get("all_key_pass")) and _is_in_target_zone_with_eps(
        overview,
        mode_config,
        eps=TARGET_BAND_EPS,
    )
    if overview_in_band:
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "already_in_target_band"
        return None

    option_specs: list[dict] = []

    def _add_option(
        *,
        updates: dict | None,
        action_type: str,
        payload: dict,
        label: str,
        source: str,
        family_tag: str | None = None,
        subfamilies: list[str] | None = None,
    ) -> None:
        u = dict(updates or {})
        if not u or _updates_match_state(guidance_state, u):
            return
        if not _candidate_is_materially_actionable(guidance_state, u):
            return
        option_specs.append(
            {
                "updates": u,
                "action_type": str(action_type),
                "payload": dict(payload),
                "label": str(label or "").strip() or "Apply one-click recommendation",
                "source": str(source),
                "family_tag": family_tag,
                "subfamilies": list(subfamilies or []),
            },
        )

    if isinstance(primary_hint, dict):
        at = str(primary_hint.get("action_type") or "")
        if at:
            hint_payload = dict(primary_hint.get("action_payload") or {})
            hint_updates = _guidance_action_updates(at, hint_payload, state=guidance_state)
            _add_option(
                updates=hint_updates,
                action_type=at,
                payload=hint_payload,
                label=str(primary_hint.get("title_main") or primary_hint.get("primary_action") or at),
                source="primary_hint",
            )

    bottom_rec = _compute_bottom_reo_recommendation(guidance_state)
    if isinstance(bottom_rec, dict):
        bu = dict(bottom_rec.get("updates") or {})
        if bu:
            is_compound = bool(bottom_rec.get("recommendation_compound"))
            rec_title = str(
                bottom_rec.get("guidance_recommendation_title")
                or bottom_rec.get("label")
                or "Apply bottom recommendation"
            )
            _add_option(
                updates=bu,
                action_type="apply_compound_guidance" if is_compound else "apply_bottom_recommendation",
                payload={
                    "updates": bu,
                    "guidance_banner_title": rec_title,
                    "label": rec_title,
                },
                label=rec_title,
                source="bottom_recommendation",
                family_tag=str(bottom_rec.get("recommendation_family_tag") or ""),
                subfamilies=list(bottom_rec.get("subfamilies") or []) if isinstance(bottom_rec.get("subfamilies"), list) else [],
            )

    geom_rec = _compute_geometry_recommendation(guidance_state)
    if isinstance(geom_rec, dict):
        gu = dict(geom_rec.get("updates") or {})
        if gu:
            g_label = str(geom_rec.get("label") or "Apply geometry recommendation")
            _add_option(
                updates=gu,
                action_type="apply_geometry_recommendation",
                payload={"updates": gu, "label": g_label},
                label=g_label,
                source="geometry_recommendation",
            )

    shear_rec = _compute_shear_recommendation(guidance_state)
    if isinstance(shear_rec, dict):
        su = dict(shear_rec.get("updates") or {})
        if su:
            s_label = str(shear_rec.get("label") or "Apply shear recommendation")
            _add_option(
                updates=su,
                action_type="apply_shear_recommendation",
                payload={"updates": su, "label": s_label},
                label=s_label,
                source="shear_recommendation",
            )

    if not option_specs:
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "no_actionable_options"
        return None

    uniq: dict[tuple, dict] = {}
    for spec in option_specs:
        sig = _one_click_candidate_payload_signature(spec.get("updates") or {})
        uniq[sig] = spec
    option_specs = list(uniq.values())

    candidates: list[dict] = []
    for idx, spec in enumerate(option_specs):
        cand = _evaluate_auto_design_candidate(
            guidance_state,
            updates=dict(spec.get("updates") or {}),
            source=f"one_click_critical_option_{idx}",
            label=str(spec.get("label") or "one_click_option"),
            action_type=str(spec.get("action_type") or ""),
        )
        if not cand:
            continue
        cand["_one_click_spec"] = spec
        candidates.append(cand)
    if not candidates:
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "candidate_eval_failed"
        return None

    winner = _select_best_auto_design_candidate(candidates, mode_config, seed_candidate)
    if not winner:
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "no_selector_winner"
        return None
    if not bool(winner.get("is_compliant")):
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "selector_winner_not_compliant"
        return None
    if not bool(winner.get("candidate_reaches_target_band")):
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "selector_winner_not_band_reaching"
            debug_extra["one_click_critical_candidate_post_util"] = winner.get("candidate_post_util")
            debug_extra["one_click_critical_candidate_reaches_target_band"] = False
        return None
    spec = dict(winner.get("_one_click_spec") or {})
    updates = dict(spec.get("updates") or {})
    if _updates_match_state(guidance_state, updates):
        if isinstance(debug_extra, dict):
            debug_extra["one_click_critical_candidate_suppressed_reason"] = "winner_noop_updates"
        return None

    action_type = str(spec.get("action_type") or winner.get("action_type") or "apply_compound_guidance")
    clines = _guidance_change_lines_for_updates(guidance_state, updates)
    post_util = float(winner.get("candidate_post_util", 0.0) or 0.0)
    cur_util = float(seed_candidate.get("worst_util", 0.0) or 0.0)
    resolved_candidate = dict(winner)
    spec_or_winner_label = str(spec.get("label") or winner.get("label") or "Apply one-click recommendation")
    canon_title = str(
        winner.get("canonical_winner_label") or winner.get("label") or spec_or_winner_label or "",
    ).strip() or spec_or_winner_label
    resolved_candidate["canonical_winner_label"] = canon_title
    resolved_candidate["title_locked_from_final_winner"] = True
    resolved_candidate["resolved_candidate_label_raw"] = canon_title
    resolved_candidate["label"] = canon_title
    title = canon_title
    resolved_candidate["action_type"] = action_type
    resolved_candidate["updates"] = dict(updates)
    resolved_candidate["recommendation_family_tag"] = spec.get("family_tag")
    resolved_candidate["subfamilies"] = list(spec.get("subfamilies") or [])
    resolved_candidate["candidate_reaches_target_band"] = bool(winner.get("candidate_reaches_target_band"))
    resolved_candidate["worst_util"] = winner.get("candidate_post_util")
    resolved_candidate["recommendation_change_lines"] = clines or []
    item = _guidance_item_from_resolved_candidate(
        resolved_candidate,
        state=guidance_state,
        overview=overview,
        title=title,
        reasoning=f"Why: this option reaches the target band in one move ({cur_util:.2f} ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ {post_util:.2f}).",
        status="FAIL",
        primary_action="Apply recommendation",
    )
    if isinstance(debug_extra, dict):
        failure_coverage = dict(item.get("failure_coverage") or {})
        debug_extra["one_click_critical_candidate_exists"] = True
        debug_extra["one_click_critical_candidate_label"] = title
        debug_extra["one_click_critical_candidate_action_type"] = "apply_resolved_candidate"
        debug_extra["one_click_critical_candidate_post_util"] = post_util
        debug_extra["one_click_critical_candidate_reaches_target_band"] = bool(winner.get("candidate_reaches_target_band"))
        debug_extra["compound_shear_augmented"] = bool(resolved_candidate.get("compound_shear_augmented"))
        debug_extra["covers_all_current_failures"] = bool(
            item.get("covers_all_current_failures")
            or failure_coverage.get("covers_all_current_failures"),
        )
        debug_extra["covered_fail_keys"] = list(
            item.get("covered_fail_keys")
            or failure_coverage.get("covered_fail_keys")
            or [],
        )
        debug_extra["remaining_fail_keys"] = list(
            item.get("remaining_fail_keys")
            or failure_coverage.get("remaining_fail_keys")
            or [],
        )
        debug_extra["one_click_critical_candidate_suppressed_reason"] = None
    return item


def _enumerate_bottom_reo_design_trials(state: dict, *, mode_config: dict | None = None) -> list[dict]:
    if not isinstance(state, dict):
        return []
    cfg = dict(mode_config or _design_mode_config(_design_optimisation_goal(state)))
    layout_cache: dict = {}
    arrangements = _generate_local_bottom_arrangements(
        state,
        cfg,
        band=2,
        context={"layout_fit_cache": layout_cache},
        limit=12,
    )
    # Include a bounded set of stronger practical layouts so severe starter
    # states (e.g. 200x300 with light reo) can still discover one-click winners.
    stronger_specs = [
        (2, 2, 20),
        (2, 2, 24),
        (2, 2, 28),
        (3, 3, 20),
        (3, 3, 24),
        (3, 3, 28),
        (4, 4, 24),
        (4, 4, 28),
        (6, 0, 24),
        (8, 0, 24),
        (6, 0, 28),
        (8, 0, 28),
    ]
    seen_signatures = {
        (
            int((a or {}).get("bot1_count", 0) or 0),
            int((a or {}).get("bot2_count", 0) or 0),
            int((a or {}).get("db_bot_1", 0) or 0),
        )
        for a in arrangements
    }
    for c1, c2, dia in stronger_specs:
        arr = _normalise_bottom_layer_order(
            {
                "bot1_layout_mode": "Count",
                "bot1_count": int(c1),
                "db_bot_1": int(dia),
                "bot2_layout_mode": "Count",
                "bot2_count": int(c2),
                "db_bot_2": int(dia),
            },
        )
        sig = (
            int(arr.get("bot1_count", 0) or 0),
            int(arr.get("bot2_count", 0) or 0),
            int(arr.get("db_bot_1", 0) or 0),
        )
        if sig in seen_signatures:
            continue
        if not _arrangement_fits_state(state, arr, layout_cache=layout_cache):
            continue
        arrangements.append(arr)
        seen_signatures.add(sig)
    out: list[dict] = []
    for arrangement in arrangements:
        arr = dict(arrangement or {})
        updates = _bottom_arrangement_to_shared_updates(arr)
        if not isinstance(updates, dict):
            continue
        out.append(
            {
                "label": _practical_bottom_reo_label(
                    int(arr.get("bot1_count", 0) or 0),
                    int(arr.get("bot2_count", 0) or 0),
                    int(arr.get("db_bot_1", 0) or 0),
                ),
                "updates": updates,
                "arrangement": arr,
            },
        )
    return out


def _augment_candidate_with_shear_if_needed(
    base_state: dict,
    candidate: dict,
    *,
    mode_cfg: dict,
) -> dict | None:
    """
    Try to compound a base one-click candidate with shear reinforcement updates
    when the current failure set includes shear or the candidate still leaves shear failing.
    Returns:
      - compounded candidate dict when a better compliant compound candidate is found
      - None if no shear augmentation is needed or no valid augmentation exists
    """
    if not isinstance(candidate, dict):
        return None

    candidate_state = dict(candidate.get("state") or {})
    candidate_overview = dict(candidate.get("overview") or {})
    current_overview = _collect_design_overview(base_state)

    current_fail_keys = {
        key
        for key, val in (current_overview.get("statuses") or {}).items()
        if str(val or "").upper() == "FAIL"
    }
    candidate_fail_keys = {
        key
        for key, val in (candidate_overview.get("statuses") or {}).items()
        if str(val or "").upper() == "FAIL"
    }

    shear_relevant_now = ("shear" in current_fail_keys) or ("shear" in candidate_fail_keys)
    if not shear_relevant_now:
        return None

    shear_rec = _compute_shear_recommendation(candidate_state)
    if not (
        isinstance(shear_rec, dict)
        and isinstance(shear_rec.get("updates"), dict)
        and shear_rec.get("updates")
    ):
        return None

    merged_updates = dict(candidate.get("updates") or {})
    merged_updates.update(dict(shear_rec.get("updates") or {}))

    compounded = _evaluate_auto_design_candidate(
        base_state,
        updates=merged_updates,
        source="one_click_solver_search_compound_shear",
        label=str(candidate.get("label") or "Apply one-click design"),
        action_type="apply_resolved_candidate",
    )
    if not isinstance(compounded, dict):
        return None

    _annotate_candidate_target_band_metrics(compounded, mode_cfg)

    subfamilies = _compound_subfamilies_from_updates(merged_updates)
    compounded["updates"] = dict(merged_updates)
    compounded["subfamilies"] = list(subfamilies)
    compounded["recommendation_family_tag"] = _family_tag_from_compound_updates(merged_updates, base_state)
    compounded["is_compound"] = True
    compounded["compound_shear_augmented"] = True
    compounded["guidance_change_lines"] = _guidance_change_lines_for_updates(base_state, merged_updates)
    compounded["action_type"] = "apply_resolved_candidate"

    title, _, _ = _compound_guidance_title_reasoning_why(
        base_state,
        merged_updates,
        subfamilies,
        strengthening=True,
    )
    compounded["label"] = str(title or candidate.get("label") or "Apply one-click design")
    return compounded

@speed_profiled("candidate_generation.solve_one_click_candidate", category="compute")
def _solve_one_click_candidate(
    state: dict,
    *,
    goal: str | None = None,
    expanded: bool = False,
    debug_enabled: bool = False,
) -> dict | None:
    """
    Bounded one-click solver:
    - searches a practical space of geometry + bottom reinforcement combinations
    - returns the best compliant candidate near the target band
    - returns None if no compliant candidate exists in the bounded search space

    Uses a small geometry grid first; if no in-band compliant candidate is found, reruns with
    the full grid (expanded=True) to match the legacy search breadth.
    """
    if not isinstance(state, dict):
        return None

    goal_name = str(goal or _design_optimisation_goal(state) or "balanced")
    mode_cfg = _design_mode_config(goal_name)
    target_min = float(mode_cfg.get("target_util_min", EFFICIENCY_TARGET_UTIL_MIN) or EFFICIENCY_TARGET_UTIL_MIN)
    target_max = float(mode_cfg.get("target_util_max", EFFICIENCY_TARGET_UTIL_MAX) or EFFICIENCY_TARGET_UTIL_MAX)
    width_key, _, base_width = _resolve_geometry_width_context(state)
    base_width = float(base_width or 0.0)
    base_depth = float(_float_from_state(state, "D", 0.0) or 0.0)

    width_steps_full = [0.0, 25.0, 50.0, 75.0, 100.0, 125.0, 150.0]
    depth_steps_full = [0.0, 25.0, 50.0, 75.0, 100.0, 125.0, 150.0]
    width_steps_small = [0.0, 25.0, 50.0]
    depth_steps_small = [0.0, 25.0, 50.0, 75.0]

    def _distance_to_band(util: float) -> float:
        if util < target_min:
            return target_min - util
        if util > target_max:
            return util - target_max
        return 0.0

    def _run_pass(width_steps: list[float], depth_steps: list[float]) -> tuple[list[dict], int, int, float | None, list[int], dict[float, list[dict]]]:
        _run_pass_t0 = time.perf_counter()
        evaluated_candidates: list[dict] = []
        explored_candidates = 0
        skipped_invalid = 0
        best_noncompliant_worst_util = None
        bottom_trial_cache: dict[float, list[dict]] = {}
        observed_bottom_trial_counts: list[int] = []
        seen_keys: set[tuple] = set()
        current_overview = _collect_design_overview(state)
        current_fail_keys = sorted(
            [
                key
                for key, val in (current_overview.get("statuses") or {}).items()
                if str(val or "").upper() == "FAIL"
            ],
        )

        def _resolve_failure_coverage(candidate: dict) -> dict:
            coverage = dict(candidate.get("failure_coverage") or candidate.get("failure_coverage_summary") or {})
            if not coverage:
                candidate_overview = dict(candidate.get("overview") or {})
                candidate_fail_keys = sorted(
                    [
                        key
                        for key, val in (candidate_overview.get("statuses") or {}).items()
                        if str(val or "").upper() == "FAIL"
                    ],
                )
                covered = sorted([k for k in current_fail_keys if k not in candidate_fail_keys])
                remaining = sorted([k for k in current_fail_keys if k in candidate_fail_keys])
                coverage = {
                    "current_fail_keys": list(current_fail_keys),
                    "candidate_fail_keys": list(candidate_fail_keys),
                    "covered_fail_keys": list(covered),
                    "remaining_fail_keys": list(remaining),
                    "covers_all_current_failures": len(current_fail_keys) > 0 and len(remaining) == 0,
                }
            candidate["failure_coverage"] = dict(coverage)
            candidate["failure_coverage_summary"] = dict(coverage)
            candidate["covers_all_current_failures"] = bool(coverage.get("covers_all_current_failures"))
            candidate["covered_fail_keys"] = list(coverage.get("covered_fail_keys") or [])
            candidate["remaining_fail_keys"] = list(coverage.get("remaining_fail_keys") or [])
            return coverage

        def _prefer_augmented_candidate(base_candidate: dict, augmented_candidate: dict) -> bool:
            if not (isinstance(base_candidate, dict) and isinstance(augmented_candidate, dict)):
                return False
            base_compliant = bool(base_candidate.get("is_compliant"))
            augmented_compliant = bool(augmented_candidate.get("is_compliant"))
            if augmented_compliant and not base_compliant:
                return True
            if not (base_compliant and augmented_compliant):
                return False
            base_cov = _resolve_failure_coverage(base_candidate)
            aug_cov = _resolve_failure_coverage(augmented_candidate)
            base_covered = len(base_cov.get("covered_fail_keys") or [])
            aug_covered = len(aug_cov.get("covered_fail_keys") or [])
            if aug_covered > base_covered:
                return True
            if aug_covered != base_covered:
                return False
            try:
                base_dist = float(base_candidate.get("candidate_distance_to_target_band", float("inf")) or float("inf"))
            except Exception:
                base_dist = float("inf")
            try:
                aug_dist = float(augmented_candidate.get("candidate_distance_to_target_band", float("inf")) or float("inf"))
            except Exception:
                aug_dist = float("inf")
            return aug_dist < base_dist

        for db in width_steps:
            for dD in depth_steps:
                geom_state = _geometry_state_with_updates(
                    state,
                    depth=(base_depth + dD) if dD else None,
                    width=(base_width + db) if db else None,
                )
                geom_updates: dict[str, object] = {}
                geom_D = float(_float_from_state(geom_state, "D", base_depth) or base_depth)
                if abs(geom_D - base_depth) > 1e-9:
                    geom_updates["D"] = geom_D
                geom_w = float(_design_width_value(geom_state) or base_width)
                if abs(geom_w - base_width) > 1e-9:
                    geom_updates[width_key] = geom_w
                    if width_key != "b":
                        geom_updates["b"] = geom_w

                width_bucket = round(float(geom_w), 3)
                trial_pool = bottom_trial_cache.get(width_bucket)
                if trial_pool is None:
                    try:
                        trial_pool = list(_enumerate_bottom_reo_design_trials(geom_state, mode_config=mode_cfg) or [])
                    except Exception:
                        trial_pool = []
                    if not trial_pool:
                        trial_pool = [{"label": "Keep current bottom reo", "updates": {}}]
                    bottom_trial_cache[width_bucket] = trial_pool
                observed_bottom_trial_counts.append(len(trial_pool))

                for trial in trial_pool:
                    trial_updates = dict(trial.get("updates") or {})
                    merged_updates = dict(geom_updates)
                    merged_updates.update(trial_updates)
                    if not merged_updates:
                        continue
                    trial_state = dict(state)
                    trial_state.update(merged_updates)
                    trial_key = _candidate_cache_key(trial_state)
                    if trial_key in seen_keys:
                        continue
                    seen_keys.add(trial_key)
                    if _quick_bending_util(trial_state) > 2.0:
                        continue
                    explored_candidates += 1
                    update_keys = set(merged_updates.keys())
                    has_geom = bool(update_keys & _COMPOUND_GEOMETRY_UPDATE_KEYS)
                    has_bottom = bool(update_keys & _COMPOUND_BOTTOM_UPDATE_KEYS)
                    if has_geom and has_bottom:
                        candidate_action_type = "apply_compound_guidance"
                    elif has_bottom:
                        candidate_action_type = "apply_bottom_recommendation"
                    else:
                        candidate_action_type = "apply_geometry_recommendation"
                    try:
                        evaluated = _evaluate_auto_design_candidate(
                            state,
                            updates=merged_updates,
                            source="one_click_solver_search",
                            label=str(trial.get("label") or "Apply one-click design"),
                            action_type=candidate_action_type,
                        )
                    except Exception:
                        skipped_invalid += 1
                        continue
                    if not isinstance(evaluated, dict):
                        skipped_invalid += 1
                        continue
                    _annotate_candidate_target_band_metrics(evaluated, mode_cfg)
                    post_util = evaluated.get("candidate_post_util", evaluated.get("worst_util"))
                    try:
                        post_util = float(post_util) if post_util is not None else None
                    except Exception:
                        post_util = None
                    if post_util is None:
                        continue
                    reaches_band = bool(target_min <= post_util <= target_max)
                    resolved = dict(evaluated)
                    resolved["candidate_reaches_target_band"] = reaches_band
                    resolved["reaches_target_band"] = reaches_band
                    resolved["updates"] = dict(merged_updates)
                    resolved["action_type"] = "apply_resolved_candidate"
                    resolved["guidance_change_lines"] = _guidance_change_lines_for_updates(state, merged_updates)
                    subfamilies = _compound_subfamilies_from_updates(merged_updates)
                    resolved["subfamilies"] = list(subfamilies)
                    resolved["recommendation_family_tag"] = _family_tag_from_compound_updates(merged_updates, state)
                    resolved["is_compound"] = bool(has_geom and has_bottom)
                    resolved["compound_shear_augmented"] = False
                    title, _, _ = _compound_guidance_title_reasoning_why(
                        state,
                        merged_updates,
                        subfamilies,
                        strengthening=True,
                    )
                    resolved["label"] = str(title or trial.get("label") or "Apply one-click design")
                    _resolve_failure_coverage(resolved)
                    candidates_to_add = [resolved]
                    augmented = _augment_candidate_with_shear_if_needed(
                        state,
                        resolved,
                        mode_cfg=mode_cfg,
                    )
                    if isinstance(augmented, dict):
                        _resolve_failure_coverage(augmented)
                        if _prefer_augmented_candidate(resolved, augmented):
                            augmented["one_click_compound_preferred"] = True
                        candidates_to_add.append(augmented)
                    for candidate_variant in candidates_to_add:
                        evaluated_candidates.append(candidate_variant)
                        if not bool(candidate_variant.get("is_compliant")):
                            try:
                                wu = float(candidate_variant.get("worst_util", 0.0) or 0.0)
                                if best_noncompliant_worst_util is None or wu < best_noncompliant_worst_util:
                                    best_noncompliant_worst_util = wu
                            except Exception:
                                pass

        speed_profile_record(
            "candidate_generation.solve_one_click_candidate.run_pass",
            (time.perf_counter() - _run_pass_t0) * 1000.0,
            category="compute",
        )
        return (
            evaluated_candidates,
            explored_candidates,
            skipped_invalid,
            best_noncompliant_worst_util,
            observed_bottom_trial_counts,
            bottom_trial_cache,
        )

    def _trace_no_compliant(
        explored: int,
        skipped: int,
        obs_counts: list[int],
        btcache: dict[float, list[dict]],
        bnu: float | None,
        *,
        solver_expanded: bool,
    ) -> None:
        if not debug_enabled:
            return
        _merge_design_guide_rank_trace(
            {
                "one_click_solver": {
                    "searched": True,
                    "goal": goal_name,
                    "explored_candidates": explored,
                    "skipped_invalid": skipped,
                    "compliant_count": 0,
                    "band_reacher_count": 0,
                    "result": "no_compliant_candidates",
                    "one_click_solver_expanded": bool(solver_expanded),
                },
            },
        )

    def _trace_winner(
        winner: dict,
        all_candidates: list[dict],
        band_reachers: list[dict],
        explored: int,
        skipped: int,
        *,
        solver_expanded: bool,
    ) -> None:
        evidence = _build_candidate_search_evidence(
            selected_candidate=winner,
            all_candidates=list(all_candidates or []),
            target_low=float(target_min),
            target_high=float(target_max),
            exhaustive=bool(solver_expanded),
            search_scope="one_click_solver_geometry_bottom_shear_compound",
            selected_title=str(winner.get("label") or ""),
        )
        winner["candidate_search_evidence"] = dict(evidence)
        winner["candidate_id"] = evidence.get("selected_candidate_id")
        winner["source_candidate_id"] = evidence.get("selected_candidate_id")
        if not debug_enabled:
            return
        _merge_design_guide_rank_trace(
            {
                "one_click_solver": {
                    "searched": True,
                    "goal": goal_name,
                    "explored_candidates": explored,
                    "skipped_invalid": skipped,
                    "compliant_count": sum(1 for c in all_candidates if bool(c.get("is_compliant"))),
                    "band_reacher_count": len(band_reachers),
                    "used_pool": "all_scored_candidates",
                    "winner_label": winner.get("label"),
                    "winner_post_util": winner.get("candidate_post_util", winner.get("worst_util")),
                    "winner_reaches_target_band": bool(winner.get("candidate_reaches_target_band")),
                    "one_click_solver_expanded": bool(solver_expanded),
                    "candidate_search_evidence": dict(evidence),
                },
            },
        )

    if not expanded:
        small_candidates, ex_s, sk_s, bnu_s, obs_s, btc_s = _run_pass(width_steps_small, depth_steps_small)
        if small_candidates:
            current_ast = float(
                (
                    _effective_bottom_design_state(
                        state,
                        _candidate_bottom_updates(state),
                    ).get("Ast_bot", 0.0)
                    or 0.0
                ),
            )
            scored_small = []
            for candidate in small_candidates:
                util = candidate.get("candidate_post_util", candidate.get("worst_util"))
                scored_small.append(
                    (
                        (
                            0 if bool(candidate.get("is_compliant")) else 1,
                            0 if bool(candidate.get("covers_all_current_failures")) else 1,
                            len(candidate.get("remaining_fail_keys") or []),
                            -len(candidate.get("covered_fail_keys") or []),
                            0 if bool(candidate.get("one_click_compound_preferred")) else 1,
                            float(candidate.get("candidate_distance_to_target_band", _distance_to_band(float(util or 0.0)))),
                        score_candidate(util, candidate, current_ast=current_ast, goal=goal_name),
                        ),
                        candidate,
                    ),
                )
            scored_small.sort(key=lambda row: row[0])
            winner = scored_small[0][1]
            band_small = [c for c in small_candidates if bool(c.get("candidate_reaches_target_band"))]
            _trace_winner(winner, small_candidates, band_small, ex_s, sk_s, solver_expanded=False)
            if not bool(winner.get("candidate_reaches_target_band")):
                return _solve_one_click_candidate(
                    state,
                    goal=goal,
                    expanded=True,
                    debug_enabled=debug_enabled,
                )
            _wl = str(winner.get("label") or "").strip()
            if _wl:
                winner["canonical_winner_label"] = _wl
                winner["title_locked_from_final_winner"] = True
            return winner
        return _solve_one_click_candidate(
            state,
            goal=goal,
            expanded=True,
            debug_enabled=debug_enabled,
        )

    evaluated_candidates, explored_candidates, skipped_invalid, best_noncompliant_worst_util, observed_bottom_trial_counts, bottom_trial_cache = _run_pass(
        width_steps_full,
        depth_steps_full,
    )

    if not evaluated_candidates:
        _trace_no_compliant(
            explored_candidates,
            skipped_invalid,
            observed_bottom_trial_counts,
            bottom_trial_cache,
            best_noncompliant_worst_util,
            solver_expanded=True,
        )
        return None

    current_ast = float(
        (
            _effective_bottom_design_state(
                state,
                _candidate_bottom_updates(state),
            ).get("Ast_bot", 0.0)
            or 0.0
        ),
    )
    scored_candidates: list[tuple[tuple, dict]] = []
    for candidate in evaluated_candidates:
        util = candidate.get("candidate_post_util", candidate.get("worst_util"))
        scored_candidates.append(
            (
                (
                    0 if bool(candidate.get("is_compliant")) else 1,
                    0 if bool(candidate.get("covers_all_current_failures")) else 1,
                    len(candidate.get("remaining_fail_keys") or []),
                    -len(candidate.get("covered_fail_keys") or []),
                    0 if bool(candidate.get("one_click_compound_preferred")) else 1,
                    float(candidate.get("candidate_distance_to_target_band", _distance_to_band(float(util or 0.0)))),
                score_candidate(util, candidate, current_ast=current_ast, goal=goal_name),
                ),
                candidate,
            ),
        )
    scored_candidates.sort(key=lambda row: row[0])
    winner = scored_candidates[0][1]
    band_reachers = [c for c in evaluated_candidates if bool(c.get("candidate_reaches_target_band"))]
    _trace_winner(
        winner,
        evaluated_candidates,
        band_reachers,
        explored_candidates,
        skipped_invalid,
        solver_expanded=True,
    )
    _wl = str(winner.get("label") or "").strip()
    if _wl:
        winner["canonical_winner_label"] = _wl
        winner["title_locked_from_final_winner"] = True
    return winner


def _compute_design_guidance_items_core(
    state: dict,
    debug_sink: dict | None = None,
    *,
    guidance_debug_verbose: bool | None = None,
    debug_enabled: bool = False,
) -> list[dict]:
    _core_stage_debug = os.environ.get("CODEX_DG_STAGE_DEBUG", "").strip().lower() in {"1", "true", "yes", "on"}
    if _core_stage_debug:
        print("DG_STAGE core_entry", file=sys.stderr, flush=True)
    design_context = _build_design_actions_context(state)
    if _core_stage_debug:
        print("DG_STAGE core_after_context", file=sys.stderr, flush=True)
    guidance_state = dict(design_context.get("state") or _guidance_state_snapshot(state))
    overview = _collect_design_overview(guidance_state, context=design_context)
    if _core_stage_debug:
        print(
            f"DG_STAGE core_after_overview any_fail={bool(overview.get('any_fail'))} all_pass={bool(overview.get('all_key_pass'))} worst={overview.get('worst_util')}",
            file=sys.stderr,
            flush=True,
        )
    mode_config = _design_mode_config(_design_optimisation_goal(guidance_state))
    target_band_with_eps_passed = _is_in_target_zone_with_eps(overview, mode_config, eps=TARGET_BAND_EPS)
    if _core_stage_debug:
        print(f"DG_STAGE core_after_target_check target={target_band_with_eps_passed}", file=sys.stderr, flush=True)
    guidance_branch = "unknown"
    _verbose = True if guidance_debug_verbose is None else bool(guidance_debug_verbose)
    _sink_is_dict = isinstance(debug_sink, dict)
    full_dbg = _sink_is_dict and _verbose
    min_dbg = _sink_is_dict and _verbose
    if min_dbg:
        debug_sink["guidance_resolved_state"] = guidance_state
    if full_dbg:
        debug_sink["overview"] = overview
        debug_sink["overview_actions_used"] = overview.get("actions_used")
        debug_sink["guidance_actions_used"] = dict(design_context.get("actions") or {})
        debug_sink["target_band_eps"] = float(TARGET_BAND_EPS)
        debug_sink["target_band_with_eps_passed"] = bool(target_band_with_eps_passed)
    if _core_stage_debug:
        print("DG_STAGE core_before_not_started_check", file=sys.stderr, flush=True)
    _not_started = _guidance_not_started(guidance_state, overview)
    if _core_stage_debug:
        print(f"DG_STAGE core_after_not_started_check not_started={_not_started}", file=sys.stderr, flush=True)
    if _not_started:
        guidance_branch = "not_started"
        if _core_stage_debug:
            print("DG_STAGE core_before_start_item", file=sys.stderr, flush=True)
        start_item = _guidance_start_item(guidance_state)
        if _core_stage_debug:
            print("DG_STAGE core_after_start_item", file=sys.stderr, flush=True)
        if _sink_is_dict:
            debug_sink["guidance_branch"] = guidance_branch
            debug_sink["selected_action_type"] = start_item.get("action_type")
            debug_sink["selected_title"] = start_item.get("title_main")
        return [start_item]
    _post_apply_acceptance_audit = {}
    if _local_cleanup_post_apply_acceptance_matches(guidance_state):
        _post_apply_acceptance_audit = _post_click_accepted_green_audit(
            overview,
            blocker_source=debug_sink if isinstance(debug_sink, dict) else None,
            state=guidance_state,
        )
        if min_dbg:
            debug_sink.update(_post_apply_acceptance_audit)
    _last_apply_route_for_post_active = dict(st.session_state.get(DESIGN_GUIDE_LAST_APPLY_ROUTE_KEY) or {})
    _compute_core_branch_projection = _build_design_guide_controller_compute_core_branch_request_projection(
        overview=overview,
        target_band_with_eps_passed=bool(target_band_with_eps_passed),
        overview_required_checks_acceptable=bool(_overview_required_checks_acceptable(overview)),
        post_apply_acceptance_matches=bool(_local_cleanup_post_apply_acceptance_matches(guidance_state)),
        last_apply_route=dict(_last_apply_route_for_post_active),
    )
    _post_apply_from_active_failure_repair = bool(
        _compute_core_branch_projection.get("post_apply_from_active_failure_repair")
    )
    if (
        _post_apply_from_active_failure_repair
        and not bool(overview.get("any_fail"))
        and _overview_required_checks_acceptable(overview)
    ):
        _post_active_exact_blockers = dict(
            _post_apply_acceptance_audit.get("post_click_exact_blockers_by_family") or {}
        )
        try:
            _post_active_actions = dict(_resolve_design_actions_from_state(guidance_state) or {})
        except Exception:
            _post_active_actions = {}
        try:
            _post_active_vu = abs(
                _float_from_state(
                    guidance_state,
                    "uls_Vstar",
                    guidance_state.get("Vu_star", 0.0),
                )
            )
        except Exception:
            _post_active_vu = 0.0
        _post_active_zero_shear_projection = _resolve_design_guide_controller_post_active_zero_shear_predicate(
            shear_demands_negligible=bool(_shear_demands_negligible(_post_active_actions)),
            direct_vu=_post_active_vu,
            shear_demand_abs_tol_kn=GUIDANCE_SHEAR_DEMAND_ABS_TOL_KN,
        )
        _post_active_zero_shear = bool(_post_active_zero_shear_projection.get("post_active_zero_shear"))
        _post_active_shear_blocker = (
            dict(_post_active_exact_blockers.get("shear") or {})
            if isinstance(_post_active_exact_blockers.get("shear"), dict)
            else {}
        )
        _post_active_acceptance_audit = dict(_post_apply_acceptance_audit or {})
        _post_active_acceptance_audit.update(
            {
                "post_click_accepted_green": True,
                "post_click_accepted_green_valid": True,
                "post_click_design_guide_state": "accepted_green",
                "post_click_required_checks_accepted_outside_target_band": not bool(
                    target_band_with_eps_passed
                ),
                "terminal_state_reason": "active_failure_repair_required_checks_pass",
            }
        )
        if _post_active_shear_blocker:
            _post_active_acceptance_exact = dict(
                _post_active_acceptance_audit.get("post_click_exact_blockers_by_family")
                or {}
            )
            _post_active_acceptance_exact.setdefault(
                "shear",
                dict(_post_active_shear_blocker),
            )
            _post_active_acceptance_audit["post_click_exact_blockers_by_family"] = dict(
                _post_active_acceptance_exact
            )
            _post_active_acceptance_audit["exact_blockers_by_family"] = dict(
                _post_active_acceptance_exact
            )
            _post_active_acceptance_cleanup = dict(
                _post_active_acceptance_audit.get("post_click_cleanup_evidence_by_family")
                or _post_active_acceptance_audit.get("cleanup_evidence_by_family")
                or {}
            )
            _post_active_acceptance_cleanup.setdefault(
                "shear",
                dict(_post_active_shear_blocker),
            )
            _post_active_acceptance_audit["post_click_cleanup_evidence_by_family"] = dict(
                _post_active_acceptance_cleanup
            )
            _post_active_acceptance_audit["cleanup_evidence_by_family"] = dict(
                _post_active_acceptance_cleanup
            )
        _post_active_target_accepted = _post_active_repair_target_accepted_item(
            guidance_state,
            overview,
            mode_config,
            _post_active_acceptance_audit,
            debug_sink=debug_sink if min_dbg else None,
            allow_required_checks_terminal=True,
        )
        if isinstance(_post_active_target_accepted, dict):
            return [_post_active_target_accepted]
        if _post_active_zero_shear:
            guidance_branch = "post_active_repair_zero_shear_terminal"
            accepted_util = _parse_util_value(overview.get("worst_util") or overview.get("governing_util"))
            target_lo, target_hi, _ = _resolved_efficiency_target_band(
                mode_config,
                goal=_design_optimisation_goal(guidance_state),
            )
            _zero_shear_projection = _build_design_guide_controller_post_active_zero_shear_terminal_projection(
                accepted_util=accepted_util,
                target_low=target_lo,
                target_high=target_hi,
                shear_util=_parse_util_value(dict(overview.get("utils") or {}).get("shear")),
                existing_excluded_families=dict(
                    _post_apply_acceptance_audit.get("post_click_excluded_families") or {}
                ),
            )
            accepted_item = dict(_zero_shear_projection.get("item") or {})
            if min_dbg:
                debug_sink.update(dict(_zero_shear_projection.get("debug_updates") or {}))
            return [accepted_item]
        if _post_active_shear_blocker:
            guidance_branch = "post_active_repair_shear_cleanup_blocked"
            _shear_blocker_reason = str(
                _post_active_shear_blocker.get("reason")
                or _post_active_shear_blocker.get("why_reduction_would_hurt_other_design_elements")
                or "No further one-click shear cleanup can preserve all required checks."
            ).strip()
            _shear_blocker_util = _parse_util_value(
                _post_active_shear_blocker.get("current_util")
                or _post_active_shear_blocker.get("failed_check_util")
                or dict(overview.get("utils") or {}).get("shear")
            )
            _post_active_shear_cleanup_item = None
            try:
                _post_active_shear_cleanup_item = _shear_best_safe_cleanup_item_from_evidence(
                    guidance_state,
                    overview,
                    _post_active_shear_blocker,
                )
            except Exception:
                _post_active_shear_cleanup_item = None
            if not isinstance(_post_active_shear_cleanup_item, dict):
                try:
                    _post_active_shear_cleanup_item = _shear_low_util_target_cleanup_item(
                        guidance_state,
                        overview,
                        threshold=float(FINAL_ACCEPTED_MIN_FAMILY_UTIL),
                        allow_best_safe_below_threshold=True,
                    )
                except Exception:
                    _post_active_shear_cleanup_item = None
            _post_active_shear_cleanup_contract = dict(
                (_post_active_shear_cleanup_item or {}).get("button_contract") or {}
            )
            if _design_guide_button_contract_enabled(_post_active_shear_cleanup_contract):
                _post_active_shear_cleanup_item = _attach_family_status_display_payload(
                    _post_active_shear_cleanup_item,
                    state=guidance_state,
                )
                _stamp_zero_bending_demand_exclusion(
                    _post_active_shear_cleanup_item,
                    guidance_state,
                    dict(overview.get("utils") or {}),
                )
                if min_dbg:
                    _post_active_shear_cleanup_evidence = dict(
                        _post_active_shear_cleanup_item.get("candidate_search_evidence") or {}
                    )
                    debug_sink.update(
                        _build_design_guide_controller_post_active_residual_shear_cleanup_debug_projection(
                            cleanup_item=_post_active_shear_cleanup_item,
                            cleanup_contract=_post_active_shear_cleanup_contract,
                            cleanup_evidence=_post_active_shear_cleanup_evidence,
                        )
                    )
                    _stamp_zero_bending_demand_exclusion(
                        debug_sink,
                        guidance_state,
                        dict(overview.get("utils") or {}),
                    )
                return [_post_active_shear_cleanup_item]
            _post_active_shear_blocked_projection = (
                _build_design_guide_controller_post_active_shear_cleanup_blocked_projection(
                    shear_blocker_reason=_shear_blocker_reason,
                    shear_blocker_util=_shear_blocker_util,
                    mode_config=mode_config,
                    shear_blocker=_post_active_shear_blocker,
                )
            )
            blocker_item = dict(_post_active_shear_blocked_projection.get("item") or {})
            if min_dbg:
                debug_sink.update(
                    dict(_post_active_shear_blocked_projection.get("debug_updates") or {})
                )
            return [blocker_item]
    if (
        _local_cleanup_post_apply_acceptance_matches(guidance_state)
        and "bending" in {
            str(family or "").strip().lower()
            for family in list(_post_apply_acceptance_audit.get("post_click_families_below_final_threshold") or [])
            if str(family or "").strip()
        }
    ):
        post_apply_resolution_item = _post_click_low_bending_resolution_item(
            guidance_state,
            overview,
            mode_config,
            _post_apply_acceptance_audit,
            debug_sink=debug_sink if isinstance(debug_sink, dict) else None,
        )
        if isinstance(post_apply_resolution_item, dict):
            guidance_branch = "post_apply_low_bending_resolution"
            if min_dbg:
                debug_sink["guidance_branch"] = guidance_branch
                debug_sink["selected_action_type"] = post_apply_resolution_item.get("action_type")
                debug_sink["selected_title"] = post_apply_resolution_item.get("title_main")
            return [post_apply_resolution_item]
    if (
        _local_cleanup_post_apply_acceptance_matches(guidance_state)
        and not bool(overview.get("any_fail"))
        and bool(target_band_with_eps_passed)
        and bool(_post_apply_acceptance_audit.get("post_click_accepted_green_valid"))
        and not list(_post_apply_acceptance_audit.get("post_click_unresolved_low_util_families") or [])
        and "bending" not in {
            str(family or "").strip().lower()
            for family in list(_post_apply_acceptance_audit.get("post_click_families_below_final_threshold") or [])
            if str(family or "").strip()
        }
    ):
        guidance_branch = "post_apply_local_cleanup_accepted"
        accepted_util = _parse_util_value(overview.get("worst_util") or overview.get("governing_util"))
        target_lo, target_hi, _ = _resolved_efficiency_target_band(
            mode_config,
            goal=_design_optimisation_goal(guidance_state),
        )
        accepted_item = _guidance_item(
            "general",
            "Design accepted - target band achieved",
            "The one-click cleanup has been applied and the current design is inside the target band.",
            None,
            "Why: all required checks remain acceptable, governing utilisation is inside the target band, and this is the accepted post-click Design Guide state.",
            "Key checks: bending, shear, serviceability, target utilisation band",
            None,
            None,
            status="PASS",
            util=accepted_util,
        )
        accepted_item["guidance_intent"] = "already_efficient"
        accepted_item["design_guide_terminal_state"] = "optimal"
        accepted_item["display_truth"] = {
            "display_truth_source": "published_summary",
            "displayed_util": accepted_util,
            "displayed_status": "OPTIMAL",
            "target_low": float(target_lo),
            "target_high": float(target_hi),
            "displayed_within_target_band": True,
            "source_summary_util": accepted_util,
            "source_candidate_util": None,
            "source_post_commit_util": accepted_util,
        }
        if min_dbg:
            debug_sink["guidance_branch"] = guidance_branch
            debug_sink["selected_action_type"] = None
            debug_sink["selected_title"] = accepted_item.get("title_main")
            debug_sink["post_click_accepted_green"] = True
            debug_sink["post_click_accepted_green_valid"] = True
            debug_sink["post_click_design_guide_state"] = "accepted_green"
            debug_sink["post_click_executable_safe_cleanup_count"] = 0
            _stamp_exact_cleanup_blocker_evidence(
                debug_sink,
                _post_apply_acceptance_audit,
                overview,
                accepted_reason="post_apply_cleanup_state_accepted",
            )
        return [accepted_item]
    if (
        _local_cleanup_post_apply_acceptance_matches(guidance_state)
        and not bool(_post_apply_acceptance_audit.get("post_click_accepted_green_valid", True))
    ):
        if min_dbg:
            debug_sink["post_click_accepted_green"] = False
            debug_sink["terminal_state_blocked_by_local_cleanup"] = True
            debug_sink["terminal_state_blocked_reason"] = str(
                _post_apply_acceptance_audit.get("post_click_accepted_green_invalid_reason")
                or "post_apply_cleanup_state_has_unresolved_overprovided_family"
            )
        post_apply_resolution_item = _post_click_low_bending_resolution_item(
            guidance_state,
            overview,
            mode_config,
            _post_apply_acceptance_audit,
            debug_sink=debug_sink if isinstance(debug_sink, dict) else None,
        )
        if isinstance(post_apply_resolution_item, dict):
            guidance_branch = "post_apply_low_bending_resolution"
            if min_dbg:
                debug_sink["guidance_branch"] = guidance_branch
                debug_sink["selected_action_type"] = post_apply_resolution_item.get("action_type")
                debug_sink["selected_title"] = post_apply_resolution_item.get("title_main")
            return [post_apply_resolution_item]
    governing_action, primary_utils = _guidance_governing_primary_action(overview)
    if full_dbg:
        debug_sink["governing_action"] = governing_action
        debug_sink["primary_utils"] = dict(primary_utils)
    bend_pack = overview["packs"]["bending"]
    shear_pack = overview["packs"]["shear"]
    crack_pack = overview["packs"]["crack"]
    defl_pack = overview["packs"]["deflection"]

    items = [
        _bending_guidance_item(guidance_state, bend_pack),
        _shear_guidance_item(guidance_state, shear_pack),
        _crack_guidance_item(guidance_state, crack_pack),
        _deflection_guidance_item(guidance_state, defl_pack),
    ]
    filtered = [item for item in items if item is not None]
    filtered.sort(key=lambda item: item["priority"], reverse=True)
    governing_item = next(
        (item for item in filtered if str(item.get("check_key") or "") == str(governing_action or "")),
        None,
    )
    critical = [
        item for item in filtered
        if item["bucket"] in ("fail", "warn")
        and (
            item["bucket"] == "fail"
            or item.get("util") is None
            or item["util"] >= GUIDANCE_NEAR_LIMIT_UTIL_THRESHOLD
            or overview["any_fail"]
            or overview["any_warn"]
        )
    ]
    governing_item_is_critical = bool(governing_item and governing_item in critical)
    out_of_band_live = bool(_compute_core_branch_projection.get("out_of_band_live"))
    primary_one_click_requires_full_coverage, primary_one_click_fail_keys = (
        _requires_full_coverage_for_primary_one_click(overview)
    )
    primary_critical = (
        next(
            (
                item for item in critical
                if str(item.get("check_key") or "") == str(governing_action or "")
            ),
            critical[0],
        )
        if critical
        else None
    )
    if not bool(overview.get("any_fail")):
        reshape_item = _in_target_shear_congestion_reshape_guidance_item(
            guidance_state,
            overview,
            mode_config,
            debug_sink=debug_sink if full_dbg else None,
        )
        if reshape_item:
            guidance_branch = "in_target_shear_congestion_reshape"
            if full_dbg:
                debug_sink["guidance_branch"] = guidance_branch
                debug_sink["selected_action_type"] = reshape_item.get("action_type")
                debug_sink["selected_title"] = reshape_item.get("title_main")
                debug_sink["actionable_target_band_winner_exists"] = True
                debug_sink["actionable_target_band_winner_family"] = "compound"
                debug_sink["actionable_target_band_winner_subfamilies"] = ["geometry", "bottom_reo", "shear"]
                debug_sink["actionable_target_band_winner_change_lines"] = list(
                    reshape_item.get("guidance_change_lines") or []
                )
                debug_sink["optimal_short_circuit_blocked"] = True
                debug_sink["optimal_short_circuit_block_reason"] = "in_target_shear_congestion_reshape"
                debug_sink["surfaced_guidance_branch"] = guidance_branch
                debug_sink["surfaced_selected_action_type"] = reshape_item.get("action_type")
                debug_sink["surfaced_selected_title"] = reshape_item.get("title_main")
            elif min_dbg:
                debug_sink["guidance_branch"] = guidance_branch
                debug_sink["selected_action_type"] = reshape_item.get("action_type")
                debug_sink["selected_title"] = reshape_item.get("title_main")
            return [reshape_item]
    _overview_utils_for_bending_cleanup = dict((overview or {}).get("utils") or {})
    _bending_util_for_cleanup = _parse_util_value(_overview_utils_for_bending_cleanup.get("bending"))
    _worst_util_for_bending_cleanup = _parse_util_value(
        (overview or {}).get("worst_util") or (overview or {}).get("governing_util")
    )
    _bending_is_overview_worst_for_cleanup = bool(
        _bending_util_for_cleanup is not None
        and _worst_util_for_bending_cleanup is not None
        and abs(float(_bending_util_for_cleanup) - float(_worst_util_for_bending_cleanup)) <= 1e-9
    )
    _bending_cleanup_governs = bool(
        str(governing_action or "").strip().lower() == "bending"
        or str(overview.get("governing_check") or "").strip().lower() == "bending"
        or str(overview.get("governing_family") or "").strip().lower() == "bending"
        or _bending_is_overview_worst_for_cleanup
    )
    if (
        _overview_required_checks_acceptable(overview)
        and not bool(overview.get("any_fail"))
        and _bending_cleanup_governs
    ):
        try:
            _bending_cleanup_worst = _parse_util_value(
                overview.get("worst_util") or overview.get("governing_util")
            )
            _bending_cleanup_t_lo, _bending_cleanup_t_hi, _ = _resolved_efficiency_target_band(
                mode_config,
                goal=_design_optimisation_goal(guidance_state),
            )
        except Exception:
            _bending_cleanup_worst = None
            _bending_cleanup_t_lo = None
        if (
            _bending_cleanup_worst is not None
            and _bending_cleanup_t_lo is not None
            and float(_bending_cleanup_worst) < float(_bending_cleanup_t_lo) - 1e-9
        ):
            bending_cleanup_item = _bending_only_target_band_cleanup_item(
                guidance_state,
                overview,
                mode_config,
                debug_sink=debug_sink if min_dbg else None,
            )
            if isinstance(bending_cleanup_item, dict):
                bending_cleanup_evidence = dict(bending_cleanup_item.get("candidate_search_evidence") or {})
                bending_cleanup_item["guidance_intent"] = "efficiency_tightening"
                bending_cleanup_item["local_cleanup_candidate"] = True
                if min_dbg:
                    debug_sink["guidance_branch"] = "bending_below_target_bending_only_cleanup"
                    debug_sink["selected_action_type"] = bending_cleanup_item.get("action_type")
                    debug_sink["selected_title"] = bending_cleanup_item.get("title_main")
                    debug_sink["family_utils"] = dict((overview or {}).get("utils") or {})
                    debug_sink["materially_overprovided_families"] = ["bending"]
                    debug_sink["governing_family"] = "bending"
                    debug_sink["local_cleanup_search_ran"] = True
                    debug_sink["local_cleanup_search_exhaustive"] = True
                    debug_sink["safe_local_cleanup_count"] = int(
                        bending_cleanup_evidence.get("safe_executor_backed_candidates_count") or 1
                    )
