    _visible_utils_for_exact_blockers: dict = {}

    def _restamp_exact_blocker_current_utils(_source):
        _restamped = {}
        for _family_key, _raw_blocker in dict(_source or {}).items():
            if not isinstance(_raw_blocker, dict):
                _restamped[_family_key] = _raw_blocker
                continue
            _blocker = dict(_raw_blocker)
            _family = str(_blocker.get("family") or _family_key or "").strip().lower()
            _visible_family_util = _parse_util_value(_visible_utils_for_exact_blockers.get(_family))
            if _family in {"bending", "shear"} and _visible_family_util is not None:
                _previous_current = _parse_util_value(_blocker.get("current_util"))
                _previous_failed = _parse_util_value(_blocker.get("failed_check_util"))
                if (
                    _previous_current is not None
                    and abs(float(_previous_current) - float(_visible_family_util)) > 1e-9
                ):
                    _blocker.setdefault("attempted_util", float(_previous_current))
                    _blocker.setdefault("attempted_candidate_util", float(_previous_current))
                    _blocker.setdefault("rejected_candidate_util", float(_previous_current))
                    _blocker.setdefault("rejected_candidate_failed_check_util", float(_previous_current))
                if (
                    _previous_failed is not None
                    and abs(float(_previous_failed) - float(_visible_family_util)) > 1e-9
                ):
                    _blocker.setdefault("attempted_util", float(_previous_failed))
                    _blocker.setdefault("attempted_candidate_util", float(_previous_failed))
                    _blocker.setdefault("rejected_candidate_util", float(_previous_failed))
                    _blocker.setdefault("rejected_candidate_failed_check_util", float(_previous_failed))
                _blocker["current_util"] = float(_visible_family_util)
                _blocker["starting_util"] = float(_visible_family_util)
                _blocker["failed_check_util"] = float(_visible_family_util)
            _restamped[_family or _family_key] = dict(_blocker)
        return _restamped

    def _restamp_exact_blocker_maps_in_evidence(_evidence):
        _restamped_evidence = dict(_evidence or {})
        for _map_key in (
            "exact_blockers_by_family",
            "post_click_exact_blockers_by_family",
            "cleanup_evidence_by_family",
            "post_click_cleanup_evidence_by_family",
        ):
            if isinstance(_restamped_evidence.get(_map_key), dict):
                _restamped_evidence[_map_key] = _restamp_exact_blocker_current_utils(
                    _restamped_evidence.get(_map_key)
                )
        return _restamped_evidence

    cached_items, cached_debug, cache_hit = _get_cached_design_guide_guidance(fingerprint)
