    def _cached_summary_html_for_first_paint() -> tuple[str | None, dict]:
        """Return proven previous summary HTML for stable reruns only."""
        cache = dict(st.session_state.get("_final_publication_summary_card_html_cache") or {})
        reuse_keys = dict(cache.get("reuse_keys") or {})
        cached_html = cache.get("summary_cards_html")
        current_result_cache_hash = _stable_final_publication_hash(
            st.session_state.get(RESULT_CACHE_KEY) or {}
        )
        current_results_version = int(st.session_state.get("results_version", 0) or 0)
        reasons: list[str] = []
        if _first_paint_landing_expected:
            reasons.append("landing_shell_expected")
        if _design_guide_sidebar_debug_enabled():
            reasons.append("debug_mode_enabled")
        if st.session_state.get(DESIGN_GUIDE_COMPONENT_APPLY_IN_FLIGHT_KEY):
            reasons.append("post_click_apply_in_flight")
        if st.session_state.get("_pending_inputs_apply_refresh"):
            reasons.append("pending_apply_refresh")
        if st.session_state.get("inputs_dirty") or st.session_state.get("_inputs_dirty"):
            reasons.append("inputs_dirty")
        if st.session_state.get("_force_inputs_widget_reseed_once"):
            reasons.append("widget_reseed_pending")
        if not isinstance(cached_html, str) or not cached_html.strip():
            reasons.append("missing_cached_summary_html")
        if int(reuse_keys.get("results_version") or -1) != current_results_version:
            reasons.append("stale_results_version")
        if str(reuse_keys.get("result_cache_hash") or "").strip() != current_result_cache_hash:
            reasons.append("stale_result_cache_hash")
        if bool(reuse_keys.get("show_landing")):
            reasons.append("cached_landing_summary")
        debug = {
            "first_paint_cached_summary_reused": not reasons,
            "bypass_reason": "stable_result_hash" if not reasons else ",".join(sorted(set(reasons))),
            "current_results_version": current_results_version,
            "current_result_cache_hash": current_result_cache_hash,
            "cached_results_version": reuse_keys.get("results_version"),
            "cached_result_cache_hash": reuse_keys.get("result_cache_hash"),
            "affects_visible_wording": False,
            "affects_cta": False,
            "affects_apply_payload": False,
            "affects_family_runtime": False,
            "product_behavior_changed": False,
        }
        if reasons:
            return None, debug
        return str(cached_html), debug

